var extra_symptoms_default = /*#__PURE__*/ JSON.parse("[{\"id\":\"x-brakes-lights-via-7-way-intermittent\",\"system\":\"Running gear\",\"title\":\"Brakes / lights via 7-way intermittent\",\"blurb\":\"From the October 2026 guide tables. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"Contacts & ground\",\"action\":\"Clean contacts, dielectric grease, check ground; spray 7-way with contact cleaner every 90 days.\"}]},{\"id\":\"x-2027-door-won-t-close-latch-properly\",\"system\":\"Body & gear\",\"title\":\"2027 door won't close/latch properly\",\"blurb\":\"From the October 2026 guide tables. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"Level & stabilizers\",\"action\":\"Out-of-level trailer twists the shell; check door fit before/after extending stabilizers (stabilizers are not for leveling).\"},{\"look\":\"Striker / screen door\",\"action\":\"Striker bolt is adjustable; screen door rubbing can push the door; sheared rivets on interior door skin mean the door came open.\"},{\"look\":\"Sticking window\",\"action\":\"Never force: unlatch, slide a nylon wedge with 303 Protectant around the seal from a corner, then clean and treat seal.\"}]},{\"id\":\"x-tankless-weak-or-cycling-truma-aquago-girard\",\"system\":\"Water heater\",\"title\":\"Tankless Weak or Cycling (Truma AquaGo / Girard)\",\"blurb\":\"From the October 2026 guide tables. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"Pressure & flow\",\"action\":\"Needs ≥45 psi and ≥0.9 GPM; use pump on weak campground pressure.\"},{\"look\":\"Faucet & aerator\",\"action\":\"Open fully; clean aerator; lower set temp.\"},{\"look\":\"Air intake / altitude\",\"action\":\"Clear intake; above 3,500 ft slow the flow.\"},{\"look\":\"Scale\",\"action\":\"Decalcify (AquaGo tablets only); Girard reset/descale per model.\"}]},{\"id\":\"x-alde-not-heating-noises-fluid-loss\",\"system\":\"Alde\",\"title\":\"Alde not heating / noises / fluid loss\",\"blurb\":\"From the October 2026 guide tables. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"Glycol level low\",\"action\":\"Top with Alde fluid only; wrong fluid forms white precipitate.\"},{\"look\":\"Pump speed\",\"action\":\"~2–2.5 normal; 5 for flush.\"},{\"look\":\"Plug icon missing\",\"action\":\"No 120 V: breaker, GFCI, plug.\"},{\"look\":\"Air lock\",\"action\":\"Run speed 5 ~15 min or use yellow air-gap valves; bleed rear to front.\"},{\"look\":\"3020 Flow leak\",\"action\":\"Short-cycling pump, wet under unit; temporary bypass with flex + SharkBite; 3030 Plus eliminates the Flow.\"},{\"look\":\"Repeated loss\",\"action\":\"Flow, bleeder or fitting leak.\"},{\"look\":\"Burner\",\"action\":\"Power-cycle, check fuses; clogged exhaust stops burner.\"}]},{\"id\":\"x-furnace-won-t-run-lights-then-quits\",\"system\":\"Furnace\",\"title\":\"Furnace won't run / lights then quits\",\"blurb\":\"From the October 2026 guide tables. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"Fuse / reset\",\"action\":\"Cycle battery disconnect.\"},{\"look\":\"Blink code\",\"action\":\"1 = airflow, 2 = flame, 3 = lockout, steady = controller; reset board breaker.\"},{\"look\":\"Sail switch / gas\",\"action\":\"Must close; ~11 in. WC; pigtail collapse.\"},{\"look\":\"E1 thermostat\",\"action\":\"Reseat RJ11; broken blue wire on some Classics.\"},{\"look\":\"Call test\",\"action\":\"Jump blue wires at furnace.\"},{\"look\":\"Ignites then shuts off\",\"action\":\"Flame sensor; limit trips = restricted return or weak blower.\"}]},{\"id\":\"x-a-c-problems\",\"system\":\"Air conditioning\",\"title\":\"A/C problems\",\"blurb\":\"From the October 2026 guide tables. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"Filters/coils/drain\",\"action\":\"Clean; thaw an iced coil fully.\"},{\"look\":\"Intermittent start\",\"action\":\"Failing capacitor: match µF; power off and short terminals first.\"},{\"look\":\"Compressor runs, warm air\",\"action\":\"Reversing valve, low charge or weak capacitor — tech.\"},{\"look\":\"E1\",\"action\":\"Reseat RJ11 at roof boards.\"},{\"look\":\"Breaker trips with heater on\",\"action\":\"Switch water heater to gas.\"},{\"look\":\"Interior drip\",\"action\":\"Clear drain; never caulk interior opening.\"},{\"look\":\"Soft-start smell/heat (2024 Trade Wind)\",\"action\":\"Recall 24V-656 — stop using and contact Airstream/dealer.\"}]},{\"id\":\"x-lp-problems\",\"system\":\"Propane\",\"title\":\"LP problems\",\"blurb\":\"From the October 2026 guide tables. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"Weak flame\",\"action\":\"Appliances off, reconnect, open valve slowly (resets excess-flow); liquid in low spot; collapsed pigtail.\"},{\"look\":\"Pressure\",\"action\":\"~11 in. WC; lock-up ≤14 in. WC.\"},{\"look\":\"Leak search\",\"action\":\"Soapy water only; never flame.\"},{\"look\":\"LP detector alarm\",\"action\":\"Ventilate, LP off, find source before reset.\"},{\"look\":\"Quick-connect appliance\",\"action\":\"Remove its own regulator or it will starve.\"},{\"look\":\"Regulator age\",\"action\":\"8–10 yr life; 2021 Winntec recall.\"}]},{\"id\":\"x-alde-boiler-reaches-set-temperature-but-the-coac\",\"system\":\"Alde\",\"title\":\"Alde: boiler reaches set temperature but the coach does not heat (Airstream TSB 170)\",\"blurb\":\"From the October 2026 guide tables. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"Expansion tank level (30' Classic: behind a false panel\",\"action\":\"above the toilet) Fill to MAX with the same glycol; do not overfill. Airstream glycol 360371-100 (1 qt) / -200 (5 gal); distilled water only as a short-term emergency (freeze risk)\"},{\"look\":\"Air in the loop\",\"action\":\"Run the circulation pump continuously about 15 min, then stop and bleed at the bleed points; repeat until heat returns\"},{\"look\":\"2018–early 2020 Classic\",\"action\":\"Service Bulletin #180: fluid replaced with glycol 360371-201C and two grounds added — ask the dealer whether it was done on a used trailer\"}]},{\"id\":\"x-brakes-grab-are-harsh-or-one-wheel-drags\",\"system\":\"Running gear\",\"title\":\"Brakes grab, are harsh, or one wheel drags\",\"blurb\":\"From the October 2026 guide tables. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"Controller\",\"action\":\"Threshold voltage too high, or a controller that jumps to high output, makes brakes harsh/grabby; re-set the controller gain\"}]},{\"id\":\"x-norcold-12-v-fridge-freezer-cold-fridge-warm\",\"system\":\"Refrigerator\",\"title\":\"Norcold 12 V fridge: freezer cold, fridge warm\",\"blurb\":\"From the October 2026 guide tables. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"Settings and airflow\",\"action\":\"Owners advise not to run both at 5, and to keep the shelf vents at the back clear and not overpack. Some models have a storage tab in the door latch that holds the door open — check it is set to travel/closed (owner-reported)\"},{\"look\":\"Fan does not run\",\"action\":\"Owners traced this to the \\\"eyebrow\\\" control board behind the top control panel (other suspects: evaporator fan, thermistor); one owner replaced it and fridge temps went back to the 30s °F (owner-reported)\"},{\"look\":\"New trailer\",\"action\":\"A 2026 Globetrotter 30RBQ owner says the dealer replaced the fridge at delivery — test it on the PDI (owner-reported)\"}]},{\"id\":\"x-entry-door-hard-to-close-or-the-upper-lock-jams\",\"system\":\"Body & gear\",\"title\":\"Entry door hard to close, or the upper lock jams\",\"blurb\":\"From the October 2026 guide tables. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"Level\",\"action\":\"The door is over-bent on purpose to seal; a twisted (unlevel) trailer makes it bind. Level side to side and front to back, and check the fit before/after lowering stabilizers\"},{\"look\":\"Striker & screen door\",\"action\":\"The striker bolt is adjustable; a misadjusted screen door can push on the main door\"},{\"look\":\"Door blew open before\",\"action\":\"Check for sheared rivets on the inside skin of the door\"},{\"look\":\"Lube\",\"action\":\"Paraffin/grease in striker pockets, a little household oil on locks and hinge pins\"},{\"look\":\"Jammed shut (NHTSA, 2021 Globetrotter)\",\"action\":\"Owner reported the upper lock jammed with the door closed — keep a second exit plan (escape window) and service the lock at the first sign of stiffness\"}]},{\"id\":\"x-pump-stopping-mid-shower-an-irvwpc-pump-controll\",\"system\":\"Plumbing\",\"title\":\"Pump stopping mid-shower (IRVWPC timeout)\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Pump stopping mid-shower: an IRVWPC pump controller can shut the pump off on a run-time leak-protection timeout. Another owner suggests checking for pump overheating and the Wago connections. IRVWPC TANK mode is reported at about 41 psi.\"}]},{\"id\":\"x-water-heater-girard-tankless-gswh-2-firing-techn\",\"system\":\"Water heater\",\"title\":\"Girard tankless: firing, diverters, and replacements\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Manufacturer + owner-reported. Water heater — Girard tankless (GSWH-2): firing, technique, diverters, replacements (cont.) Manual values: Girard GSWH-2 owner's manual: minimum 0.60 gpm per hot-water faucet, from a pressurized cold-water source of 45 psi or greater; 125 psi max operating; start-up sensing about 0.70 gpm ±10%. The factory inlet regulator is 50 psi per the 2027 owner's manuals. The service manual notes about 20 minutes of continuous run time. Water heater — Girard tankless (GSWH-2): firing, technique, diverters, replacements (cont.) Symptoms: the burner fires only above minimum flow, so cold water runs first (about 15 s on 2021 trailers; 40–50 s or a minute-plus at the galley in other reports; others report 5–20 s) and a cold slug returns after every pause in a navy shower. Mixing in cold drops flow and shuts it off (a 2023 International's 95 °F minimum still gave 113 °F). Other reports: pump pulsing with the shower-head button, grey tanks filling faster, cold blasts when another tap opens or the toilet flushes, 99–102 °F at most with tank water below 50 °F, temperature creep during showers (J.Silvers, an owner), a 2024 heater overshooti\"}]},{\"id\":\"x-winterizing-air-vs-antifreeze\",\"system\":\"Plumbing\",\"title\":\"Winterizing — air vs antifreeze\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Owners disagree. One warns that after an air-only blowout, \\\"even a few droplets left in the faucets or toilet valve could destroy them\\\". He uses antifreeze. Another owner's Airstream dealer told her air plus antifreeze in the drains only was enough. Follow your owner's manual.\"}]},{\"id\":\"x-one-owner-found-the-three-way-winterizing-valve-\",\"system\":\"Leaks\",\"title\":\"One owner found the three-way winterizing valve \\\"leaking air into the pump when the\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. One owner found the three-way winterizing valve \\\"leaking air into the pump when the pump kicked on\\\" (seen through clear tubing). Another had it installed backwards: antifreeze came out of the fresh-tank drain instead of the faucets.\"}]},{\"id\":\"x-a-50-f-rv-antifreeze-rating-is-a-burst-protectio\",\"system\":\"Plumbing\",\"title\":\"A \\\"-50 °F\\\" RV antifreeze rating is a burst-protection rating\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. A \\\"-50 °F\\\" RV antifreeze rating is a burst-protection rating. The fluid goes slushy well above that: one owner says it \\\"would freeze at zero\\\" but protects against bursting. Slushy antifreeze in a jug at 12 °F is therefore expected. One owner calls it \\\"anti-burst\\\". Another disputes the physics, but agrees burst protection holds to about -50 °F.\"}]},{\"id\":\"x-reported-practice-regulate-air-to-blow-out-air-m\",\"system\":\"Plumbing\",\"title\":\"Reported practice: regulate air to blow-out air max 50 psi (30 psi on Globetrotter)\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Manufacturer + owner-reported. Reported practice: regulate air to blow-out air max 50 psi (30 psi on Globetrotter) per the 2027 owner's manuals. Start at the faucet farthest from the city inlet, work toward the nearest, and repeat at least twice. Also blow out the water heater and the hose outlet. Use an oil-free compressor or an oil/water separator. Owners disagree on air-only vs. adding antifreeze: one says the first water before pink appears shows water remains after blowing.\"}]},{\"id\":\"x-one-owner-pumps-antifreeze-through-to-displace-t\",\"system\":\"Plumbing\",\"title\":\"One owner pumps antifreeze through to displace the water, then immediately drains and\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. One owner pumps antifreeze through to displace the water, then immediately drains and blows the lines. He says this saves money and spring flushing, and reuses the collected antifreeze in the traps.\"}]},{\"id\":\"x-if-plumbing-has-frozen-turn-the-pump-off-and-don\",\"system\":\"Plumbing\",\"title\":\"If plumbing has frozen: turn the pump off and don't force frozen valves 25FB and others (\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. If plumbing has frozen: turn the pump off and don't force frozen valves. The original poster's metal low-point valve \\\"broke off in my hand right at the base\\\". Open the drains and let it thaw. Several owners advise not repairing until after the thaw. Then test with air, not water: pressurize to about 45 psi with all outlets closed, watch for a pressure drop and listen for hissing at the pump, water heater, fridge, sinks and showers. On the 25FB the drains are between the street-side wheels.\"}]},{\"id\":\"x-a-nylon-drain-plug-whose-head-separated-sprayed-\",\"system\":\"Plumbing\",\"title\":\"A nylon drain plug whose head separated sprayed water out of the heater door\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. A nylon drain plug whose head separated sprayed water out of the heater door. Owners carry spares, use Teflon tape and hand-tighten only; over-tightening strips threads. For any leak: pump off, city water off, open the low-point drains and a faucet, then fix.\"}]},{\"id\":\"x-for-air-only-winterizing-open-every-hot-and-cold\",\"system\":\"Plumbing\",\"title\":\"For air-only winterizing, open every hot and cold outlet one at a time and do the Owners\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. For air-only winterizing, open every hot and cold outlet one at a time and do the whole round twice. That means faucets, toilet, sprayers, indoor and outdoor showers, low-point drains and the water heater drain. Owners say low spots still hold water: \\\"you never really get that last drop out\\\". Listen for gurgling to find the problem spots. Several owners add antifreeze afterwards as insurance.\"}]},{\"id\":\"x-antifreeze-fed-in-at-the-pump-inlet-does-not-rea\",\"system\":\"Plumbing\",\"title\":\"Antifreeze fed in at the pump inlet does not reach the city-water inlet line or the\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Antifreeze fed in at the pump inlet does not reach the city-water inlet line or the black-tank flush line. Blow both out, or push antifreeze in with a small hand pump. One owner reports a \\\"pro\\\" winterizer missed the outside shower.\"}]},{\"id\":\"x-owners-strongly-advise-against-putting-antifreez\",\"system\":\"Plumbing\",\"title\":\"Owners strongly advise against putting antifreeze in the fresh-water tank because it\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Owners strongly advise against putting antifreeze in the fresh-water tank because it is very hard to flush out. One owner flushed for days and still tasted it in the first water from the tap. Use the pump bypass, or the pump inlet, instead.\"}]},{\"id\":\"x-remove-the-under-sink-or-sippy-faucet-filter-bef\",\"system\":\"Plumbing\",\"title\":\"Remove the under-sink or \\\"sippy\\\" faucet filter before winterizing\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Remove the under-sink or \\\"sippy\\\" faucet filter before winterizing. Owners report that antifreeze strips the dye and can spoil the filter. One owner says the filter holder bypasses the flow when the filter is removed; another installed a shut-off valve instead. One owner replaces the filter every spring because of possible bacterial growth.\"}]},{\"id\":\"x-water-heater-draining-plug-atwood-equipped-trail\",\"system\":\"Water heater\",\"title\":\"Water heater — draining & plug Atwood-equipped trailers\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Disagreement. Owners cite Atwood documentation that about 2 quarts left below the drain hole is OK. Others urge removing as much water as possible. Everyone agrees an undrained heater can be damaged (\\\"arguably the most expensive hit\\\"). Remove the plastic plug with a 15/16 in socket on an extension; an adjustable wrench rounds off the head. Use a little Teflon tape when refitting.\"}]},{\"id\":\"x-fresh-tank-draining-fully\",\"system\":\"Plumbing\",\"title\":\"Fresh tank — draining fully\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. One owner says the fresh tank has a flat bottom, so if the trailer leans away from the drain (often the passenger side), the valve will not empty it, and the pump can't either. Open the drain valve and drive around, or raise the drain side. As long as any water left is below the pump line, he says freeze damage is unlikely.\"}]},{\"id\":\"x-blow-out-winterizing-commonly-missed-spots\",\"system\":\"Plumbing\",\"title\":\"Blow-out winterizing — commonly missed spots\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Owners report that air alone did not clear the pump inlet filter (\\\"resulting in a cracked filter\\\"), so remove it or push antifreeze through it. Other spots owners name: the water left in the pump (disconnect the inlet and outlet and run it a few seconds), the back-flow valve inside the city-water inlet, the toilet feed and its plastic valve, the outside shower, the sink sprayer, and the black-tank flush. On many water heaters you must pull a plug, not just open a valve, to drain them fully. A 20FB owner found a valve under the water heater only by following the trailer's own manual.\"}]},{\"id\":\"x-winterizing-what-can-burst-and-antifreeze-types-\",\"system\":\"Plumbing\",\"title\":\"Winterizing: what can burst, and which antifreeze\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. One owner explains that freezing water damages anything \\\"constrained\\\": pipes, connectors, valves, traps, faucets, the pump, back-flow preventers and shower heads. Tanks with a small amount of water are generally not at risk. \\\"You can get every bit as much damage from lines freezing at 28F as at -28F\\\" if the trailer sits below freezing for days. Pink RV antifreeze comes in a cheaper alcohol-based type with a strong odor and a propylene-glycol type that is \\\"almost odourless\\\" and easier to flush.\"}]},{\"id\":\"x-compressor-choice-for-blow-out\",\"system\":\"Plumbing\",\"title\":\"Compressor choice for blow-out\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Owners stress air volume (CFM) over pressure: \\\"you simply can't get the air flow (CFM)\\\" from small inflators for a no-antifreeze winterization, so you may leave water behind. With an oil-bath compressor, fit particulate and coalescing filters to protect the potable lines. A 2019 Sport 22 owner says the short line between the fresh tank and the factory 3-way winterizing valve (under the sink cabinet) gets missed; Airstream's instructions say to run the pump until the tank is dry and to lower each end of the trailer when draining.\"}]},{\"id\":\"x-winterizing-owner-procedures\",\"system\":\"Plumbing\",\"title\":\"Winterizing — owner procedures (\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Manufacturer + owner-reported: Methods vary: one owner blows the lines at 40 psi; a ’99 Safari 27 owner says the factory told him blowing out was enough; blow-out air max 50 psi (30 psi on Globetrotter) per the 2027 owner's manuals. Others add antifreeze. Pump antifreeze from the jug, not the fresh tank, and use a heater bypass, or gallons are wasted filling the heater. Bypass check: most bypass fittings need more than one valve turned. If no antifreeze reaches the hot taps, a valve was missed. If pink pours from the heater drain plug, antifreeze is going into the heater. Do not use an oil-lubricated compressor on fresh-water lines. An Excella 500 hose-reel fitting was the one part that had to be replaced after a trip; blow out the reel hose too.\"},{\"look\":\"More\",\"action\":\"Winterizing — owner procedures (2002–2006 sticky) (cont.) If the tank-fed pump will not pull antifreeze, check whether the tank pickup is above the remaining fluid and whether the city-water cap is tight. Black tank: just drain it; no antifreeze or chemical needed (one owner). Keep a stiff fresh-tank drain valve free with silicone spray. A ’74 Argosy owner re-plumbed a “rat’s nest” into an easy winterizing system.\"}]},{\"id\":\"x-winterizing-by-blowing-out-lines-pressure-and-mi\",\"system\":\"Plumbing\",\"title\":\"Winterizing by blowing out lines — pressure and missed points\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Manufacturer + owner-reported: Pressure: blow-out air max 50 psi (30 psi on Globetrotter) per the 2027 owner's manuals; keep one valve open. Do not connect compressed air to the black-tank flush fitting unless the manual allows it (risk of blowing debris into the vent); others say the tanks are vented, so pressure is not an issue (disagreement). Commonly missed and then broken: kitchen sprayer, outdoor shower, toilet valve, toilet rinse hose, filtered-water spigot and its cartridge (remove; antifreeze ruins carbon filters). Blow out with the heater bypass in normal, then again in bypass, to clear both paths. 2013 Classic owners: no pump bypass from the factory (pump beside the wheel well); screw a hose onto the pump inlet instead. One owner had Airstream turn a backwards-mounted pump around.\"},{\"look\":\"More\",\"action\":\"Winterizing by blowing out lines — pressure and missed points (cont.) Heater drain: owners swapped the nylon plug for a brass drain valve (1/2 in.); one Camco valve leaked; plumber’s putty on threads suggested. One owner reports a JC tech said the factory only blows the lines (no antifreeze).\"}]},{\"id\":\"x-winterizing-and-storage-bypass-check-valve-low-p\",\"system\":\"Plumbing\",\"title\":\"Winterizing and storage: bypass check valve, low-point drains, de-winterizing\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported: Newer single-valve heater bypasses rely on a check valve that can stick open and let antifreeze into the heater (pink dripping from the heater). Owners report tapping it frees it; one says replace it. 2012 27FB: the two brass petcocks are the hot/cold low points; the white valve drains the fresh tank (owner of a Classic; another owner guessed similarly). Antifreeze can sit in the low points all season if they are not opened when flushing. JC techs told one owner that blowing the lines, draining the heater and a cup of antifreeze in the traps and tanks is enough (no antifreeze in PEX). Leaving the trailer plugged in all winter can boil flooded batteries dry; check water often or use a smart charger/maintainer.\"},{\"look\":\"More\",\"action\":\"Winterizing and storage: bypass check valve, low-point drains, de-winterizing (cont.) De-winterizing: flush each line on city water, purge low points, then fill the heater; foaming fades with time. Weak hot-water flow only: clean the screen in the bypass/mixer valve (2011 Classic), or faucet strainers; the hot line may be air-bound. Leaks: a paper towel shows small drips; tighten 1/8 turn at a time.\"}]},{\"id\":\"x-grey-water-backing-up-into-the-shower\",\"system\":\"Plumbing\",\"title\":\"Grey water backing up into the shower\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported: Symptom: after draining a full galley sink, grey water rises in the shower pan and the tank monitor jumps to “full”, then both slowly fall back while the tank is only ~1/4 full. Owners explain the monitor misreads because the tank is pressurised. Many owners see a brief “geyser” or gurgle in the shower when they pull the plug on a full sink with the grey valve closed; it clears within seconds or minutes. A diagram the starter got from Airstream showed the grey tank venting through the drain plumbing, with an air-admittance valve (AAV) at the galley, rather than a separate direct tank vent (owners note older line drawings differed).\"},{\"look\":\"More\",\"action\":\"Grey water backing up into the shower (cont.) Airstream’s prescribed fix was a an owner waterless valve added after the sink P-trap. The owner says it stopped the small backups, but it did not cure his long slow drain. That was cured when an independent shop blew out the vent pipe; the cause was never confirmed (presumed vent blockage). Disagreement: several owners argued the an owner treats a symptom and that the real causes are a blocked or submerged vent or inlet pipe, a stuck AAV, or an uphill shower drain line (one owner found exactly that). Checks owners suggest: remove the roof vent cap and look or run a hose down the vent pipe; check the trailer is level (raising the front cured one owner’s backup); drain the sink slowly; keep the shower drain plug in; leave the grey valve open on full hookups.\"},{\"look\":\"More\",\"action\":\"Grey water backing up into the shower (cont.) Tank monitors: calibrate them yourself (instructions in the owner’s packet); owners treat them as a rough guide only; one owner was told at the factory to coat the sensor contacts with dielectric grease. One 2011 FC 30 owner found the grey and black valve handles mislabelled.\"}]},{\"id\":\"x-low-point-drain-valves-finding-them-missing-hand\",\"system\":\"Plumbing\",\"title\":\"Low-point drain valves — finding them, missing handles\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Manufacturer + owner-reported: Location varies: on some recent models they are two small brass ball valves (hot and cold) under the belly near the tank enclosure, shown in the manual’s plumbing section. On older (1985/1994) trailers they were plastic valves inside compartments. Some owners did not know theirs existed. One 2023 owner opened only the fresh-tank drain, and a ’14 Sport owner found no mention in the manual. Handles fall off: owners on 2018, 2020 and 2023 trailers found handle screws or nuts loose or missing (not thread-locked). One sourced M4-0.70×10 bolts and notes the valve cannot be removed with the handle on, because of belly-pan clearance. Check and tighten them.\"},{\"look\":\"More\",\"action\":\"Low-point drain valves — finding them, missing handles (cont.) Workarounds: a wrench on the square stem, or a filed screwdriver in the slot (’10 Classic). Or unscrew the valve, holding the elbow with a second wrench so it doesn’t twist, and fit a new ball valve with a close nipple. One owner leaves the low-point valves open all winter. Another drains with them open, then blows out each tap, the low points and the toilet (blow-out air max 50 psi (30 psi on Globetrotter) per the 2027 owner's manuals ), opens the water-heater relief valve, and puts antifreeze in the traps.\"}]},{\"id\":\"x-pex-replumbing-cinch-clamps-vs-copper-crimp-ring\",\"system\":\"Plumbing\",\"title\":\"PEX replumbing: cinch clamps vs copper crimp rings, brass vs plastic fittings, valves\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Cinch (stainless) clamps: one tool for several sizes, fits tight spots, cheaper tool; hard to remove (cut at an angle with a hacksaw or Dremel). Copper crimp rings: larger tool, and the tool must be checked with its go/no-go gauge; one owner's borrowed, out-of-adjustment crimper leaked at every joint. Rings must not be re-crimped. Owners report years of leak-free use with either. A fitting that still turns after crimping is normal; a connection with the ring cut off will not hold.\"},{\"look\":\"More\",\"action\":\"PEX replumbing: cinch clamps vs copper crimp rings, brass vs plastic fittings, valves (cont.) Brass fittings are preferred over plastic by most owners; plastic elbows can snap under pull. Scratched fittings leak; keep them clean, and wash only with dish soap. Leaks on one new trailer's factory joints were traced to rings set too far from the tube end; collar rings with an inspection hole help. Use a proper PEX cutter for square cuts. Non-oxygen-barrier PEX is fine for potable water. Keep PEX out of sunlight and away from hydrocarbons. Minimum bend radius per the manufacturer is about 6x tube size; use bend supports for tight 90s.\"},{\"look\":\"More\",\"action\":\"PEX replumbing: cinch clamps vs copper crimp rings, brass vs plastic fittings, valves (cont.) Valves: owners suggest quarter-turn ball valves (less restriction than compression stops) at the toilet, city inlet, water heater cold feed and hot and cold drains; ball-type stop valves with a 3/8 in compression outlet connect PEX straight to single-lever faucets. A toilet isolation valve lets you keep using the trailer if the toilet fails. Push-fit (SharkBite) and nylon flare fittings are tool-free options for road repairs; one owner found patching with them cost more than a full replumb.\"}]},{\"id\":\"x-outdoor-shower-replacing-the-stock-faucet-and-wa\",\"system\":\"Plumbing\",\"title\":\"Outdoor shower: replacing the stock faucet and wand (Dura Faucet), access to the\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Complaints about the stock unit: low flow (one owner saw what looked like a reducing washer in the hose), a short hose, and a wand stowed against the knobs that opened the hot tap in transit and dripped.\"},{\"look\":\"More\",\"action\":\"Outdoor shower: replacing the stock faucet and wand (Dura Faucet), access to the (cont.) Swap: owners fitted an aftermarket Dura Faucet with quick-disconnect hose, reusing the box where the spacing matched; 5 to 30 minutes. Access to the back of the box varies: behind the drawers under the stove (19 FC), the kitchen drawer (Caravel 16), the closet floor (Sport 22), under the bathroom sink (FC 23D). On an FC 25FB the plumbing sits under the shower, so that owner pulled the box from outside; a 2008 27FB owner also did it all from outside. Removing the box may need the butyl seal gently broken with a cloth-covered tool; on some an aluminium plate catches the siding, and on the FC 23D the faucet slips out from inside without removing the box.\"},{\"look\":\"More\",\"action\":\"Outdoor shower: replacing the stock faucet and wand (Dura Faucet), access to the (cont.) Check for leaks: one owner forgot to tighten the cold side and sprayed water inside; another pressurized and waited 30 minutes before closing up. Stock units were found missing rubber gaskets. Reuse the gasket if sound (one owner planned a bead of sealant). Reliability: one owner's later black plastic replacement leaked; another moved to a metal hose that fits the box. Aftermarket boxes may be smaller and have no lock. Winterizing: connect the hose and drain the shower lines; a stock wand burst in a Texas freeze. Using the outdoor shower saves grey-tank capacity when boondocking.\"}]},{\"id\":\"x-city-water-pressure-the-built-in-inlet-regulator\",\"system\":\"Propane\",\"title\":\"City water pressure: the built-in inlet regulator vs an external regulator; hose bursts\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Manufacturer + owner-reported. Owners have seen campground pressure of 80–100+ psi, and pressures that change from day to night. Several had the plastic built-in inlet regulator leak or blow out, causing a hidden leak and floor-rot risk; it is a cheap part on the inside wall behind the city-water inlet. Many fit an external brass regulator at the spigot (owners set adjustable ones to about 50–60 psi) to protect the hose and filter too. Owners say cheap fixed regulators restrict flow (one found this starved a tankless heater); adjustable ones with a gauge flowed better. Built-in regulator rating: the factory inlet regulator is 50 psi per the 2027 owner's manuals. One 2023 owner says it is only a limiting valve that leaks inside rather than out of the weep hole, and does not regulate.\"},{\"look\":\"More\",\"action\":\"City water pressure: the built-in inlet regulator vs an external regulator; hose bursts (cont.) Hose bursts: DISAGREEMENT. Some blame pressure; another owner argues water trapped by the spigot backflow valve expands in the sun, and recommends an accumulator or keeping an air bubble in the water heater. Turn the spigot off when leaving the site. You can top up the fresh tank through the outdoor shower hose while on city water. A badly overfilled fresh tank can burst and damage the floor.\"}]},{\"id\":\"x-water-pump-cycling-with-the-taps-off-and-city-wa\",\"system\":\"Plumbing\",\"title\":\"Pump cycling with the taps off, or city water filling the tank\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. After a freeze, an owner's pump cycled about every 10 seconds, and on city water the fresh tank overfilled out of its fill. Several owners and shops pointed to the pump's internal check valve; a replacement Shurflo pump (installed in about 30 minutes) fixed both. He was told the pump head is not sold separately. Others found a cracked pump head, a cracked clear strainer housing next to the pump, a leaking low-point drain, an outside shower, or a plastic elbow under the bed. Finding leaks: watch for drips with the system pressurized, listen for hissing, use a moisture meter on the carpet and plywood, and check behind the toilet. Turn the pump off at night and when away until it is fixed.\"},{\"look\":\"More\",\"action\":\"Water pump cycling with the taps off, and city water backflowing into the fresh tank (cont.) Adding a separate check valve: DISAGREEMENT about placement. One owner put one on the pump outlet (arrow away from the pump) to stop city water backflow; another notes that this will not stop cycling caused by the pump's own valve, and that a valve before the pump can make priming harder.\"}]},{\"id\":\"x-water-pressure-accumulator-thermal-expansion-pum\",\"system\":\"Plumbing\",\"title\":\"Water pressure accumulator: thermal expansion, pump cycling, and the water-heater air\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Why owners add one: the campground backflow valve and the pump's check valve make a closed system, so water-heater expansion can spit from the T&P valve or find weak fittings. A small Shurflo accumulator (about 1 litre, factory 30 psi charge) evens out flow and cycling. Installs: on the cold supply under the bath sink with a braided connector, at the pump outlet, or on a tee. Mount it fittings-down so it drains when winterizing. A 1994 owner found one factory-fitted behind the kitchen cabinets; another found one under the sink without knowing it.\"},{\"look\":\"More\",\"action\":\"Water pressure accumulator: thermal expansion, pump cycling, and the water-heater air (cont.) DISAGREEMENT for variable-speed pumps: Shurflo says its Revolution pump does not need one, and owners with a 2007 Safari and a 2013 trailer saw no benefit; a 27FB owner says one smoothed the surging of his variable-speed pump. Restore the water-heater air pocket from time to time (pump off, open the T&P valve until it stops); the air is gradually absorbed, after which the T&P drips. Water dripping from the water-heater compartment can be combustion condensate. A 2002 Classic owner's dealer fitted a curbside relief valve. Owners leave the pump and water heater off when away or asleep after a fitting burst at night.\"}]},{\"id\":\"x-water-heater-drain-plug-tools-sealing-anode-rods\",\"system\":\"Leaks\",\"title\":\"Water-heater drain plug: tools, sealing, anode rods, broken stub\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Water-heater drain plug: tools, sealing, anode rods, broken stub (cont.) Plug size: owners report 15/16 in; others needed 1 in (one owner found the OEM Atwood plug and an aftermarket plug differ). Use a 6-point socket on a 6–8 in extension (the gas line is in the way), a flex-head ratchet, or a crow's foot. Carry spare plastic plugs and Teflon tape, and replace a scuffed or cracked plug. If a plug leaks, chase the threads with a tap; one owner with persistent leaks switched to an aluminium hex-key plug. DISAGREEMENT over whether metal plugs seize galvanically; some prefer plastic only. Easier draining: a petcock, or two 1/2 in 45° street ells plus a quarter-turn boiler valve and a hose. Others prefer the plain plug so they can flush the tank with a wand. Water-heater drain plug: tools, sealing, anode rods, broken stub (cont.) Anode rod: DISAGREEMENT. Owners say Atwood tanks (steel with an aluminium lining) need none, and one warns against adding zinc unnecessarily; Suburban steel tanks use one; one owner fits an anode each season and sees it erode. Winterizing: air through the city inlet plus the opened drain clears the tank; the bypass is only needed when using antifreeze. Atwood says water below the drain can freeze harmlessly (one owner, 17 years). Several owners p\"}]},{\"id\":\"x-water-heater-support-block-under-the-6-gallon-at\",\"system\":\"Water heater\",\"title\":\"Water-heater support block under the 6-gallon Atwood: check it and reinforce it\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. On a 2018 23CB, the small wooden block under the 6-gallon Atwood water heater, held by one #8 screw, worked loose after 2,200 miles. The tank sagged and tore the side skin, and the dealer replaced the skin under warranty. Others found the same flimsy one-screw block, and a 2016 FC 25 owner found it lying loose. The Atwood installation manual says the tank must be fully supported; one owner noted the factory block sat under the angled rear face rather than the centre.\"},{\"look\":\"More\",\"action\":\"Water-heater support block under the 6-gallon Atwood: check it and reinforce it (cont.) Fixes: a planed hardwood strip glued in under the centre of the tank; a full-width plywood T-support screwed down, with ratchet straps over the top; spray foam between the tank and the floor, with plastic sheet over the tank so it can still be removed (about one can). Access is usually from above, through the bed platform. DISAGREEMENT on the foam: one owner asked whether foam added a fire risk; another judged it did not because the tank already has a foam jacket and the burner vents outside. Check with the heater maker before foaming.\"},{\"look\":\"More\",\"action\":\"Water-heater support block under the 6-gallon Atwood: check it and reinforce it (cont.) Owners also reinforced fixings that rattle loose on washboard roads: microwave and oven screws, latches (toothpick-and-filler in stripped holes, brass ball latches), the angle bracket behind the counter, dinette table screws, and cabinet hinges through-bolted into hollow spaces. Jack nuts (expanding, like a Molly bolt) suit thin material better than sheet-metal screws.\"}]},{\"id\":\"x-replacing-a-water-heater-atwood-vs-suburban-tank\",\"system\":\"Water heater\",\"title\":\"Replacing a water heater: Atwood vs Suburban tanks and PrecisionTemp tankless\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Tank units: owners rate 6- and 10-gallon Atwood and Suburban DSI heaters as similar in cost and quality. Atwood tanks are aluminium; Suburban tanks are porcelain-lined steel with a replaceable anode. One owner has replaced several Atwood tanks but never a Suburban, and another avoided aluminium because of corrosion. Measure the existing cutout to choose a model: one owner measured a 1976 Bowen opening at about 16.5 x 16 inches against about 16 x 15.5 inches for a 10-gallon Atwood. Owners recommend electronic ignition, and units with an extra 120 V element heat up faster.\"},{\"look\":\"More\",\"action\":\"Replacing a water heater: Atwood vs Suburban tanks and PrecisionTemp tankless (cont.) Tankless: owners used the PrecisionTemp RV-500. It uses propane and 12 V only while hot water is flowing, which suits boondocking. Fitting it into an Atwood 6-gallon opening meant enlarging the skin opening, which one owner cut with a small hand nibbler; the door can be flush or surface-mount. The Twin-Temp Jr. vents through the floor and also provides hydronic heat, but is overkill for hot water alone. Owners warn against fitting household or uncertified propane tankless heaters in an RV: use only units built and certified for RVs, as these must withstand road vibration and your insurer may deny claims otherwise. Tankless gives unlimited showers on hookups, but when dry camping the fresh-water tank is the limit.\"}]},{\"id\":\"x-no-or-weak-hot-water-after-de-winterizing-mixing\",\"system\":\"Plumbing\",\"title\":\"No or weak hot water after de-winterizing (mixing-valve screen)\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Symptoms: after de-winterizing, a short burst of hot water followed by warm or cold water and weak flow on the hot side. Airstream reportedly confirmed this is usually a clogged mixing valve and said they get many such calls in spring. No or weak hot water after de-winterizing (mixing-valve screen) (cont.) Cause: calcium and debris clog the inlet screen in the brass anti-backflow piece that threads into the tank. Relieve the pressure, disconnect the water lines, unscrew the valve body, then remove the brass piece with a 1-1/16 inch socket or wrench (one owner recalled 1-1/8 inch). Owners cleaned it in white vinegar or CLR, and with fine steel wool. Often the screen alone needs cleaning, and owners keep the old valve as a spare. It can be very tight; on reassembly use thread tape, not plumber's putty, because bits of putty ended up in a faucet. One owner found the wooden support block under the tank had shifted, leaving the tank hanging from its skin screws; re-wedge it if you have the access panel off. No or weak hot water after de-winterizing (mixing-valve screen) (cont.) Prevention: an inlet filter and a water softener, and checking the screen every year. DISAGREEMENT: some owners using a filter still have to clean it every year. Keep the valve: the tank thermostat runs at ab\"}]},{\"id\":\"x-reaching-a-buried-water-pump-to-winterize-adding\",\"system\":\"Plumbing\",\"title\":\"Reaching a buried water pump to winterize; adding a bypass (\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Manufacturer + owner-reported. Access (2007-era 25' FBs): the pump sits beside the wheel well under the wardrobe, inlet facing the inaccessible side. Reach it through the storage space under the fridge by removing the thin fibreboard back panel (4 screws or small brads) and moving the heat duct aside. If you cut a closet-floor access hole, wiring and plumbing sit right below it.\"},{\"look\":\"More\",\"action\":\"Reaching a buried water pump to winterize; adding a bypass (2007–08 FB layouts) (cont.) Bypass: an owner removed the four pump screws and moved the pump about 2\\\" inboard to fit a Camco valve; an owner instead cut the inlet PEX and fitted a Camco 3-way with a Flair-It coupling (leave enough tube for full insertion); Wasafari moved the pump forward on a soft PEX tail so the strainer lifts out. Pump inlet and strainer threads were reported as 1/2\\\" male pipe thread. one owner’s push-fit 3-way on the suction side drew air, and an Airstream tech said not to use push-fit fittings there. DISAGREEMENT on whether the Camco's small bore restricts flow; an owner and another owner noticed none (two seasons).\"},{\"look\":\"More\",\"action\":\"Reaching a buried water pump to winterize; adding a bypass (2007–08 FB layouts) (cont.) Method (DISAGREEMENT): dealers and an Airstream/factory tech drain the tanks, blow out the lines and put antifreeze only in the traps and toilet; an owner pumps antifreeze through everything; the 2007–08 manuals make that optional extra protection. Blow-out air max 50 psi (30 psi on Globetrotter) per the 2027 owner's manuals. Don't skip the manual's step of disconnecting the pump inlet and running the pump until the last water (about 1/2 cup) comes out: 2airishuman skipped it and cracked the pre-pump strainer cup. Remove the kitchen faucet's carbon cartridge before antifreeze. Don't put antifreeze in the fresh tank (the taste lingers); woodedareas and Gene did and planned hard spring flushing. A water-heater bypass uses three valves on the tank; drain from the bottom with the relief valve open.\"},{\"look\":\"More\",\"action\":\"Reaching a buried water pump to winterize; adding a bypass (2007–08 FB layouts) (cont.) Noise: one owner fitted braided flexible lines and turned the pump, cutting noise and vibration; another switched to a variable-speed ShurFlo (4.0 gpm).\"}]},{\"id\":\"x-upgrading-the-outside-shower-box-to-stainless\",\"system\":\"Plumbing\",\"title\":\"Upgrading the outside shower box to stainless\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. The plastic shower boxes warp so the door won't stay shut, and the paint peels. Owners repainted them or used aftermarket boxes (e.g. Thetford 36765), but one owner found the RV-store boxes worse than Airstream's. Airstream's stainless outside-shower kit (part 39768W) includes the box, door, valves, hose and head. Installers had to enlarge the opening slightly and file the inside of the door to clear the screw heads. Early kits came with gasket sheet you cut to fit, and the door seal was stiff at first. One installer's improvements: fasteners every 2\\\" instead of every 4\\\" to stop the skin buckling, and corner screws to stop the corners curling. The hose connection is hard to reach. The slotted latch needs a coin; a keyed cylinder can be fitted.\"},{\"look\":\"More\",\"action\":\"Upgrading the outside shower box to stainless (cont.) Uses owners mention: rinsing off after dumping tanks, washing kids and dogs.\"}]},{\"id\":\"x-ventless-vent-free-tankless-water-heaters-inside\",\"system\":\"Water heater\",\"title\":\"Ventless (vent-free) tankless water heaters inside a trailer\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Not safe inside the trailer: despite its oxygen-depletion sensor (ODS), the unit puts all its combustion products and moisture into the living space, and the seller's own literature calls for active ventilation for boats. One installer also said the installation packet states venting is necessary. Several owners recommend an RV-rated unit that vents outside (PrecisionTemp, Girard) and working CO, propane and smoke alarms. This guide does not recommend installing an unvented gas appliance inside the living space; follow your manual and the appliance maker's instructions. Altitude: an ODS can shut the burner off at high elevation because there is less oxygen in the air. Check the rated maximum (one owner quoted 9,200 ft).\"},{\"look\":\"More\",\"action\":\"Ventless (vent-free) tankless water heaters inside a trailer (cont.) Correction: catalytic heaters also burn propane and use up oxygen, so ventilate when running one. Practical notes: the Excel needs batteries for ignition and is easy to drain by tilting it or blowing it out; do not have propane or batteries connected while antifreeze is in the lines. A household tankless heater needed yearly descaling and soot cleaning (home use, not an RV).\"}]},{\"id\":\"x-cracked-shower-pan-gelcoat-repair\",\"system\":\"Plumbing\",\"title\":\"Cracked shower pan: gelcoat repair\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. DISAGREEMENT over the material: Airstream told one owner its showers are fibreglass from Ultra/Glas of Lakeville, Indiana, while older-trailer owners believe theirs are ABS. One recommended a flexible epoxy (West System G/flex) for plastic, because ordinary polyester resin may not bond. Identify your pan before choosing a product.\"},{\"look\":\"More\",\"action\":\"Cracked shower pan: gelcoat repair (cont.) Ultra/Glas sold a colour-matched gelcoat kit. The first attempt flaked off within five months. The maker's tech blamed poor preparation and too little hardener; the correct ratio is 1 tablespoon of gelcoat to 1/8 teaspoon of hardener (not two drops). The second attempt held: rough up the area well, clean off all dust, soap and grease, apply thickly, dab with a stick to recreate the texture, and finish per the gelcoat maker’s instructions (do not sand until cured as directed). Solvent wipe omitted — hazardous-chemical tip excluded per owner policy; see exclusions log. That owner said Ultra/Glas would also do the repair free at its plant if you brought the trailer.\"},{\"look\":\"More\",\"action\":\"Cracked shower pan: gelcoat repair (cont.) Do not drill the pan to stop a crack. A hole in the gelcoat is an owner method, not a repair to copy. If water can reach the floor, this is a shop job. Other products owners mentioned: Elmer's tub and shower repair kit, epoxy putty plus a two-part epoxy tub refinishing kit. One owner warned that water can get through unnoticed and cause rot, so seal the whole area. Inland RV sold replacement pans.\"}]},{\"id\":\"x-moen-1222-shower-cartridge-replacement\",\"system\":\"Plumbing\",\"title\":\"Moen 1222 shower cartridge replacement\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Symptoms: the hot water only dribbles, the shower drips when off, or there is no temperature control. Replacement cartridge: Moen 1222. Several owners got free replacements from Moen's lifetime warranty. Tools: a 7/64\\\" hex key for the handle, the plastic tool supplied with the cartridge, and often a cartridge puller because old cartridges stick. Brace the valve if you pull hard, so you don't bend the pipes or crack the shower wall. Before fitting the new cartridge, Moen suggested soaking the valve body in vinegar (a bag taped around it) and scrubbing it. Use the silicone grease supplied. Orientation: the instructions say to put the stem notch at the top, but in one trailer it had to go at the bottom. If hot and cold are reversed, turn the stem 180°.\"},{\"look\":\"More\",\"action\":\"Moen 1222 shower cartridge replacement (cont.) Retaining clip behind the shower wall (the rear corner bath in 2005 19' trailers): press the valve in, rotate the white plastic collar about 90° to its largest notch, then pull the valve forward using the mounting screws until the clip clears the wall. Hold the collar with a wire so it doesn't drop into the wall. Others removed the whole valve from the back, through a cabinet or access panel. If a cartridge won't seat, check for debris and mineral build-up, and check that it is the right model.\"}]},{\"id\":\"x-weak-outside-shower-flow\",\"system\":\"Plumbing\",\"title\":\"Weak outside shower flow\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Check the simple things first: a kinked hose (one trailer was delivered with one), a quarter-turn stop valve on the branch line, and the on/off collar on the back of the factory spray head, which is easy to miss. One owner traced a slow drain line to a screw driven into the cold water pipe under the stove. The usual cause is a flow restrictor. Airstream sent one owner an identical replacement, which was just as weak, but the indoor 2.5 gpm head worked fine outside. Do not drill out a restrictor. Removing the plastic restrictor from the head loses the on/off feature. Keep the part if you take it out. Either change is owner practice, not a factory fix. Several fitted an Oxygenics head instead. One 2017 owner found the Empire mixer's small outlet hole limiting and wanted a different faucet.\"},{\"look\":\"More\",\"action\":\"Weak outside shower flow (cont.) Showering outside: a pop-up privacy tent and mats help, and it saves grey-tank space when boondocking. Check the park's rules; one owner advised no soap at Long Key State Park because it is next to protected water.\"}]},{\"id\":\"x-low-flow-shower-heads-and-tankless-heaters\",\"system\":\"Water heater\",\"title\":\"Low-flow shower heads and tankless heaters\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Manufacturer + owner-reported. One owner recommended the High Sierra 1.25 gpm RV handheld head (solid brass, trickle valve, foam grip). It screws onto the stock hose, and one owner's bucket test confirmed 1.25 gpm. Other heads owners liked: Oxygenics Fury, PIH, and a Delta 1.75 gpm. Water budget: one couple used 6–6.5 gallons a day in total, which made a 39-gallon tank last 6–7 days of boondocking. DISAGREEMENT and caution with tankless heaters. Girard GSWH-2 owner's manual: minimum 0.60 gpm per hot-water faucet, from a pressurized cold-water source of 45 psi or greater; 125 psi max operating. A Truma AquaGo is said to activate at 0.4 gpm and has a small reservoir. In July 2026 an owner reported his Girard would not come on with the 1.25 gpm head but ran with the head removed. Check your heater's minimum flow.\"},{\"look\":\"More\",\"action\":\"Low-flow shower heads and tankless heaters (cont.) The brass head weighs about 16 oz. Store it on the shower floor (in a mat, caddy or tub) when towing, because it could crack the shower if it falls. A pin-mount swivel adapter lets you hang other heads on the peg. (A High Sierra employee posted in the thread; their product details are not used here.)\"}]},{\"id\":\"x-tracing-a-leak-under-the-shower\",\"system\":\"Leaks\",\"title\":\"Tracing a leak under the shower\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Causes owners actually found: a loose or leaking city-water inlet behind the shower wall; a cracked plastic pressure regulator at the inlet, which leaked as the water heater warmed and raised pressure (Jackson Center replaced it with a metal one); a cracked shower mixing valve or its outlet (one valve was not fixed firmly to the structure); and a cracked drain elbow where the shower floor lacked support. Step-by-step tests: run a garden hose down the drain only, then into the pan, then over the walls (this tests the drain, the pan-to-drain seal and the wall seams in turn). Then test the supply on the pump only versus city water, and hot only versus cold only.\"},{\"look\":\"More\",\"action\":\"Tracing a leak under the shower (cont.) Another test is to shower with city water disconnected and the tank and pump on; one owner's floor stayed dry, which pointed to the inlet. Another started with a cold heater, capped the inlet and ran the pump; a leak then means the inlet. Other checks: tape over the seam between the upper and lower shower sections, recaulk where the walls meet the pan, and slide dry cardboard into the space to see where water first appears. To get out a stuck access panel, screw two screws partway into its holes and pull on them.\"}]},{\"id\":\"x-shower-pan-seat-what-s-under-it-using-the-space-\",\"system\":\"Plumbing\",\"title\":\"Shower-pan seat: what is under it, and how to clean it\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. What is under the seat varies: the wheel well, the black tank (on one Safari), the water heater (on one Excella 25), or the outside-shower and water-inlet plumbing (on one 27). Inland RV said the seat often covers the wheel wells. A full-width seat was disliked by one 2009 International 28 owner; others found it useful for washing feet and shaving, and said it helps ageing joints. Using the space: one Bambi owner fitted a screw-out boat deck plate in the side of the seat, which gives watertight storage and an inspection port for leaks. Inland RV warned that labour to fit a full-size pan would likely cost more than the pan.\"},{\"look\":\"More\",\"action\":\"Shower-pan seat: what's under it, using the space, and cleaning (cont.) Cleaning: owners use automotive spray wax or Walbernize on the walls but not the textured floor, which would get slippery. One 2014 FC 20 owner sprays a daily shower cleaner after each use to prevent soap-scum build-up.\"}]},{\"id\":\"x-torn-shower-door-sweep\",\"system\":\"Plumbing\",\"title\":\"Torn shower-door sweep\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Replacement sweeps are available from Airstream or Woodland Airstream; cut them to length and slide them in. One owner found the bottom frame stuck even after removing the screw. The sweep tears because the door sags and rubs the sill. A dealer said replacing it is pointless unless the door is raised first, and Jackson Center fits a shim under the door. Owners added nylon or UHMW shims siliconed near the pivot, a longer piece taped on for travel, or a credit-card shim on the factory block. DISAGREEMENT: many owners removed the sweep after it tore repeatedly and saw little or no water on the floor (they use a bath mat). Others prefer to keep it, and one owner saw moisture damaging the finish below the door.\"},{\"look\":\"More\",\"action\":\"Torn shower-door sweep (cont.) Alternative: the Nautilus retractable door by Stoett; a 2002 19' came with a similar roll-up door from the factory.\"}]},{\"id\":\"x-see-also-refs-433-and-441\",\"system\":\"Plumbing\",\"title\":\"Door rattle blocks, without re-drilling the jamb\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Airstream will send a free kit of two plastic blocks that screw into the frame, one under the hinge and one on the latch side. One owner noted do not re-drill the door jamb. Pre-drilling a jamb is an owner modification, not a factory repair. Cheaper option: a 1/2\\\" plastic spacer from a hardware store, set with silicone or epoxy in the corner track while the door is lifted. Top-hinge fixes: one 2005 Classic owner pinned the sliding block in the top frame with a roll pin through a 1/8\\\" hole so it can't move. Others fitted longer stainless screws, and do not raise or re-drill the jamb. That is an owner modification. For travel, one owner clamps the door to the frame with a small C-clamp.\"},{\"look\":\"More\",\"action\":\" (cont.) Replacing the door: Stoett Nautilus roll-up doors are light and don't open into the hall. One owner advised ordering it nearly as tall as the opening because the top support is required. Others used a Sterling pivot door or a double shower curtain. One owner found the frame couldn't be removed without tearing up the woodwork.\"}]},{\"id\":\"x-tankless-water-heaters-lifestyle-and-boondocking\",\"system\":\"Water heater\",\"title\":\"Tankless water heaters: lifestyle and boondocking notes\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. An owner: Atwood's tankless units (OD-45 and OD-50, 2011) used technology licensed from Precision Temp. Precision Temp also offered a floor-vented unit, which suits vintage owners who want no side vent. Output temperature depends on the inlet water temperature and the flow rate; reduce the flow for hotter water. Gas DC loads are similar to a DSI tank heater. Winterising: there is no tank, so no bypass is needed, but pink RV antifreeze must flow through the heat exchanger, or drain it.\"},{\"look\":\"More\",\"action\":\"Tankless water heaters: lifestyle and boondocking notes (cont.) Freezing risk (DISAGREEMENT): an owner worried that the exposed small copper lines could freeze on a cold drive or overnight. An owner said the Precision Temp has a cold-weather protection function. An owner rejected one model because it fires every so often in freezing weather. An owner: the pump may cycle more without a tank's air bubble, so he added a small surge tank. The switch saved about 42 lb on the street side. An owner reported a 4-month trip with long showers without emptying two 30 lb tanks. One parts dealer said failures usually mean replacing the whole unit. Owner-reported.\"},{\"look\":\"More\",\"action\":\"Tankless water heaters: lifestyle and boondocking notes (cont.) one owner’s on-demand unit gives consistent hot water only with the tap left running. An owner: low flow won’t trigger these heaters, and a recirculating system won’t fix that. one owner’s Girard needed 20–30 s at full flow and shut off at reduced flow; his trailer was refitted with a Truma AquaGo because a tank heater wouldn’t fit. Workarounds: Jeff Bittner sets 115°F, saves the cold run-off in a bucket and uses it to flush the toilet, lasting 5+ days boondocking; an owner trickles the outside shower instead of filling grey; an owner and irush installed a Showermiser recirculating valve (irush: plus tools; needs access to the fresh-water fill line). An owner and Kittycatcat heat water on the stove.\"},{\"look\":\"More\",\"action\":\"Tankless water heaters: lifestyle and boondocking notes (cont.) DISAGREEMENT: several prefer tank heaters for dry camping (An owner, Kittycatcat, Scott an owner, Ronyx); One Smith likes her new tankless and saves the warm-up water.\"}]},{\"id\":\"x-cleaning-the-shower-and-controlling-moisture\",\"system\":\"Plumbing\",\"title\":\"Cleaning the shower and controlling moisture\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. The most common routine was to squeegee or towel-dry the walls, seat and door after each shower. Owners said this keeps humidity and mildew down; ventilate, and dry towels outside the trailer. Cleaners owners used: Simple Green (with a sponge), white vinegar for hard-water deposits, vinegar and Dawn in a spray bottle, a Magic Eraser with a little Dawn, Mrs. Meyer's cleaners, Clean Shower or Tilex daily sprays, ECOS shower cleaner, and Aldi's Radiance spray on the glass. Gel-Gloss cleaned the walls while one trailer was winterised, followed by Rain-X on the glass. an owner advised checking that any cleaner is compatible with the plumbing seals and gaskets. One full-timer found bar soap left heavy residue; switching to body wash fixed it. Another owner poured Simple Green and hot water down the drains every few days.\"}]},{\"id\":\"x-water-pump-access-on-flying-cloud-28\",\"system\":\"Plumbing\",\"title\":\"Water pump access on Flying Cloud 28 (\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. The pump sits behind a four-screw panel at the bottom of the wardrobe but extends well under the fridge. On some 2015 FC 28s it is behind the electrical panel, which was moved under the fridge mid-year according to one owner’s report of Jackson Center's reply. A dealer took about 30 minutes to reach it to winterise. Fix: a mobile tech extended the pump's outlet line about 1.5 ft to under the wardrobe and fitted a 3-way winterising valve. A 2016 owner found the same layout.\"},{\"look\":\"More\",\"action\":\"Water pump access on Flying Cloud 28 (2015–2016) and 22FB (cont.) If you can't reach the pump inlet: drain the fresh tank, bypass and drain the water heater, remove the under-sink filter, and put about 5–6 gallons of RV antifreeze in the fresh tank to pump through each faucet. Blow out the black-tank flush, whose inline valve can freeze and crack. In spring, fill and drain the tank and flush the lines on city water. Or blow the system out with compressed air. A 2013 22FB owner's pump inlet was clamped under wire harnesses, so it could not be disconnected as the manual says.\"}]},{\"id\":\"x-see-also-ref-459-turn-the-pump-off-for-travel\",\"system\":\"Plumbing\",\"title\":\"Turn the water pump off for travel\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Why: a kitchen faucet opened in transit on a 2005 Classic and flooded the floor. Options: (1) a 12 V LED with a built-in resistor wired across the pump leads, which lights whenever either of two 3-way switches powers the pump; (2) a lighted mini rocker switch (A2-38 green or A2-23 red, quoted as a direct fit in the Micropulse panel); (3) a 12 V blue LED glued behind the Micropulse front panel. Micropulse fascia: pry from the notch at the top, because prying from the sides bends the bottom tabs. Lighted switches need a ground to terminal 3, spliced to the panel's black ground or the trailer body. One owner found the green ground capped off and unconnected. Two owners had to reverse the yellow and green wires so the light showed only when the pump was on.\"},{\"look\":\"More\",\"action\":\" (cont.) Low-tech options: a pre-tow checklist, removing the sink cover when travelling, or switching the panel lights on whenever the pump is on as a reminder.\"}]},{\"id\":\"x-6-gallon-tank-heater-capacity-showers-and-lighti\",\"system\":\"Water heater\",\"title\":\"6-gallon tank heater: capacity, showers and lighting faults Trade Wind (new Atwood 6 gal)\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported (tankless comparison). Most owners say 6 gallons is enough with \\\"navy\\\" showers (water off or reduced while soaping). Continuous running gives roughly 4–5 minutes, longer with warm incoming water; one 2005 Safari owner reported over 10 minutes on hookups. Back-to-back showers may need a few minutes of recovery. Running gas and electric together speeds recovery; one owner said electric alone takes about twice as long as propane. Atwood XT models are rated as the equivalent of 9 gallons from a 6-gallon size. Low-flow aids: an Oxygenics head, a flow-control valve, or reducing (not stopping) flow so the temperature stays even. One owner removed a clogged flow restrictor in a 30-year-old head.\"},{\"look\":\"More\",\"action\":\"6-gallon tank heater: capacity, showers and lighting faults (cont.) Failure to light when damp (2005 25'): water from a leaking relief valve had wetted the TCO/thermostat area, and drying it with a hair dryer let it light. Another owner's fault was a corroded igniter ground screw.\"}]},{\"id\":\"x-water-heater-won-t-heat-light-wiring-and-board-f\",\"system\":\"Water heater\",\"title\":\"Water heater won't heat: light, wiring and board faults\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. On 2017–2018 models the red light at the switch normally only flickers at start-up and stays on to signal a fault (failed ignition); it is not an 'on' indicator, and it doesn't detect missing 120 V (An owner tested this). Normal sounds: a relay click for electric; on gas, an ignition click, then the gas valve and the burner. Faults owners found: a loose 120 V feed at the converter/charger on a new trailer; a half-unplugged red wire at the heater; dirty connectors fixed by cleaning the contacts; failed control boards, replaced under warranty on 2017s; and on Atwood units a blown cutoff (TCO) switch, which an owner says to check whenever a board fails. Check the propane valve is open, and that the tank is full and bled of air before using electric.\"},{\"look\":\"More\",\"action\":\"Water heater won't heat: light, wiring and board faults (cont.) Indicator ideas: a pilot-light AC switch or a 12 V LED on the switch terminal; label the switches.\"}]},{\"id\":\"x-low-hot-water-flow-at-a-single-lever-shower-valv\",\"system\":\"Plumbing\",\"title\":\"Low hot-water flow at a single-lever shower valve\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. If hot flow drops only at the shower, suspect the mixing cartridge. On Moen pressure-balancing cartridges, the balancing spool can stick after disuse: remove the cartridge, rap it on wood, and check the spool slides (An owner, a plumber). Or replace it: an owner says Moen gives a lifetime warranty to original owners. A stuck cartridge may need Moen's puller tool. Soaking it in vinegar is another option. Debris was found in one. Non-Moen original valves on old units: soak them in vinegar or replace with a residential valve if there is rear access.\"}]},{\"id\":\"x-retrofitting-a-truma-aquago-and-other-tankless-h\",\"system\":\"Water heater\",\"title\":\"Retrofitting a Truma AquaGo (and other tankless) heater\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. The AquaGo Comfort fits standard 6-gallon openings. Owners report it is easy on propane, the ECO/Comfort switch preheats a small reservoir, and it removes about 50 lb of stored water. Winterizing is lifting a drain lever (water pressure off first). Owners note the output is limited to about 120°F and not adjustable. The Plus model recirculates but needs a third (return) line; an owner advises the plain Comfort for most. Installation is via authorised installers or dealers. A 2017 FC with the heater at floor level lacked room for the flange. A&P riveted Airstream skin onto the door to match. Other units: PrecisionTemp/Atwood on-demand needs about 0.5 gpm flow and dislikes low tank pressure. Airstream told one owner it had found the PrecisionTemp's temperature unstable. An owner recommends a filter ahead of any tankless.\"}]},{\"id\":\"x-cracked-water-heater-tank-checking-the-rest-of-t\",\"system\":\"Plumbing\",\"title\":\"Cracked water-heater tank; checking the rest of the system\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Cracks came from freezing (tank not drained) and, for one owner, running it with no water. Do not weld a cracked tank: the metal around a freeze crack is stretched and weak, and it is a pressure vessel. One owner bought a complete new unit from Airstream parts (with door, 2023). Save the old controls as spares. Leak check with the heater bypassed: pressurise from city water or the pump. If the pump stays off with taps closed, there are no leaks. Bypass on one owner’s 2007: three valves by the tank, with the centre one parallel to the line and the outer two perpendicular. Support the PEX when turning stiff valves. A trickle from one tap afterward can be debris (old heater sediment) in faucets or a worn cartridge; check the handle labels match the red/white PEX.\"}]},{\"id\":\"x-water-heater-gives-only-a-minute-of-hot-water\",\"system\":\"Water heater\",\"title\":\"Water heater gives only a minute of hot water\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. The cause: the winterizing bypass valve (between the hot and cold shut-offs) had been left open, mixing cold into the hot line. An owner found it; the owner had first mistaken a check valve for the outside shower line for the bypass. Check all three valves, including whether their internal washers have come loose. Other checks that ruled things out: the electric side's manual-reset over-temperature switch; sediment (a vinegar soak — fill via the relief-valve opening with the house valves closed — then a wand flush); seating the contact thermostat with thermal paste. An owner resets an oversized air bubble by bleeding the relief valve with the heater off.\"}]},{\"id\":\"x-gravity-drinking-water-filter-berkey-in-an-airst\",\"system\":\"Plumbing\",\"title\":\"Gravity drinking-water filter (Berkey) in an Airstream\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Many owners use a Travel or Big Berkey as the final drinking-water stage after the trailer's sediment/carbon filters, and report good taste. The black filters must be primed: owners found Berkey's primer helps, and re-priming may be needed if it sits dry for a week. Scrub or brush the filters when flow slows, and get a sight-glass spigot. An optional fluoride/arsenic filter helped one owner where arsenic warnings were posted. Storage: by the sink or wall, collapsed in the shower for travel, under the dinette, or with filtered water kept in a fridge pitcher or collapsible pouches. Alternatives: a prefilter plus UV (An owner, 23FB) or RO with the discharge returned to the fresh tank.\"}]},{\"id\":\"x-shurflo-smart-sensor-pump-stops-until-power-is-c\",\"system\":\"Plumbing\",\"title\":\"Shurflo Smart Sensor pump stops until power is cycled\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. On a 2011 27FB, the Shurflo Smart Sensor 4.0 stopped at low flow and ran again only after power was cycled. Other owners had the same and fixed it with a new pump. An owner blames many elbows creating back-pressure; letting the pump reach full pressure kept it working. A pump that cycles with all taps shut points to a leak or a bad check valve. Rubber isolators under the feet reduce noise; the owner's were over-tightened. Fresh-tank filling: the vent is about straw-sized. If water spits back early, slow the fill. an owner holds the hose just outside the fill port, citing an overfill that damaged a floor.\"}]},{\"id\":\"x-replacing-a-stuck-moen-shower-cartridge\",\"system\":\"Plumbing\",\"title\":\"Replacing a stuck Moen shower cartridge\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Erratic temperature, then a handle that would only run cold, was fixed by a new cartridge on a 2012 International Serenity. Remove the flat retaining clip, then pull the cartridge straight out. It takes real force: owners used strong pliers, locking pliers, or a Moen puller tool. The valve body is plumbed with crimped PEX and can't come out without cutting the lines. Use a genuine Moen cartridge; owners say knock-offs fit poorly or fail early. an owner 2012 used Moen 1222. An owner cites the 2012 EB parts manual listing the valve as Moen TL2391. Owners also mention brass cartridges and a light coat of plumber's silicone grease. Compare the old cartridge before buying. An owner reports Moen supplies replacement cartridges free under its lifetime warranty.\"},{\"look\":\"More\",\"action\":\"Replacing a stuck Moen shower cartridge (cont.) Parts manuals for your model may list fixture part numbers; one International CCD owner's documents name Kindred as maker of the round stainless galley sink.\"}]},{\"id\":\"x-drinking-water-filtration-options-19-full-timer-\",\"system\":\"Plumbing\",\"title\":\"Drinking-water filtration options\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Common setups: a blue Camco or Clear2O hose filter for sediment, sometimes with an under-sink filter or a Berkey/Brita for drinking. Others use ClearSource 2–3-stage canisters (heavy, about 17–24 lb) or a 5-micron sediment plus 0.5-micron carbon pair. An owner says the basic Camco only stops particles of about 20 microns and up. Some just drink bottled water. Practices: run the campground spigot about 10 seconds before connecting; ask the campground for its water-quality report. If water tastes bad everywhere, sanitise the tank and lines. an owner uses 3/4 cup of bleach per 50 gallons, sits it overnight, then flushes three times; an owner pre-mixes bleach in a gallon of water first. Carbon filters sitting unused may need replacing, or use bacteria-resistant KDF media. Owner-reported.\"},{\"look\":\"More\",\"action\":\"Drinking-water filtration options (cont.) Options used: a hose-end inline filter at the spigot (Camco or similar), also used when filling the fresh tank; the factory under-sink microstrainer/carbon filter (Classic); a Berkey gravity purifier; a carbon filter plus water softener; and supermarket RO water in a jug. Caution from drboyd: carbon filters remove chlorine, so don't fill the tank with unchlorinated filtered water and let it sit. Fill at home with chlorinated water, and use the carbon filter only on a direct city-water connection. one owner’s Camco inline filter clogged within six months.\"}]},{\"id\":\"x-very-hot-output-from-an-atwood-dsi-water-heater-\",\"system\":\"Water heater\",\"title\":\"Very hot output from an Atwood DSI water heater (and too-cool output)\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Atwood DSI heaters have no user temperature knob. Contact thermostats on the tank (about 130–145°F primary, with a higher ECO cut-off) set the temperature. Owners keep the mixing valve mid-range; some like the heat because it stretches 6 gallons with cold inlet water. DISAGREEMENT: the 2011 owner considered it dangerously hot. Options mentioned: have the dealer check it, or fit Atwood's lower-temperature (130°F) thermostat. A sensor seated well on clean metal reads correctly. Atwood's adjustable thermostat 93105 fits older gas-only units, not the newer gas/electric DSI. Tepid water: first check that the bypass valve (middle of the H) is closed, then the thermostats and their contact. On gas/electric units, the electric pair is on the back of the tank. Work with the power off.\"}]},{\"id\":\"x-replacing-an-original-water-heater\",\"system\":\"Water heater\",\"title\":\"Replacing an original water heater\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Replace like for like: Atwood and Suburban differ, and 6- and 10-gallon units need different openings. Owners report Bowen units are Atwood, and that the same-size Atwood fitted the old opening. The original silver door can usually be reused, or the new white door painted to match. You need access inside and out; it is riveted or screwed in and sealed at the flange. Uwe used RV putty tape plus a bead of Vulkem. Tip: start the water-line nuts before fixing the flange, or you'll have to break the new seal. An owner found rot under his old heater, so check the floor once it is out. A removed heater left an opening open to rodents. Gas/electric units run on either source; electric eats into your 30-A capacity. An owner reports Atwood voids its warranty if a Hott Rod element is fitted.\"}]},{\"id\":\"x-tankless-heater-placement-warm-up-waste-and-the-\",\"system\":\"Water heater\",\"title\":\"Tankless placement, warm-up waste, and the Showermiser\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Owners say a 15-ft hot run won't lose much heat. The real issue is the cold water run to waste before hot arrives: one owner’s 2021 on-demand takes about 45 seconds. an owner notes the cold water fills the grey tank. Waste-savers: a Showermiser-type valve returns the cold slug to the fresh tank or pump suction (An owner: essential when on the fresh tank). an owner uses a 12-V valve on a 15-second timer triggered by the shower light. An owner catches cold water in a collapsible bucket for flushing. Merlintiaga (Girard) says cold slugs recur at the sink whenever the tap is reopened; he recommends a Truma with its small heated tank. He doubts an unheated reservoir after the heater would help; the builder chose to try a 1-litre reservoir anyway.\"},{\"look\":\"More\",\"action\":\"ShowerMiser and diverter returns for tankless heaters (cont.) Alternatives: one owner swapped the factory valve for a diverting pressure-balance valve whose scald limit can be set (Symmons Temptrol), and another fitted a simple diverter with a braided line, saving about 3/4 gallon per shower. Check access panels before buying parts, as layouts differ by model.\"}]},{\"id\":\"x-hot-water-turns-lukewarm-after-a-few-seconds\",\"system\":\"Plumbing\",\"title\":\"Hot water turns lukewarm after a few seconds\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. The water ran hot for about 45 seconds, then barely warm, at every faucet. Suggested checks: the winterizing bypass valves are in the correct position and not leaking internally; an owner once found a washer had come off a bypass valve. A shut-off outdoor-shower head can let its mixing valve stay in play. Scale build-up in the tank may also be a cause. An owner says the Atwood's tempering (mixing) valve is a known failure point. It blends very hot tank water down to about 120°F, so a failed valve gives lukewarm output; check the outlet temperature with an IR thermometer. The owner replaced the heater with an Atwood tankless. Rmkrum fitted a PrecisionTemp in the original 6-gal opening with a slight trim, and his has built-in freeze protection.\"}]},{\"id\":\"x-water-pump-cycles-or-runs-with-no-demand-priming\",\"system\":\"Plumbing\",\"title\":\"Water pump cycles or runs with no demand; priming failures\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. one owner’s pump pulsed with no taps open after it had run dry. He replaced the pressure switch and housing, but the real cause was a low-point drain valve jarred partly open. Lessons he reports: check for leaks first (also the water-heater drain plug and relief valve, per Wayne&Sam). To bench-test a pump, feed it from a bucket of water and seal the outlet with a threaded cap; air alone won't trip the switch. An owner says stock pumps tolerate minutes of dry running. Air in the lines can also cause cycling for a while. Water pump cycles or runs with no demand; priming failures (cont.) The 25FBT pump is hard to reach under the refrigerator. Owner-reported. DISAGREEMENT: many owners say an occasional short run is normal. Suggested causes: water cooling and contracting; slight leak-back through the pump's check valve into the tank; and the air bubble in the water-heater tank shrinking as it cools. Others (stefrobrts, an owner) say a sealed system should hold all night, so any cycling means a leak. Leaks owners found: an owner found hand-tightened fittings at the pump, filter and water heater leaking on two 2013 trailers. one owner’s slow-leaking fitting dripped water out of the tank-enclosure weep holes. The heater relief valve or drain plug can also weep. Water pump cycles or runs with no demand\"}]},{\"id\":\"x-factory-under-sink-drinking-filter-part-fittings\",\"system\":\"Plumbing\",\"title\":\"Factory under-sink drinking filter: part, fittings, and alternatives\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. The filter is a Pentek GS-10RO (an owner: the -B, 1/4-in thread, on a 2016 FCFBT). The original adapters can be reused; an owner switched to brass because nylon may leak. Owners say neither this filter nor exterior Camco filters remove microbes; they are for taste and particles. Leaks: an owner cut out the filter and fitted a quarter-turn valve. James.an owner warns against over-tightening plastic fittings; their small silicone gaskets are easily damaged. Many owners skip it and use a hose-end filter for all incoming water, including when filling the tank (one owner’s dealer suggested this). An owner found no filter on his 2019 FC 27.\"}]},{\"id\":\"x-should-you-switch-to-a-tankless-heater\",\"system\":\"Water heater\",\"title\":\"Should you switch to a tankless heater? (\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. For: unlimited showers, lower weight, and quiet operation. The Truma AquaGo is smaller and, by one owner's figures, removes about 84 lb versus a full 6-gallon Atwood. The PrecisionTemp RV-550 and Atwood OD-50 are quiet, protect against freezing when power and propane are on, and work on the 12 V pump. The Truma needs at least 0.4 gpm to fire. DISAGREEMENT: an owner said tankless heaters cope badly with navy showers when dry camping. one owner’s bench test of an OD-50 showed only slight temperature swings. An owner saw no advantage over a dual-fuel 6-gallon tank.\"},{\"look\":\"More\",\"action\":\"Should you switch to a tankless heater? (2015 views) (cont.) Notes: you may need an accumulator because there is no air bubble, and good propane-regulator pressure. The existing wall switch and light can be reused. Fitting the Truma in a larger opening needed framing and reskinning by a shop.\"}]},{\"id\":\"x-water-pump-and-city-water-leave-on-or-off\",\"system\":\"Plumbing\",\"title\":\"Water pump and city water: leave on or off?\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. An owner said leaving the pump on all the time is fine, because the pressure switch runs it only when water flows. An owner leaves it on except when towing (he fitted a ShurFlo 4008 and an accumulator, which he found quieter). Most owners turn the pump off when away, at night or while towing. An owner had a cracked cross-threaded fitting flood the trailer at 3 am, and an owner had a hose-clamped previous-owner repair pump 30 gallons into the trailer. An owner found a faucet had bounced on while towing a Serenity. Several owners also shut off city water when leaving. owners noted that there is usually enough pressure left to flush the toilet with the pump off.\"},{\"look\":\"More\",\"action\":\"Water pump and city water: leave on or off? (cont.) an owner said to turn the water heater off when the water is off, since an empty tank can burn out the element or be damaged by propane heat. one owner’s 2017 pump hummed and cycled, and Jackson Center later replaced it with a quieter unit. DISAGREEMENT: owners leave the pump on while present, while an owner and others advise keeping it off when not in use.\"}]},{\"id\":\"x-water-heater-yellow-flame-and-no-ignition\",\"system\":\"Water heater\",\"title\":\"Water heater: yellow flame and no ignition\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. A water heater flame with 3 to 4 inches of yellow was caused by a spider nest in the burner baffle. Once it was cleared, the flame was blue and roared. An owner said his runs blue, and that a yellow flame suggests the air mix is out of adjustment. No light and no ignition: first check the propane is on, then the fuse, then loose wires, the igniter and the control board (Gene). Gas-system disassembly and adjustment advice in this thread was excluded from the guide (see the exclusions log).\"}]},{\"id\":\"x-leaking-shower-vacuum-breaker\",\"system\":\"Leaks\",\"title\":\"Leaking shower vacuum breaker\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. The fitting between the shower hose and the wall elbow is a vacuum breaker. It is designed to drain the hose when the water is turned off, but should not leak while the water is running. Leaking during use suggests gunk, a bad washer or a worn-out unit. An owner said the internal rubber diaphragm can develop a hole. An owner suggested soaking it in CLR as a temporary fix. To replace it, an owner used two wrenches (one to back up the wall elbow) and Teflon tape on the threads, and warned that the chrome top is plastic. An owner cited Out-of-Doors Mart part 600332, and the OP bought a replacement there. Advice to run without the vacuum breaker (a backflow device) was excluded (see the exclusions log).\"}]},{\"id\":\"x-rear-corner-shower-shifting-after-rough-roads\",\"system\":\"Plumbing\",\"title\":\"Rear corner shower shifting after rough roads\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. After rough roads, one owner’s ceiling screws pulled out and the shower rocked back about 3 in. Under the shower, two scrap-wood support blocks (3/4 in) had vibrated out of place. Access was by removing the bed (which revealed two extra storage bins) and enlarging the drain cutout. He fitted a new block, refitted the ceiling screws and resealed, and the shower was solid. He said the ceiling screws cannot carry the shower's weight, and the 3/4 in spacer only makes the shower meet the ceiling curve. Keep the block in place: an owner suggested shimming and construction adhesive, and an owner said the blocks should be glued or screwed. ventport has used expanding foam under shower stalls in houses and his Avion. An owner said air must still be able to circulate under the shower so the pipes don't freeze.\"},{\"look\":\"More\",\"action\":\"Rear corner shower shifting after rough roads (cont.) an owner suggested checking the black-tank connection for cracks after a drop like this. an owner warned water on the rear bumper can get behind the trim band and rot the floor. An owner removed the roll-up screen and used a curtain, which gave about 3 in more room at the toilet. The reply from Jackson Center isn't quoted in the thread, and owners criticised it.\"}]},{\"id\":\"x-exterior-shower-fitting-and-use\",\"system\":\"Plumbing\",\"title\":\"Exterior shower: fitting and use\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. An owner said Classics use a white plastic shower box painted silver. An owner rigged a cold-only hand shower on the outside spigot in the connections bay. Bruce B pointed to marine transom-shower fixtures. keydodge planned to fit one where hot and cold lines run behind a patch over an old furnace-vent opening.\"},{\"look\":\"More\",\"action\":\"Exterior shower: fitting and use (cont.) Uses owners reported: feet, dogs, kids, and saving grey-tank space (dkrug, afneill, an owner). An owner said rangers in several public parks have told them not to use a shower shelter, because grey water counts as sewage in many places. Check local rules. Posts about showering outdoors and draining onto the ground were not cited (see the exclusions log).\"}]},{\"id\":\"x-factory-sticker-on-the-fibreglass-shower-wall\",\"system\":\"Plumbing\",\"title\":\"Factory sticker on the fibreglass shower wall\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. The sticker in a new shower peeled off easily by fingernail for several owners (An owner, mrjkq); one owner’s carried the build date. If it doesn't peel, an owner suggested Goo Gone or WD-40 to loosen it without harming the gel coat; an owner said either works. Alphonse recommended De-Solv-it, a citrus cleaner, for the sticker, the residue and general shower cleaning. An owner suggested oil (WD-40 or cooking oil) left a few minutes, then rubbed off. DISAGREEMENT: an owner found Goo Gone harsh and preferred WD-40. An owner left the sticker in place: it gives cleaning instructions, the date of manufacture and warranty information. He said the date is when the stall was made (Ultraglas, Indiana); an owner said it is the trailer's. one owner’s sticker is still in a 1994 Classic.\"}]},{\"id\":\"x-holes-and-chips-in-the-shower-pan-flying-cloud-1\",\"system\":\"Plumbing\",\"title\":\"Holes and chips in the shower pan Flying Cloud 19CB\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Repair routes reported: professional fibreglass or gel-coat repairers such as boat shops (An owner, Joseph Sessa); JB Weld an owner on a Sport 22 chip; JB Weld WaterWeld white putty, durable but not colour-matched; a dab of white silicone for small breaks on a 2021 Globetrotter 27. An owner got a matching gel-coat kit free from the enclosure maker after Airstream supplied its name; an owner also got matching material from the maker. Check warranty with the dealer or Airstream first; owners blamed poor gel-coat bonding at manufacture. Clear Gorilla tape sealed holes temporarily for an owner.\"},{\"look\":\"More\",\"action\":\"Holes and chips in the shower pan (cont.) Prevention: leave the shower head on the pan floor or secured while towing; pad the pan with a bath rug against loose bottles. GOUSC was told the stall is installed early, so replacing it is a major job.\"}]},{\"id\":\"x-fresh-water-pump-cutting-out-on-long-runs\",\"system\":\"Plumbing\",\"title\":\"Fresh-water pump cutting out on long runs\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. one owner’s pump on a 2021 FC 30 Bunk ran hot and stopped after about 10 minutes, resetting in 1–2 minutes; it sits in the kitchen cabinet under heater ducts. He replaced it with an OEM pump. owners suspected the thermal cut-off; an owner said his Shurflo manual says the pumps are not for constant use, and suggested clearing space, moving and insulating the heater ducts, and an accumulator. An owner suggested testing with a fan on the pump. DISAGREEMENT: one owner’s 2019 FC 30 Bunk pump ran over half an hour without trouble; one owner’s 2021 FC 28RBT pump, in the same spot, never cut out (he raised the ducts to reach the strainer). jsaucier advised logging it with the dealer under warranty.\"},{\"look\":\"More\",\"action\":\"Fresh-water pump cutting out on long runs (cont.) an owner said these pumps are sensitive to contamination, so filter the water. Sparkle was on a third pump in four years, which she put down to faulty check valves.\"}]},{\"id\":\"x-upgrading-a-tankless-water-heater-to-recirculati\",\"system\":\"Water heater\",\"title\":\"Upgrading a tankless water heater to recirculating\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Options raised for a 2023 International 23FBT: a dealer told jcl a tank conversion was straightforward and recommended it; an owner said Airstream will convert to recirculating, but Truma typically won't. An owner found a Girard behaves better at about 106 °F. An owner said the 23 ft corner shower valve makes a return line very hard without opening the wall; an owner said 25 and 27 ft models have an under-floor channel for PEX. Truma AquaGo owners liked it: Montoya (30 ft GT) said priming takes about half a gallon, but it is audible at night; an owner had one fitted after a Girard. An owner uses a ShowerMiser for boondocking. DISAGREEMENT: an owner said a tank heater is better for boondocking; an owner and persistent argued for recirculating systems; an owner weighed water, power and propane.\"}]},{\"id\":\"x-water-heater-won-t-light-on-gas-works-on-electri\",\"system\":\"Water heater\",\"title\":\"Water heater won’t light on gas (works on electric)\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. The common cause was the igniter (striker) board: an owner described listening at the open door for the spark \\\"pop\\\" from the burner, not the board, and recommended getting Airstream approval for a Dinosaur board; owners (whose OEM replacement also failed) praised Dinosaur boards. one owner’s board was replaced by Airstream of Utah in 15 minutes. one owner’s 2018 Sport had three warranty board replacements. Vitothepug had it fixed under warranty and advised staying within warranty. Other causes found: an incorrectly placed ground wire, a poor igniter wiring connection that P. Wee cleaned and re-crimped, a spider nest in the tube, and a failed thermal cut-off. tbadams reset it by disconnecting the igniter's power wire.\"},{\"look\":\"More\",\"action\":\"Water heater won’t light on gas (works on electric) (cont.) Airstream asked owners to message with the last six VIN digits or email an owner@airstream.com. An owner replaced the water heaters in a 2014 Classic and 2015 International with Truma AquaGo units.\"}]},{\"id\":\"x-water-heater-works-on-gas-but-not-120-v\",\"system\":\"Water heater\",\"title\":\"Water heater works on gas but not 120 V\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. an owner, after consulting Airstream of Spokane, traced it step by step: 12 V reached the board and relay, the relay clicked, the element had continuity, and 120 V reached the relay; the fault was a bad wire connection. With the breaker off she re-crimped it and fitted ring terminals at the element. She later fitted a solid-state relay with a heat sink, mounted vertically; the heater's back was reached through a panel by the toilet. An owner said relays fail more often than elements; an owner advised carrying a spare relay. an owner believed Internationals and Classics had electric heat and Safaris propane only. An owner said running both together gives over 14 gal/hr recovery versus about 8 for either.\"}]},{\"id\":\"x-atwood-water-heater-dead-on-electric-relay-eleme\",\"system\":\"Water heater\",\"title\":\"Atwood water heater dead on electric: relay, element, board 25FB (\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. An owner found a melted relay and an open element; reaching the back on his 25FB meant pulling the heater partway, and the element took 3.5 hours with a Camco wrench. Still no AC heat: 12 V at the board's yellow pin unplugged but 0.75 V connected; an owner calculated the relay driver could supply only about 5 mA of the 75 mA needed, likely damaged by the shorted coil. A Dinosaur UIB64 board (3-year warranty) fixed it. Root cause: an improperly crimped #14 connection at the relay overheated and shorted the coil without tripping the breaker. Access: Airstream told him newer units have a removable interior panel. an owner (2012 25FB Queen) reaches it by removing the closet's bottom drawer and pulling a pressboard panel held by plastic hooks.\"},{\"look\":\"More\",\"action\":\"Atwood water heater dead on electric: relay, element, board (cont.) Board warranty: his internet vendor and Atwood each deferred; one owner’s replacement board fixed theirs. franklyfrank got a new heater from Atwood for a faulty tank weld. an owner shared Atwood's 2007 service manual (diagnosis p. 11, schematic p. 23).\"}]},{\"id\":\"x-hard-water-portable-softeners-and-spot-removal\",\"system\":\"Plumbing\",\"title\":\"Hard water: portable softeners and spot removal\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Hard water leaves stains and scale: an owner noticed crackling from the water heater at Kartchner Caverns; DAQ filters ahead of a softener to keep residue off the water-heater valve screens. Portable regenerating softeners: owners use the \\\"On the Go\\\"; it connects inline on the fill hose, is regenerated with table salt, and test strips tell you when it's exhausted (An owner: no need to regenerate at every stop). An owner regenerates every couple of months, but every other fill near Quartzsite. one owner’s Amerisoft is rated about 200 gallons per regeneration. An owner got discoloured first water after the unit sat idle and the maker replaced the resin beads; an owner says an idle softener can release some iron. Map: USGS water-hardness map.\"},{\"look\":\"More\",\"action\":\"Hard water: portable softeners and spot removal (cont.) Stains on stainless sinks: stainless cleaner or polish (McStreamy_), polishing compound, Bartender’s Friend; an owner found CLR weak.\"}]},{\"id\":\"x-suburban-st65rl-tankless-water-heater-freeze-val\",\"system\":\"Water heater\",\"title\":\"Suburban ST65RL tankless water heater: freeze-valve leak out of the middle drain tube\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Symptom: water runs out of the middle of the drain tubes behind the curb-side rear wheel whenever the pump or city water is on; it drained Bamasteelers’ entire fresh tank. On his 2025 the line from the heater splits to the pressure-relief valve and to a freeze-protection valve, both draining through one middle drain; the freeze-protection valve was defective though it had not been near freezing. Airstream had trouble identifying the part and sent the entire water heater. Running with the heater off did not stop the flow.\"},{\"look\":\"More\",\"action\":\"Suburban ST65RL tankless water heater: freeze-valve leak out of the middle drain tube (cont.) Others report the same: one owner’s dealer called his the sixth in about a month (“it’s a thing currently”) and said Suburban is quick to send replacements; another trailer at that dealer got three valves that all leaked, then a new heater from Suburban. one owner’s dealer obtained valves from Suburban ahead of time but needed his old valve back. An owner found leaking starts around 50°F and below, and the replacement leaked too; an owner says Airstream told him by phone it recognizes the issue and is working with Suburban on a new valve, and that running hot water through with recirculation closed his valve.\"},{\"look\":\"More\",\"action\":\"Suburban ST65RL tankless water heater: freeze-valve leak out of the middle drain tube (cont.) Different failure: one owner’s ST65RL leaked internally out the back of the casing; the dealer’s freeze-valve swap didn’t fix it and Airstream agreed to replace the unit. persistent had pouring from between the bottom panels that stopped after switching the heater off; the dealer found no defect. Finding which tube is which: an owner notes there are typically separate hot and cold low-point drains and suggests tracing each pipe. one owner’s similar leak was the winterization bypass valve left in the wrong position. An owner: never block the pressure-relief drain line. An owner (retired plumber) says the relief valve should drain by gravity, mounted upright rather than on its side, with an outlet not reduced in size; test by briefly pulling the lever and checking it all leaves via the drain.\"},{\"look\":\"More\",\"action\":\"Suburban ST65RL tankless water heater: freeze-valve leak out of the middle drain tube (cont.) an owner saw gaps around the low-point drains letting cold air reach the valve area and sealed them; an owner left his, reasoning the gap lets pipes move and water drain. Warranty: drwhiddon was told to bring the trailer in for re-diagnosis before a part would be sent; jordandvm (Portland, OR) also asked about poor heating above 4,000 ft; a dealer quoted a software fix; an owner points to the Globetrotter tankless-heater thread. Several owners’ road fixes that plug, remove or adjust the freeze valve are not reproduced here (they defeat a protective device).\"}]},{\"id\":\"x-descaling-a-tank-water-heater-with-vinegar-subur\",\"system\":\"Water heater\",\"title\":\"Descaling a tank water heater with vinegar Suburban tank heaters\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Don’t use a pressure washer (Lumatic, an owner); an owner suggests asking Suburban and checking with an inspection camera first. Owners fill the drained tank with vinegar (Lumatic; an owner: regular 4–5% vinegar, 50/50 is enough), let it sit or heat overnight, drain, then flush with a Camco tank wand (Woosch, an owner); an owner posted the debris from a 3-hour soak. Expect a vinegar taste for a cycle or two (Lumatic). Turn the propane and electric elements off while draining and refilling; one owner’s relief valve wouldn’t budge. Frequency: annually (An owner — in the fall when winterizing); an owner does it every 6 months full-time.\"}]},{\"id\":\"x-finding-the-winterizing-valve-behind-the-28-rb-s\",\"system\":\"Plumbing\",\"title\":\"Finding the winterizing valve behind the 28 RB’s ducts\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. The pump, strainer and winterizing valve sit under the range behind heater ducts and wiring (An owner; Airstream support agreed it’s packed tight). Owners zip-tied the ducts up (Two Tall, an owner — he then ran the furnace briefly to check the ducts weren’t kinked); akarakos props them up and follows the coiled clear tube to a white valve with a position tag; one owner’s valve was against the back wall, far left, handle facing the wall. An owner: trace ducts to an end and disconnect there; one owner’s had a dryer-type section that disconnects. An owner removes the microwave/oven above. An owner moved the pump, filter and valve forward. one owner’s valve was installed backwards at the factory. one owner’s 2019 Sport 22 valve was under the kitchen sink, 5 ft from the pump.\"},{\"look\":\"More\",\"action\":\"Finding the winterizing valve behind the 28 RB’s ducts (cont.) Tankless (Girard): no bypass needed; antifreeze through it is approved; akarakos stresses running antifreeze through hot and cold lines. An owner also opened the low-point drains to confirm antifreeze. owners: water stays in the pump unless it is cleared. Two Tall cleans and re-greases the pump strainer O-ring.\"}]},{\"id\":\"x-owner-reports-the-converter-stops-charging-after\",\"system\":\"Electrical\",\"title\":\"Owner reports the converter stops charging after 4 h, so the battery drifts down a few %\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. One owner said the converter stopped charging after about 4 hours, and that the battery then drifted down a few percent. Unplugging shore power and plugging it back in restarted charging. That owner pointed at a manual page. In that one case, Battle Born later replaced both batteries under warranty. That is one warranty replacement, not a finding that the model fails.\"}]},{\"id\":\"x-a-fully-charged-lead-acid-battery-will-not-freez\",\"system\":\"Electrical\",\"title\":\"A fully charged lead-acid battery will not freeze until roughly −60 °C to −80 °F\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. A fully charged lead-acid battery will not freeze until roughly −60 °C to −80 °F, according to one owner. Disconnect the batteries in storage with a real disconnect switch (usually a big red rotary) or by pulling the negative leads. The USE/STORE switch is \\\"always no\\\" for this. On parallel banks, connect a maintainer to the positive of one battery and the negative of the other. Newer smart chargers drop into a \\\"storage\\\" mode; older ones stay on float, which raises water use.\"}]},{\"id\":\"x-wiring-chafe-protection-aging-roof-plastics\",\"system\":\"Electrical\",\"title\":\"Wiring — chafe protection; aging roof plastics\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. The power jack and breakaway wires rub where they run under the edge of the propane tank cover. One owner slit clear 3/8\\\" plastic tubing over them and taped it every 4–5 inches. Another reports that plastic vent lids and A/C shrouds can turn brittle in as little as two years; he found cracks in his Penguin shroud and fitted an aftermarket replacement.\"}]},{\"id\":\"x-shore-power-adapters-and-cords\",\"system\":\"Electrical\",\"title\":\"Shore power adapters and cords\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. One owner warns that a 15 A adapter plus a 14-gauge extension cord drops voltage when the A/C starts, which \\\"could cause a failure in the compressor over time\\\". He suggests a 20 A adapter with a #10 cord instead. Other owners suggest a 30 A RV extension cord with an adapter, or a 10 AWG cord that still has standard 15 A plugs. The first owner also considers plugging a 30 A cord into a 50 A outlet unwise, while a 50 A cord into a 30 A outlet is safe.\"}]},{\"id\":\"x-shore-power-faults-and-hot-skin-rally-temporary-\",\"system\":\"Electrical\",\"title\":\"Shore-power faults and hot skin: rally temporary power, EMS vs surge protector\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. A miswired temporary rally feed put a live voltage on one owner's skin and later fried converters, batteries and electronics in several trailers. Protect yourself: test the pedestal before plugging in (one owner found reverse polarity at a park he had used for 30 years); use an EMS-type protector, which also cuts off for high or low voltage and wiring faults, not just a basic surge strip; a 50 A unit works on 30, 20 or 15 A service via adapters. Basic surge protectors do not check for ground faults. Owners report low voltage (under 90 V with the AC on) and open grounds at campgrounds; if in doubt, dry camp or use the generator.\"},{\"look\":\"More\",\"action\":\"Shore-power faults and hot skin: rally temporary power, EMS vs surge protector (cont.) A tingle from the skin or pets avoiding the trailer can signal hot skin; one owner suggests checking the skin with a digital voltmeter. Carry a multimeter. Neutral and ground are kept separate in the trailer's panel; they should be bonded only at the source. Generators (disagreement, long debate): many inverter generators have a floating neutral. One side says a neutral-ground bonding plug at the generator lets the ground wire trip a breaker on a hot-to-skin fault and lets GFCIs and EMS units work; the other says an unbonded, unearthed generator poses little shock risk and the plug mainly satisfies the EMS. All agree an EMS will not pass power from a floating-neutral generator without one. Commercial models (e.g. EB2000i) may already be bonded; check with a meter or the manual, and bond only one of two paralleled units.\"},{\"look\":\"More\",\"action\":\"Shore-power faults and hot skin: rally temporary power, EMS vs surge protector (cont.) The plug's inventor (an RV electricity educator) says bonding is optional but GFCIs and some appliances need it. Excluded: rewiring inside the generator or its cord to bond it; driving ground rods (buried lines risk).\"}]},{\"id\":\"x-solar-water-pre-heating-one-owner-s-bench-tests-\",\"system\":\"Electrical\",\"title\":\"Solar water pre-heating: bench tests and the objections\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported (experimental; not installed on a vehicle in the thread). DISAGREEMENT on whether it's worthwhile: sceptics say it adds weight, complexity and roof penetrations; in good sun you don't need it, and on cloudy days it produces little, so a tankless propane heater or simply running propane and electric together on the 6-gallon tank is simpler. Supporters point out that solar thermal still collects heat in overcast conditions. Another owner's alternative was a small 120 V under-sink electric heater with bypass valves.\"},{\"look\":\"More\",\"action\":\"Solar water pre-heating: one owner's bench tests, and the sceptics (cont.) Bench results (the bucket loop recirculated 5 gallons): a 22×34\\\" copper sheet with 50' of 1/4\\\" OD tube, painted matt black, raised the bucket from 64 °F to 117 °F over 3 hours on an 81 °F day. A lighter aluminium panel with drip tubing reached 74 °C at the panel in late-day sun and started melting its hot glue. Physics check from another member: heating a shower in real time would take about 15 kW, roughly 15 m² of panel, so this only pre-heats the tank slowly. Design suggestions included flat black paint (black anodizing reflects infrared), insulation underneath with glazing on top, and a differential temperature controller. Run the pump from the main battery system, with an override switch. Plan for freeze drain-down, with isolation valves and a vacuum break.\"}]},{\"id\":\"x-shurflo-4008-failure-pressure-switch-prime-and-w\",\"system\":\"Electrical\",\"title\":\"ShurFlo 4008 failure: pressure switch, prime and wiring ShurFlo 4008\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. one owner’s pump cycled but gave no water. On the bench it pumped when he bypassed the pressure switch, so he blamed the switch. An owner said the 4008's microswitch arcs each time it switches off and eventually fails, and fitted a replacement inside the housing. one owner’s failure was also the switch. Carry a spare pump. An owner doubles his spare as a 12 V transfer pump for a water bladder.\"},{\"look\":\"More\",\"action\":\"ShurFlo 4008 failure: pressure switch, prime and wiring (cont.) Access: the rear mounting screws are hard to reach. An owner mounted his pump on noise-damping material with industrial Velcro. On a 2020 Classic, the pump under the fridge was changed from the drawer opening without removing the fridge (An owner, using a mirror and a small screw gun). An owner found Airstream had used rigid CPVC instead of the flexible hoses the pump instructions call for, on a 2019 25FB. Air lock: Electronut disconnected the output line until water spat out, then reconnected. An owner blew into the outdoor shower hose to restore prime. Hermes pours water into the winterising suction tube. one owner’s intermittent pump on a 2015 23FB was caused by wires twisted and taped instead of crimped; fitting crimp connectors fixed it.\"}]},{\"id\":\"x-use-store-switch-and-parasitic-battery-drain\",\"system\":\"Electrical\",\"title\":\"Use/Store switch and parasitic battery drain\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. An owner measured 0.25 A in Store mode on a 2017 27 ft trailer, about a week of usable capacity; an owner said the inverter is wired straight to the battery, so Store does not cut it, and is the largest parasitic load. one owner’s FC19 inverter has no fuse or switch, only a reset breaker. one owner’s 2014 FC20 has a wall switch for it. Store mode disconnects the converter, so batteries do not charge in Store. one owner’s batteries (bad cell; out-of-spec gravity) were replaced by Interstate under warranty; an owner said older single-stage converters (2017 and earlier) can cook batteries, and a friend's 2017 23 ft got a PD4600.\"},{\"look\":\"More\",\"action\":\"Use/Store switch and parasitic battery drain (cont.) Fixes: a battery disconnect switch; insulate a knife switch against shorts (PKI, an owner); check relay lugs. An owner: T-105 golf-cart batteries are taller and may not fit modern boxes.\"}]},{\"id\":\"x-surge-protector-vs-ems-need-hard-wired-or-portab\",\"system\":\"Electrical\",\"title\":\"Surge protector vs EMS: need, hard-wired or portable\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. EMS vs surge-only: a full EMS also disconnects for low/high voltage, open ground, reversed polarity and miswiring; brown-outs matter as much as spikes (An owner, who says a quality 30 A EMS matters more than a stand-alone suppressor). GFCIs protect people, EMS protects equipment. An owner recommends UL 1449 listing.\"},{\"look\":\"More\",\"action\":\"Surge protector vs EMS: need, hard-wired or portable (cont.) Losses and catches: A/Cs lost to low voltage, a fridge, TV, microwave and converter at a bad pad; one owner’s cheap protector failed with two TVs; an owner says four of five trailers on one Idaho circuit lost AC compressors to brown-outs while his EMS protected his, and reported improperly grounded and miswired pedestals. Catches: reversed pedestal wiring, burnt pedestal wiring, a chewed line (an owner, 33 Classic), storm brown-outs (An owner, bigredandoldblue); DLDINS explained open-neutral damage on 50 A. DISAGREEMENT: Tony Lee, an electrical engineer, used none in 12 years and about 35 countries and calls the need exaggerated.\"},{\"look\":\"More\",\"action\":\"Surge protector vs EMS: need, hard-wired or portable (cont.) Limits: an EMS can't be used on floating-ground inverter generators such as high-end Honda and Yamaha units. one owner’s dealer blamed his EMS for tripping a 2019 Flying Cloud's breakers. Mounting (DISAGREEMENT; an owner say it matters far less than having one). External: easy to replace or skip, movable to another trailer, burns up outside at the pedestal (wulfraat, an owner, dhroberts); lock it to the pedestal (An owner, DLDINS; one owner’s cable lock, though nothing is theft-proof); one owner’s reports over Bluetooth; one owner’s needed recalibrating, easier than internal. Internal: can't be stolen or forgotten, stays dry (an owner RJJ), remote display helps (An owner, RJJ).\"},{\"look\":\"More\",\"action\":\"Surge protector vs EMS: need, hard-wired or portable (cont.) Hum: hard-wired units can hum — don't mount on a thin plywood partition, straighten wires or use rubber washers; DISAGREEMENT: an owner says every internal unit he's seen hums, RJJ never heard his. Startup delay: Progressive hard-wired units wait 15 s by default (136 s with a jumper) to protect the A/C compressor; one owner’s seemed to take a minute or more; an owner saw no lag. Warranty: owners dispute whether Progressive or Southwire covers a unit that dies stopping a surge; Progressive's E10 code means it absorbed a surge; one owner’s lightning-hit unit was replaced; Prime Power's E10 was first refused. An owner had the ground pin break off two Camco dogbone adapters.\"}]},{\"id\":\"x-shore-power-trips-a-house-or-pedestal-gfci\",\"system\":\"Electrical\",\"title\":\"Shore power trips a house or pedestal GFCI\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. How a GFCI works: it trips when current on hot and neutral differs by a few milliamps, meaning some is leaking to ground. An owner and an owner discuss neutral–ground bonding. Common causes owners found or list: moisture in an outside outlet (an owner; an owner had a bad gasket and a damp box); a burned-out water-heater element; a neutral-to-ground short at the A/C; the converter; a rodent nest. Leakage adds up, so two small faults can trip it together. Breakers don't disconnect neutrals, so a trip can happen with every breaker off.\"},{\"look\":\"More\",\"action\":\"Shore power trips a house or pedestal GFCI (cont.) Isolate it: switch breakers on one at a time to find the circuit; plug into a different GFCI to rule out a failing outlet. If guesses fail, use an ohmmeter, or have an electrician check each neutral against ground (an owner lgebhardt). The trailer’s wiring diagram is in the owner’s manual under maintenance.\"},{\"look\":\"More\",\"action\":\"Shore power trips a house or pedestal GFCI (cont.) Outcomes: an owner narrowed it to the A/C and converter circuits, then the A/C, and planned to have it replaced at a service center. lgebhardt traced a neutral–ground connection to the main incoming neutral; it cleared after the inlet was reinstalled. An owner says that means something is touching ground and will again. Rich of one owner’s added outlet shifted so its terminals touched the aluminum skin; the GFCI tripped even with the breaker off. an owner say an outlet with no box is a code violation and recommend an RV-specific outlet box for the shallow walls. DISAGREEMENT: an owner suspected a leaking A/C breaker; an owner, an electrician, says he has never seen a standard breaker leak. Don’t ignore GFCI trips; an owner would never assume the breaker or GFCI itself is faulty.\"}]},{\"id\":\"x-melted-30-a-shore-power-inlet-safe-hook-up-order\",\"system\":\"Electrical\",\"title\":\"Melted 30 A shore-power inlet; safe hook-up order About\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. one owner’s trailer inlet melted; a receptacle pin came out with the cord. A loose or corroded contact arcs and heats; an owner says to replace both plug and socket and keep pins clean, and an owner cleaned his in 10 minutes. An owner mentions a factory recall for loose wire screws on these inlets (Wayne&Sam agrees); 369goose had a recall repair done by Airstream. The inlet swaps with a screwdriver, but expect a big glob of sealant behind it. Check depth: one owner’s Furrion marine inlet was about ½ in too deep for his FC25; an owner suggests ordering the exact Airstream part. Several owners like SmartPlug (An owner: ETL listed; The an owner; an owner; an owner wishes it were shallower); DISAGREEMENT: an owner prefers to keep the standard connector.\"},{\"look\":\"More\",\"action\":\"Melted 30 A shore-power inlet; safe hook-up order (cont.) Hook-up order: pedestal breaker off, plug in the EMS, confirm it is off, then the rest, all solidly engaged. An owner: inspect the pedestal with a flashlight and don't use a sketchy one. An owner: plugging into a live receptacle arcs and degrades both parts; turn the breaker off. DISAGREEMENT: an owner says breakers aren't rated as frequent switches; an owner says switching them doesn't wear them out. DISAGREEMENT on commercial 50-to-30 A dogbone adapters: an owner plugs into the 50 A receptacle when possible because those see less wear, so only the dogbone is at risk; an owner notes the trailer’s own 30 A main breaker still limits the total load. owners say the 50 A pedestal breaker then no longer protects the 30 A cord against a fault between the pedestal and the trailer panel.\"},{\"look\":\"More\",\"action\":\"Melted 30 A shore-power inlet; safe hook-up order (cont.) Long cords: an owner works the voltage drop (115 ft of 10 gauge at 30 A is about 6.9 V).\"}]},{\"id\":\"x-smartplug-shore-power-connector-vs-twist-lock-in\",\"system\":\"Electrical\",\"title\":\"SmartPlug shore-power connector vs twist-lock; installing\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. For: latching, gasketed, positive click-lock with no cross-threading, better weather sealing, more contact area and a reverse-polarity indicator (An owner, an owner). Twist-lock trouble that prompted switching: Rob and one owner’s 2014 OEM unit worked loose; a friend's melted; an owner had several overheating problems and none in about five years since. An owner saw a volt or two less drop (An owner blames his old loose wire). SmartPlug shore-power connector vs twist-lock; installing (cont.) Prime Power's stainless version shows no corrosion against aluminum after about 6 years. An owner says it is now standard on new Airstreams; an owner says it first appeared on mid-2021 AI-19s; an owner says the 2017 Classic lacked it. DISAGREEMENT: an owner used twist-locks 40 years without trouble; an owner calls it a solution to a non-problem; an owner blames melting and cross-threading on technique; an owner says a properly connected twist-lock is rated for the amperage; an owner notes it does nothing for the pedestal end, which can still burn; an owner found full conversion costly; owners dislike a proprietary connector. A lost cord is hard to replace on the road, so carry a spare. Cheaper option: a Marinco Easy Lock ring replaces the threa\"}]},{\"id\":\"x-inverter-outlets-dead-breaker-or-shore-power-mod\",\"system\":\"Electrical\",\"title\":\"Inverter outlets dead (breaker or shore-power mode)\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. How it should work: the inverter needs 120 V at its own AC-in plug to pass shore power through to its outlets. The inverter light showed yellow (battery backup) while plugged in.\"},{\"look\":\"More\",\"action\":\"Inverter outlets dead (breaker or shore-power mode) (cont.) Fixes found: the receptacle feeding the inverter was dead; an extension cord to another outlet worked; the inverter had come unplugged; unplug and replug it; reset the breaker on the inverter itself (chadwest, after plugging in a space heater); a tripped GFCI at the dinette took out all inverter outlets. Check breakers and fuses first (wave man, an owner). one owner’s dealer said needing the switch on was normal; his later began passing through on its own after a click. Layouts differ: some years have separate inverter outlets (one owner’s 2014 had blue-marked ones); an owner says newer ones pass through. 805Vet’s inverter would not reset at a park running high voltage; he checks voltage routinely. Owner-reported.\"},{\"look\":\"More\",\"action\":\"Inverter outlets dead (breaker or shore-power mode) (cont.) A dead stock 1000W inverter on a 2018 27FB turned out to be the 100A terminal fuse at the battery, blown after a high-draw appliance was plugged into an inverter outlet (An owner, 2018); the fuse has torque specs (An owner, 2018). Owners named the Blue Sea Systems 5183 100A terminal fuse as a replacement and suggested carrying a spare (An owner, 2018). Airstream tech support said AS would cover labour to replace an in-warranty inverter, including with an owner-supplied unit (An owner, 2018). A converter failed when a regulator chip broke off its heatsink from vibration (An owner, 2018). The stock unit was identified as a WFCO; an E04 code can also show with low battery voltage or poor connections (GMFL, an owner, 2018–21).\"},{\"look\":\"More\",\"action\":\"Inverter outlets dead (breaker or shore-power mode) (cont.) Victron MultiPlus 2000/3000 inverter-chargers were common replacements that also replace the converter; the built-in transfer switch keeps inverter and shore power separate (An owner, 2018–21).\"}]},{\"id\":\"x-battle-born-lithium-failure-warranty-replacing-o\",\"system\":\"Electrical\",\"title\":\"Battle Born warranty questions: one battery or both, and cold charging\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Not a finding that the model fails. One owner said one battery in a factory pair read about 6 V and dropped under load. Some owners replace every battery in a string at once. Others name Epoch, SOK, SFK, Lithium Blue, or Renogy as what they installed instead. One owner said a Renogy’s data connectors got wet in an unsealed box. One owner said an Epoch’s mini terminals felt easy to damage. Cold charging: owners say these packs generally do not charge below freezing, and that discharge can continue. One owner switches the maker’s heater on only when it is freezing.\"}]},{\"id\":\"x-battle-born-positive-terminal-overheating-report\",\"system\":\"Electrical\",\"title\":\"Battle Born terminals: what owners check when a post looks hot\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Not a finding that the design fails. One owner’s tests, passed on by another owner, reported that the bolted positive terminal loosened and ran hot. Those owners watch the red epoxy for a dull or brown color. Other owners, including some with several years on a 2018 Flying Cloud, report no trouble. One owner calls that behavior a safety feature. One owner said two of four BB100 packs showed heat marks at the terminals. Another said the design had not changed and that theirs was not from a bad batch. The same notes say those tests used about 49–99 A, against about 25 A per battery from a typical 50–55 A converter.\"},{\"look\":\"More\",\"action\":\"Owner-reported. What those owners did: look at the terminal color, replace a pack, add temperature sensors, or lower the charge current. One owner said a high inverter-charger rate was about 50 A per battery and turned it down. Test each battery on its own. Lights coming on is not a capacity test. Owners also warn that a lithium battery fire is not put out with water.\"}]},{\"id\":\"x-dropping-lithium-batteries-into-the-factory-batt\",\"system\":\"Electrical\",\"title\":\"Dropping lithium batteries into the factory battery box: converter, solar and wiring\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Converter: owners say a lead-acid converter won’t reach full lithium charge voltage and cells won’t balance; an owner says major lithiums work but won’t fully charge. DISAGREEMENT: one owner’s 2016 Classic ran Renogy lithiums 3 years on the old converter with solar; an owner says a solar controller with a lithium setting will reach 100%, while an owner says solar may not hold voltage long enough to balance.\"},{\"look\":\"More\",\"action\":\"Dropping lithium batteries into the factory battery box: converter, solar and wiring (cont.) Lithium-capable converters were phased in during the 2021 model year; check what your trailer actually has. Typical steps: set the solar controller to lithium (Victron dial from 3 to 7 per an owner and mudhoneyandthenips); replace the WFCO converter (mudhoneyandthenips: WFCO 8950L2 MBA under the fridge, ~10 minutes); change battery cable ends from post to lug; disconnect or manage the tow-vehicle charge lead or add a DC-DC charger (wulfraat, irush). Heaters: switch on only when charging in cold weather. Fit: GC2s dropped in after removing the plastic tray (mudhoneyandthenips, an owner; one owner’s 2019 needed no mods); an owner trimmed the box hinge tab for standard BB10012s. Weight: two 100 Ah BBs ~62 lb vs two GPL-27T AGMs ~122 lb.\"}]},{\"id\":\"x-planning-a-lithium-upgrade-capacity-converter-mo\",\"system\":\"Electrical\",\"title\":\"Planning a lithium upgrade: capacity, converter, monitor, disconnect\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Capacity: an owner notes only about half a lead-acid pair’s capacity is usable, so one 100 Ah lithium roughly matches it and two double it; an owner suggests 2 × 100 Ah if you run the fridge on propane and the pump off-grid. Converter: GMFL, an owner, Naia Haus and Airsurfer swapped to a lithium-capable converter (An owner: set its lithium switch); an owner replaced a Parallax in a 2016 with a Best Converter unit. DISAGREEMENT: Mudfud kept the original Parallax on his 2008 with a 330 Ah battery.\"},{\"look\":\"More\",\"action\":\"Planning a lithium upgrade: capacity, converter, monitor, disconnect (cont.) Wiring: an owner and an owner say factory cables are fine unless you raise charge/discharge rates (e.g., a big inverter); an owner questions this. an owner: the taller box for Battle Borns arrived around 2017, so measure. Add-ons (field & stream, an owner): a DC-DC charger (one-way from the tow vehicle), a shunt monitor such as a Victron 712, and a real battery disconnect, since the factory switch leaves the LP detector and other loads drawing. Zamp ports are reverse polarity; non-Zamp suitcase panels need an adapter. DISAGREEMENT on placement: Mudfud was told not to put lithium inside; an owner says LiFePO4 is fine inside; an owner notes LiFePO4 is a lithium-ion subtype.\"}]},{\"id\":\"x-what-solar-ready-means-and-how-much-the-factory-\",\"system\":\"Electrical\",\"title\":\"What “solar ready” means and how much the factory pre-wire carries\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. The pre-wire is a yellow (+) / green (–) pair marked “Solar”, usually near the 12 V busbars up front; on 2017–18 Classics it comes down under the recliners’ center section. An owner: location varies a lot, so be prepared to look. an owner: add a switch, the controller, and heavier wire with a breaker to the busbars. Capacity: the 10-gauge pre-wire is rated 30 A; one owner’s is fused at 40 A. an owner runs 600 W as series-parallel pairs; an owner says factory wiring easily supports 400 W parallel.\"},{\"look\":\"More\",\"action\":\"What “solar ready” means and how much the factory pre-wire carries (cont.) DISAGREEMENT: series-parallel (an owner: earlier start, less voltage drop) versus all-parallel (An owner: shading one panel drops its series partner). an owner and an owner advise rigid, not flexible panels; an owner says the factory controller and flexible panels are fine for storage but weak for boondocking. Loads: an owner figures a Classic draws 2–2.5 A doing nothing (over 50 Ah/day). hhendrix prefers portable panels for shade; an owner suggests both.\"}]},{\"id\":\"x-testing-the-solar-pre-wire-before-installing-a-c\",\"system\":\"Electrical\",\"title\":\"Testing the solar pre-wire before installing a controller\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. one owner’s 2026 GT27FBT, ordered without solar, showed continuity from the yellow PV+ wire to the chassis with both ends disconnected; his Victron MPPT wouldn’t recognize the panels. oldenavy: test with the wire disconnected at both ends, measure ohms, check the roof combiner first; likely a screw or cut insulation. ssemone: confirm polarity with a DC voltmeter (a negative reading means reversed leads). The pre-wire should be isolated from chassis and each other (ClearPath RV Solutions, BGClassic). Running a new wire is hard: the pair runs inside the wall to the wiring closet under the curb-side bed; suggested routes are the bath vent chase, the shower wall (ClearPath RV Solutions) or the chase by the black-tank vent.\"},{\"look\":\"More\",\"action\":\"Testing the solar pre-wire before installing a controller (cont.) Outcome: insist on factory spec (BGClassic); do not relabel or rewire the pre-wire yourself. Owners advise going through the dealer under warranty (An owner, oldenavy, 8thMarines, an owner). vanderwielen: reversing battery polarity on the MPPT bricks it.\"}]},{\"id\":\"x-lithium-batteries-battle-born-100ah-gc2-270ah\",\"system\":\"Electrical\",\"title\":\"Lithium batteries: owner reports on Battle Born 100 Ah, GC2, and 270 Ah\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Independent owner reports, not a test of the model. One owner said a healthy battery in a bank can hide another that is not taking a charge, and suggested testing each battery or watching how the bank recharges. One owner with three 2-year-old 270 Ah GameChangers said their monitor looked like about a third of the capacity was gone. That is one owner’s screen, not a lab result. Another owner said the packs he opened had plastic in the terminal joints, that he thought cold could loosen the joint, and that older packs he checked showed less capacity. He told owners to test each battery and look at the epoxy color. Those are his checks, not a finding that every pack does this.\"},{\"look\":\"More\",\"action\":\"Owner-reported. Other owners report no trouble: 2019 and later coaches, four GC2s in a 2022 Classic, and a pair with the same run time after four years and no color change. A Jackson Center tech told one owner he had seen few of these packs come back. One owner described a capacity check: discharge until the battery shuts off, then count amp-hours on the way back up with a charger. One owner said one of two 2.5-year-old 100 Ah packs stopped working and was deciding whether to replace one or both. Other owners suggested replacing a string as a matched set rather than mixing a new pack with an old one. They also said to fasten the batteries and the heavy cables down.\"},{\"look\":\"More\",\"action\":\"Owner-reported. One owner preferred brands with screwed cases, naming SFK, SOK, and Epoch. One owner said an unfused positive lead on loose batteries in a metal tongue box shorted, and that the battery manager no longer worked. That was an install report, not a claim about the battery model. Several owners said they will keep the packs they have until a test shows less capacity or a terminal looks heat-stained. Batteries in a bank can be checked one at a time by disconnecting them from each other.\"}]},{\"id\":\"x-lithium-inverter-upgrade-27fb-50a-2020s-flying-c\",\"system\":\"Electrical\",\"title\":\"Lithium / inverter upgrade 27FB (50A) 2020s; Flying Cloud 26\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Build log of a 27FB lithium/Quattro/solar upgrade. Lessons the owner reported: battery cables kept equal length (within 1/2\\\") gave near-equal charge rates (An owner, 2026; equal-length advice also LNBright, 2026). Each battery was charged fully on its own before paralleling; they then connected \\\"with nary a spark\\\" (An owner, 2026). The factory wardrobe floor could not carry batteries and was rebuilt with framing; others warned the closet floor is under-supported and the inverter is a heavy dynamic load (an owner 2026). The Quattro's AC terminal blocks are numbered 1–4 with L1/N/L2/G embossed under a lip; the owner caught reversed wires only by re-reading the factory manual (An owner, 2026).\"},{\"look\":\"More\",\"action\":\"Lithium / inverter upgrade (cont.) Factory wiring was found chafing on bare aluminium edges, including a 120V Romex over the wheels (An owner, 2026). Former inverter-only outlets were moved to the second AC output, which is live only with AC input (LNBright, 2026). Solar panels mounted with VHB tape and Sikaflex stayed attached on a Virginia–Colorado tow (An owner, 2026). A campground outage at night drew enough from the batteries for two A/C units to trip the 400A battery breaker; the owner now sets a low-SOC alarm (An owner, 2026). An installer suggested a breaker between the solar charger and Lynx (vanderwielen, 2026).\"}]},{\"id\":\"x-converter-inverter\",\"system\":\"Electrical\",\"title\":\"Converter / inverter\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. The 2014 27FB's stock 1,000W WFCO inverter sits under the bed and feeds four dedicated outlets that only work with the inverter on, controlled by a galley remote switch (An owner, 2014). The WFCO was measured at about 1.9 A idle; one owner added a small sine-wave inverter with a search mode for light loads and noted his WFCO's AC pass-through was not connected (idroba, 2014). A Magnum MS-series spec of about 25 W no-load was noted (idroba, 2014); a master tech advised simply switching an inverter off when not needed (An owner, 2014). The Progressive Dynamics PD4655 was named the direct replacement for the Parallax 7355, fitting the same space; an inverter/charger install involves more peripherals (An owner, 2014).\"},{\"look\":\"More\",\"action\":\"Converter / inverter (cont.) Owner install notes: power and battery negative disconnected and checked with a meter first; a headlamp; allow at least twice the expected time; the green AC wire goes to the ground bus, not neutral; do not put two wires under one breaker; loosening the converter's strain relief frees battery-cable slack (An owner, 2014). After install the PD4655 dropped to storage mode by itself and could stay plugged in with the battery switch on \\\"Use\\\" (An owner, 2014); float draw measured about 10 W (idroba, 2014). The dealer replaced flooded batteries judged impaired by lot storage at half charge (An owner, 2014). An optional remote pendant can skip the fuse-board swap and save about 30 minutes (68 Overlander, 2017).\"}]},{\"id\":\"x-lid-won-t-power-open-10-speed-fans-have-a-powere\",\"system\":\"Furnace\",\"title\":\"Lid won't power-open: 10-speed fans have a powered lid, 4-speed are manual\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Lid won't power-open: 10-speed fans have a powered lid, 4-speed are manual. A damp rain sensor blocks auto mode. The lid can stick to the gasket after storage: stop the power opening and open it by hand. Dealers replaced the board/lid motor under warranty. One owner siliconizes the gasket yearly.\"}]},{\"id\":\"x-a-c-calls-but-never-starts-an-owner-resets-the-d\",\"system\":\"Air conditioning\",\"title\":\"A/C calls but never starts: an owner resets the DC thermostat by pulling its 15 A fuse\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. A/C calls but never starts: an owner resets the DC thermostat by pulling its 15 A fuse. Another traced the same symptom to a device on a 120 V outlet. Owner reports the 15k compressor cycling at 8500–9500 ft.\"}]},{\"id\":\"x-frost-check-the-door-seals-with-a-paper-strip-do\",\"system\":\"Leaks\",\"title\":\"Fridge frost: door seals, load, and a dehumidifier\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Frost: check the door seals with a paper strip, don't overload, consider a dehumidifier. Defrost with the fridge off; no hair dryer or heat gun (can melt the liner).\"}]},{\"id\":\"x-clicking-no-blower-the-blower-must-run-before-ga\",\"system\":\"Furnace\",\"title\":\"Clicking, no blower: the blower must run before gas opens\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Clicking, no blower: the blower must run before gas opens. Check for 13.5 V+ at the fan (check batteries). Replacing the blower motor took one owner about 4 h (long T-handle Allen key for the fan-blade screw); fit a new sail switch while it's apart.\"}]},{\"id\":\"x-erratic-stopping-never-switch-off-awning-or-trai\",\"system\":\"Furnace\",\"title\":\"Erratic stopping: never switch off awning or trailer power while the awning is out\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Manufacturer + owner-reported. Erratic stopping: never switch off awning or trailer power while the awning is out. Level any tilt before closing. Press CLOSE before OPEN. Weak lead-acid batteries off shore power may not run it. Matches the manual's full-close recalibration pp.10–12. 15 A fuse blows when the awning is switched on: inspect the front-arm motor wire, which had been cut by the aluminum cover. Also check the wires entering both arms. The green flashing board under the sink is the Zip Dee Relax control board. Water from the A/C vents only in heavy downpours: a dealer traced it to partly clogged 2020 25 ft Globetrotter (dual A/C); 2015 25 ft RB Symptom (full): Water from the A/C vents only in heavy downpours: a dealer traced it to partly clogged A/C drain tubes overflowing the tray into the ducts Owner-reported. Water from the A/C vents only in heavy downpours: a dealer traced it to partly clogged A/C drain tubes overflowing the tray into the ducts. Another owner's shop replaced the A/C-to-roof gasket, which stopped it. For the gasket, follow the A/C maker's bolt-torque spec.\"}]},{\"id\":\"x-a-c-or-thermostat-not-cooling-not-responding-glo\",\"system\":\"Air conditioning\",\"title\":\"A/C or thermostat not cooling / not responding Globetrotter (new)\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. A/C dead with power present: one owner fixed it by switching off the A/C breaker and the battery disconnect, then restoring power (thermostat reset; free to try first). Thermostat no longer sees the furnace after a heat-pump error was cleared: a tech suspects a furnace DIP switch in the A/C was turned off. Another owner fixed the same symptom by replacing the A/C 15 A fuse. Owner-reported. A/C or thermostat not cooling / not responding (cont.) \\\"EE\\\" means lost communication between the CCC thermostat and the A/C; suspects are the data-cable connectors and the small cable unions above the lower A/C grille (An owner, 2011). The CCC is powered over the data cable from the relay board in the roof unit; that board has a 3 (or 5) A fuse (An owner, 2011). In one case the 3 A relay-board fuse was the fix (fmr.capt.evi, 2011). The relay board is either under the shroud on the curb side or reached by removing the interior air distribution box (An owner, 2011). The data cable looks like phone cable but is wired differently; testing with a known-good data cable isolates cable faults (An owner, 2011). A/C or thermostat not cooling / not responding (cont.) E1–E9 code list posted: E1 communication loss; E2/E3 indoor sensor; E4 outdoor sensor; E5 freeze sensor; E6 humidity sensor; E7 loss of 120 V; E8/E9 zon\"}]},{\"id\":\"x-when-towing-from-warm-humid-weather-straight-int\",\"system\":\"Furnace\",\"title\":\"When towing from warm, humid weather straight into hard freeze, water can still sit in\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. When towing from warm, humid weather straight into hard freeze, water can still sit in the roof A/C drain cups and freeze. One owner hit this at 13 °F the next day.\"}]},{\"id\":\"x-lp-fridge-on-propane-while-towing-disputed\",\"system\":\"Refrigerator\",\"title\":\"LP — fridge on propane while towing (disputed)\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Owners disagree, and one notes \\\"You will not find a common ground between the two sides.\\\" Many tow with the fridge on LP; others turn the propane off and pre-chill the fridge with ice or gel packs. One owner who turned it off found the fridge reached 45–50°F on each leg of a trip; another saw a rise of about 10°F in two hours at 80°F. One owner quoted the Dometic manual: its 15-minute gas lockout when the engine stops works only if the alternator D+ connection is installed and AUTO mode is on. Near gas pumps, the warning is to shut off LP appliances. Tunnels and ferries can require propane off (a Lake Michigan ferry told one owner \\\"NO\\\"). The underbody 1/4\\\" copper LP tubes are exposed to road debris.\"},{\"look\":\"More\",\"action\":\"LP — fridge on propane while towing (disputed) (cont.) On newer fridges, closing the tank valve starts the spark igniter retrying and can time out to a fault that needs an off/on reset, so one owner switches the fridge off inside instead. On a 2014 FC, pressing the \\\"gas\\\" button forces LP but bypasses the thermostat, which freezes contents; leave it on AUTO.\"}]},{\"id\":\"x-alde-hot-water\",\"system\":\"Alde\",\"title\":\"Alde hot water —\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported: 2018 Classic with only 15–20 s of hot water: the fix that worked for two owners was a hidden quarter-turn valve behind the Alde unit under the dinette (the cold inlet to the heater). It must be open (handle in line with the pipe); one owner says customer service walked them through it by email with photos. After that, recalibrate the Alde mixing valve: pull the knob off; the knob limits travel. Caution: one owner backed the stem out “until it stops” and it unscrewed completely, spraying water; he says never change the max-temperature limit by more than 1/2 turn, and he rebuilt it from the LK550 diagram. Another owner warns that forcing the knob can break it internally. Do not disable the Kohler shower anti-scald set screw; owners warn of scalding above about 130–140 °F, especially with children.\"},{\"look\":\"More\",\"action\":\"Alde hot water — 2017–2018 Classic (Firefly era) (cont.) Bleed air from the Alde loop (one owner says a dealer who refused to bleed it “does not understand the system”). The shower boost runs for 20 minutes, then reverts (2017). 2018 build: Alde 3010 plus an Alde Flow pre-heater mounted under the dinette (visible after removing the front skirt). Airstream Service Bulletin 173 (owner-quoted): a 3-pin Alde connector on the G6 panel may be miswired on 2018 Classics built 1/31/2017–11/02/2017 (serials 538263–542982), causing incorrect cycling. One owner’s DIY Firefly 3.3 update broke Alde communication until the pinout was addressed. Alde fluid in US Airstreams is propylene glycol (non-toxic), not ethylene glycol per European manuals (owner-reported). At altitude (above ~5,000 ft) one 2017 owner added an adjustable propane regulator to stop burner rumbling (second-hand report).\"},{\"look\":\"More\",\"action\":\"Alde hot water — 2017–2018 Classic (Firefly era) (cont.) Do not run the pump and city water together; check the outside-shower valves are closed (they can mix hot and cold).\"}]},{\"id\":\"x-condensation-and-mould-under-the-mattress-over-a\",\"system\":\"Furnace\",\"title\":\"Condensation and mould under the mattress over an outside storage compartment\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported: Problem: the thread starter found the underside of the mattress and the plywood dripping wet on cold nights (inside 60 °F at 40–50% RH, outside 35–47 °F) after a window-leak repair. Airstream replaced the plywood and mattress. Mould and mildew had formed. Rule out leaks first: one owner found two small holes in the window rim. Another suggests the tissue-paper test around the access door and the bed platform, and checking the compartment door gasket. Another suggests a moisture meter to find a hidden water reservoir.\"},{\"look\":\"More\",\"action\":\"Condensation and mould under the mattress over an outside storage compartment (cont.) What fixed it: a 1.5 in layer of foil-faced foam (two 3/4 in sheets, about R-5.8, seams foil-taped) between mattress and plywood left both surfaces dry overnight. Other owners report 1/2–1 in rigid foam, Reflectix, flattened cardboard, a ventilated cup-sheet “breathing” layer, or a slatted frame. Insulating under the lid of the compartment and adding D-shaped weather seal to the door stopped cold drafts for another owner. One owner runs a 200 W heater in the compartment plus a dehumidifier. Lower indoor humidity: vent while cooking and showering, crack vents, and remove wet towels. One owner notes heat-pump mode does not dehumidify.\"},{\"look\":\"More\",\"action\":\"Condensation and mould under the mattress over an outside storage compartment (cont.) Heat-pump note: owners report the Dometic CCC can switch automatically to the furnace in cold weather, and the heat pump runs a defrost cycle below about 40 °F. One owner says the switchover must be reprogrammed after DC power is removed, while another’s kept working. A third owner explains the DIP switches and the reset.\"}]},{\"id\":\"x-roof-ac-soft-starter-micro-air-easystart-364-ins\",\"system\":\"Furnace\",\"title\":\"Roof AC soft starter (Micro-Air EasyStart 364): install, the five learning starts\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported, with replies from a Micro-Air representative (vendor) marked as such.\"},{\"look\":\"More\",\"action\":\"Roof AC soft starter (Micro-Air EasyStart 364): install, the five learning starts (cont.) Install (roughly 20 min to 3 h): remove the shroud screws and lift it off; the unit sits in the compressor housing and is wired into the AC electrical box, replacing the start capacitor and the parts attached to it. Owners found the optional install kit useful. Photograph the wiring and DIP switches first: bumped DIP switches caused E1 errors and missing modes for two owners. Choosing the wrong white wire (it must be the one that runs to the compressor) gave an E7 error or left the compressor hard-starting. Use crimped, ideally heat-shrink, butt connectors and pull-test them. Some owners kept the removed parts so the unit could be restored for warranty work; one owner says the mod voids the AC warranty.\"},{\"look\":\"More\",\"action\":\"Roof AC soft starter (Micro-Air EasyStart 364): install, the five learning starts (cont.) Roof: step only where the rivets show the ribs, keep your feet dry because the roof is very slippery, or work from ladders on each side (pad a leaning ladder). Learning: do the five starts on steady utility power (a 20 A, or even 15 A, household outlet or 30 A pedestal) with the converter, fridge and water heater switched off at their breakers. Vendor: generator ECO mode off for learning; the unit does not keep learning, and a jumper inside resets it. Heat or cool mode both work.\"},{\"look\":\"More\",\"action\":\"Roof AC soft starter (Micro-Air EasyStart 364): install, the five learning starts (cont.) On a 2000 W generator: the soft starter cuts starting current, not running current (vendor: about 12–14 A running for a 13.5k unit). Switch the fridge and water heater to propane, and turn off the converter if the batteries are charging, or the generator overloads; the compressor then runs about a minute and cuts out, retrying every five minutes. Hondas struggled at about 5,000–6,400 ft even after re-jetting; two paralleled units, or a 2200 W unit, worked. Stale fuel and a hot, corroded 15-to-30 A adapter caused failures for others. Do not run a high-altitude jet at low altitude (owners report running too lean). An EMS needed a neutral-ground bonding plug on the generator for one owner. Other causes of cycling were a bad thermistor, an old bi-metal thermostat, and running the AC in cool weather.\"}]},{\"id\":\"x-off-grid-power-on-newer-more-electric-airstreams\",\"system\":\"Furnace\",\"title\":\"Off-grid power on newer, more-electric Airstreams: charging from a generator or truck\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported.\"},{\"look\":\"More\",\"action\":\"Off-grid power on newer, more-electric Airstreams: charging from a generator or truck (cont.) On a 2025 30 ft Classic, 2000 W inverter generators and a truck's 2 kW outlet charged at about 20 A for a few minutes, then only 1–2 A. Another owner explains that the stock converter puts only about 20 A into the batteries whatever the source, which is why many upgrade the charger. His generator checklist: a reliable brand; about 1 kW for charging, 2 kW for the microwave, 3 kW for AC; the right 30 A adapter; a neutral-ground bonding plug so the EMS/GFCI is not confused; check the oil; confirm about 120 V. Truck power: owners report ground-fault trips and overloads with a 2 kW truck outlet, but no problems with the 7.2 kW one. With a MultiPlus, owners set the input type to generator and limit input current (about 13 A).\"},{\"look\":\"More\",\"action\":\"Off-grid power on newer, more-electric Airstreams: charging from a generator or truck (cont.) A DC-DC charger fed from the 7-pin gives about 15–18 A while towing (check the truck's fuse; one owner chose an adjustable Victron XS). Upgrades owners made: lithium (300–800 Ah), 600–1,000 W of solar, a 3,000 W inverter/charger feeding the whole 120 V panel, soft starts on the ACs (one AC on batteries). One owner found the factory push-in outlets substandard and had them replaced; another found the thermal breakers on the factory positive busbar cutting out under charging loads (one replaced the breaker, another rewired).\"},{\"look\":\"More\",\"action\":\"Off-grid power on newer, more-electric Airstreams: charging from a generator or truck (cont.) 12 V compressor fridge: one owner with 200 Ah and 300 W ran flat overnight on cold nights with the furnace running; another with 400 Ah and about 720 W of solar was back to 100% each day. Owners say water and tank capacity, not batteries, often limit off-grid stays. DISAGREEMENT over propane-fridge safety versus 12 V fridges; one owner gives absorption-fridge levelling limits (about 3° side to side, 6° front to back) and says to keep vents clear. EXCLUDED (unsafe): removing the ground pin from an adapter to stop truck-generator ground-fault trips. AI-generated text pasted by a poster is not used as a source.\"}]},{\"id\":\"x-atwood-dometic-water-heater-ignition-board-failu\",\"system\":\"Water heater\",\"title\":\"Atwood/Dometic water-heater ignition board failures and the Dinosaur replacement board\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Symptom: propane mode makes three tries and then the switch shows a red light, while electric mode still works. If the stove and furnace light, the propane supply is fine and the board is the likely cause. Running only on electric hides the fault. Many owners of 2017–2019 trailers report repeated failures of the original boards with models ending in -8E; one went through four boards under warranty. A Dinosaur supplier said the original board is single-sided, and relay movement cracks its solder joints.\"},{\"look\":\"More\",\"action\":\"Atwood/Dometic water-heater ignition board failures and the Dinosaur replacement board (cont.) Fix most owners chose: a Dinosaur UIB-64 (gas/electric) or UIB-S board. It is plug-and-play using the supplied plate, and on a single-6-pin heater the 6-pin plug goes into the 6-pin socket. Set the jumpers following the instructions (two owners moved the mode jumper to position 2–3 for water heaters). Use the shorter supplied screws so they don't press on the tank. A delay of up to about 20 seconds before the next try is normal. Owners report years of service. In 2019 one owner received a board from a different maker directly from Airstream and had no problems. Before replacing the board, check: the spark electrode's ceramic insulator (clean it with isopropyl alcohol or replace it; one owner's furnace fault was a leaky igniter), spider webs in the burner tube (soot on the side), and loose wires at the switch.\"},{\"look\":\"More\",\"action\":\"Atwood/Dometic water-heater ignition board failures and the Dinosaur replacement board (cont.) Warranty: keep the old board and receipt and ask Airstream for reimbursement; several owners were refunded, one was not after the returned board was lost. An adjustable Atwood thermostat is available.\"}]},{\"id\":\"x-dropped-under-mount-galley-sinks-and-the-awning-\",\"system\":\"Furnace\",\"title\":\"Dropped under-mount galley sinks and the awning controller beneath them Classic 30 (\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Failure: the glued under-mount sink dropped into the cabinet, and water reached the Zip Dee awning controller mounted below it, which failed. The sink was held by a thin bead of adhesive and four soft metal brackets, two of which can't be reached without removing the countertop. Owners reported this was covered under warranty. Check yours: a widening caulk gap between the sink and countertop is an early sign; one owner tightened a loose bracket screw. Some models have top-mount stainless or overmount sinks that rest on the counter.\"},{\"look\":\"More\",\"action\":\"Dropped under-mount galley sinks and the awning controller beneath them (cont.) Temporary fixes: support the sink from below with an adjustable brace or a strap. One owner added extra sink clips (in place for 10 years and 60,000 miles); another moved the awning controller onto the wall. A re-glue method: clean off the old adhesive, then hold the sink up to the counter overnight with a wooden batten across the top, chained zip ties through the drain grids and non-expanding adhesive (don't over-pull or you could crack the drain). One owner routed a flush pocket into plywood for the flange. A plumber prefers self-rimming sinks.\"},{\"look\":\"More\",\"action\":\"Dropped under-mount galley sinks and the awning controller beneath them (cont.) If an electrical part gets wet, remove power immediately and dry it before reapplying power. With erratic 120 V behaviour, turn off the breakers, disconnect shore power and the inverter, disconnect the battery negative, and get professional help. In this case the owner suspected a failing pedestal surge protector after rain.\"}]},{\"id\":\"x-atwood-dsi-heater-electric-works-gas-won-t-light\",\"system\":\"Water heater\",\"title\":\"Atwood DSI heater: electric works, gas won't light\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Check: other LP appliances working; spider or dirt-dauber nests in the burner tube; the 12 V breaker; the thermal cutoff fuse; loose or corroded connectors (turn off 12 V and AC before reseating); igniter resistance (it should read open — Al found a 200,000-ohm leak on a furnace igniter that killed the spark). One click without repeated sparking points to the spark circuit or board. An owner found a blown 2 A fuse on the board; a replacement board plus a thermostat kit fixed it. An owner' online-bought board was defective; a Dometic/Atwood mobile tech's board worked.\"},{\"look\":\"More\",\"action\":\"Atwood DSI heater: electric works, gas won't light (cont.) A dripping relief valve means the tank's air pocket is lost: with the tank cool and pressure off, drain it, refill, then bleed the hot lines. Don't pull the lever to 'test' it. Replace a valve that keeps dripping, using new Teflon tape; leaks can damage the board. Hand-lighting a DSI burner (discussed in posts 15546978 and 15546981) is excluded from this guide.\"}]},{\"id\":\"x-burning-smell-from-a-gas-electric-atwood-electri\",\"system\":\"Water heater\",\"title\":\"Burning smell from a gas/electric Atwood; electric side dead\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. A burning-wire smell on electric came from the 120 V junction box, where the relay (Zettler AZ2280-1A-12D) had burned. Stop using electric until it is fixed. The root cause was that the heater wasn't cycling off on gas or electric; replacing the thermal cut-off and thermostat kit cured it. An owner: thermostats must touch the tank and can be bench-tested (thermostat about 140°F, ECO 180°F). Undersized splice wire or a wrong relay caused one repeat. Electric not working while gas works: check for about 12 V at the relay coil with the switch on. one owner’s dead circuit board replaced from the front fixed his 2012 25FB. A 2-amp fuse on the exterior board restored propane on another. The 25FB heater is hard to reach from inside or out.\"}]},{\"id\":\"x-red-fault-light-and-a-dripping-relief-valve-on-a\",\"system\":\"Furnace\",\"title\":\"Red fault light and a dripping relief valve on a gas/electric heater\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. On several owners' trailers the red light means the gas burner failed to light after its retries, often because the propane is shut or empty. Some saw it on electric only, linked to over-temperature. one owner’s 2017 FC overheated and dripped from the relief valve; the dealer suspected the control module and thermostat. An owner says an overheat with a leaking valve needs fixing, and on a new trailer leave it to the dealer. Dripping: an owner quote Atwood that weeping is normal expansion, and that the tank's air gap can be restored. Turn the heater and water off, open a hot tap, pull the relief valve until flow stops. DISAGREEMENT: an owner says don't open the valve; the drip usually stops on its own. Purge air from the hose and lines on setup; an owner warns air can burn out the electric element.\"}]},{\"id\":\"x-factory-tankless-heaters-propane-cost-water-use-\",\"system\":\"Water heater\",\"title\":\"Factory tankless heaters: propane cost, water use, and alternatives\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Factory tankless units are propane-only. Owners explain that electric tankless needs far more current than a 30-A trailer supports. DISAGREEMENT: several call the cost trivial against site fees, and Wanderings likes his Girard, saying the low electric bill offsets propane. An owner and others say tankless units need a minimum flow to fire, which uses more water when boondocking. An owner says his fresh tank now lasts 3–4 days instead of 5–7. Remedies reported: Truma hybrid swaps (one owner’s 2021 International 27); a Showermiser. an owner gets 4–5 boondocking nights from 37 gallons with one, but reports a botched third-party install, so choose an experienced installer. An owner says the recirculating system is standard on the Trade Wind and 2025 Globetrotter.\"}]},{\"id\":\"x-water-heater-lights-on-propane-then-shuts-off-at\",\"system\":\"Water heater\",\"title\":\"Water heater lights on propane then shuts off Atwood (unspecified model); 23D\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. If the board doesn't detect flame, it shuts off the gas. Suggested causes: a flame sensor out of position or sooty (an owner cleans the probes); a corroded igniter/sensor bracket ground; insect nests in the burner tube; low supply pressure from a near-empty tank or failing regulator; and a failed Atwood board. Several owners replaced the board with a Dinosaur board; an owner advises checking everything else first because boards are costly. Electric-only operation that works while gas fails points toward the gas side or the board. In the original poster's case a new board alone didn't fix it; it finally ran after he cleaned the connectors and grounds (he did several things at once, so the cause is unknown). Screening vents against insects: an owner.\"}]},{\"id\":\"x-electric-water-heating-on-30-a-service\",\"system\":\"Furnace\",\"title\":\"Electric water heating on 30 A service\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Dual propane/electric RV heaters exist; on electric they draw heavily, so you may not run them alongside the air conditioner or microwave on 30 A. An owner said propane recovers a 6-gallon tank faster and 50 A conversion is expensive. An owner: 30 A is the campground standard, 50 A sites exist. A Lightning Rod element (about 4 A, 425 W) can be added to a gas heater; one owner’s plugs into the pedestal separately and heats fairly fast. Alwhisman added an electric conversion and uses 30 A sites without trouble. 63Silver ran a dedicated line to an electric-only heater. An owner runs a 13.5 AC plus the electric heater on good 30 A voltage (not a 15.0 AC), checking a plug-in voltmeter, and uses an autotransformer when voltage is marginal.\"},{\"look\":\"More\",\"action\":\"Electric water heating on 30 A service (cont.) an owner tripped a breaker running both; an owner said breakers can trip from built-up heat.\"}]},{\"id\":\"x-living-with-a-propane-tankless-heater-precisiont\",\"system\":\"Water heater\",\"title\":\"Living with a propane tankless heater (PrecisionTemp / Atwood)\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Water flow: mixedpuppy and an owner: these units need strong flow; a fixed 50 psi campground regulator may not do. Use an adjustable regulator with a gauge; the pump works fine. Turning on cold elsewhere can shut the heater off mid-shower; mixedpuppy kept the \\\"winter\\\" setting and found mixing faucets awkward. Propane: an owner and nickclifford: a mostly empty tank or weak regulator gives lukewarm water, especially in cold weather. An owner: three showers then dishes near freezing without running out; it protects itself from freezing with power and propane. An owner quoted the manual's counter-intuitive mixing curve; one owner’s family adapted.\"},{\"look\":\"More\",\"action\":\"Living with a propane tankless heater (PrecisionTemp / Atwood) (cont.) Boondocking DISAGREEMENT: 55AS and Docinabox prefer a tank for water conservation; an owner says gas tankless suits boondocking. nickclifford catches the initial cold water in a bucket. An owner prefers a tank. Vent-free units: owners warned they add moisture and CO2 inside and consume air.\"}]},{\"id\":\"x-dometic-fridge-and-roof-ac-answers-from-a-certif\",\"system\":\"Refrigerator\",\"title\":\"Dometic fridge and roof-AC answers from a certified tech\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Recall: 68 Overlander posted the NHTSA recall 06E076000 for certain Dometic two-door fridges (RM2652/2662/2663/2852/2862/3662/3663/3862/3863, NDR1062) built April 1997 – May 2003: a boiler-tube fatigue crack could release coolant near the gas flame. An owner (a Dometic-certified tech) said the kit adds sheet metal and a thermal cut-off that shuts the board down on overheating; he called it a band-aid. Switches, per an owner: CLC (climate control) is a frame heater for high heat and humidity, when moisture on the door-seal frame causes leaks and frost; LAC/LAT (low ambient) keeps the interior light on below 50 °F so the unit cycles and the freezer stays cold, and should be off above 50 °F. 12 V mode only maintains temperature while towing; Dometic said it needs at least 12.8 V and won't pull temperatures down.\"},{\"look\":\"More\",\"action\":\"Dometic fridge and roof-AC answers from a certified tech (cont.) A roof-AC fan that needs a push after storage indicates a bad run capacitor. Door shelves breaking at the notch (an owner, three in under three years); Dometic replaces whole doors rather than selling gaskets. A Snyder fan kit fits a 2005 Bambi through the two rear access doors without pulling the fridge (An owner, about 20 minutes).\"}]},{\"id\":\"x-norcold-n8dc-door-flying-open-in-transit\",\"system\":\"Refrigerator\",\"title\":\"Norcold N8DC door flying open in transit\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Cause: the lower door sags so its catch misses the latch plate; loaded door shelves make it worse (An owner, Robkhoo, an owner). Washers on the lower hinge pin: Merlintiaga (2022 GT) added about 1/4 in of washers; fixed since 2023, after a warranty door replacement had failed. Robkhoo was told to have it done at an Airstream service centre to protect the warranty. An owner had limited success. Travel lock: owners use the two threaded hinge-swap holes between the doors for a 10-32 × 3.5 in screw with fender washer, rubber washer and wing nut; bzizzi made a thumbscrew the same way.\"},{\"look\":\"More\",\"action\":\"Norcold N8DC door flying open in transit (cont.) Swing-arm latch: an owner ('23 GT 27) says the RecPro lever worked for about 18 months. DISAGREEMENT: an owner ('21 GT 27) and Spartanfam say the Amazon versions didn't fit. An owner identified the part as Everchill 324-000149 (discontinued). Do not drill a new hole in the latch. A door that flies open in transit is a stop. Use the maker’s latch, or a shop. Other: an owner (23 FC27) uses Velcro straps; an owner wrapped the wardrobe handle that the flying door dents. one owner’s 2024 GT door came off its hinges; Jackson Center adjusted it under warranty. Unlike Dometic, Norcold has no built-in storage prop to vent the doors (Spartanfam, Reeltimer).\"}]},{\"id\":\"x-norcold-door-adjustment-and-latch-test\",\"system\":\"Refrigerator\",\"title\":\"Norcold door adjustment and latch test\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Test: pull the door edge, not the latch; if it opens, the latch isn't holding. Lifting the door making it latch points to sag. Shimming: Imustwander (2025 Classic 28) and an owner put washers on the bottom hinge. An owner took the door off and added washers on the top and bottom hinge pins: one screwdriver, about an hour. An owner found a video giving the hinge pin as 5/16 in. Tugbaby ('25 Classic 28) tapped the bottom hinge with a dead-blow hammer to realign it. An owner: hot-melt glue on the latch plate for more pressure, plastic washers to remove vertical play, plus a command-hook bungee. An owner uses a child-safety strap; an owner fitted the etrailer 324-000149 latch; an owner uses the 3 in 10-32 screw through the hinge-swap holes.\"},{\"look\":\"More\",\"action\":\"Norcold door adjustment and latch test (cont.) DISAGREEMENT on whether it can be fixed: one owner’s 2023 27 GT doors still wouldn't hold after a warranty door, so he replaced the fridge with a dual-compressor Isotherm.\"}]},{\"id\":\"x-norcold-dc-fridge-failure-warranty-and-replaceme\",\"system\":\"Refrigerator\",\"title\":\"Norcold DC fridge failure, warranty and replacements Globetrotter (N8DCX)\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Manufacturer + owner-reported. one owner’s N8DCX stopped powering on at 19 months (13.4 V reached it); a shop diagnosed a coolant leak. Airstream said the cabinetry fits only this fridge. Trekers' failed at 6 months; the Norcold N8DC/N10DC manual gives DC-only models a 1-year limited warranty and other models one or two years depending on the model. Components follow their maker's warranty. An owner: compressor fridges are sealed systems; \\\"leaking coolant\\\" is often a guess. Happyisles helped remove one: two people, easy, plug-and-play. Alternatives: an owner (2020 GT30) replaced two N10DCX units and fitted a Dometic DMC4081CFRH 8 cu ft (the 10 cu ft hit the curved wall). Vitrifrigo's suggested DP2600IXD4 was half an inch too wide for an owner.\"}]},{\"id\":\"x-12-v-compressor-fridge-power-use-when-boondockin\",\"system\":\"Refrigerator\",\"title\":\"12 V fridge power use when boondocking\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Measured: an owner (27FB, 300 W solar, N8DCSSR) used about 2.4 Ah/hour overnight at a 50–70 °F range. An owner (9.7 cu ft Norcold, 200 Ah, 300 W, full sun) ran over 4 days without going below 13.1 V. An owner (RFU6800, 5.2 A running, 200 Ah, 270 W) got about 3 days of cloud. one owner’s Caravel averages 1–2 A. DISAGREEMENT on draw: an owner and an owner plan about 100 Ah/day and favour propane (about 28 days on a 30 lb tank); owners say the concern is exaggerated; an owner drains 500 W solar's battery in 3–4 days and misses propane.\"},{\"look\":\"More\",\"action\":\"12 V compressor fridge power use when boondocking (cont.) Planning: duty cycle runs about 30–90% with ambient temperature (field & stream); multiply draw × duty cycle × 24; 60 Ah/day is a starting assumption. Use night mode; pre-chill frozen food; a DC-DC charger on the 7-pin line and portable panels help. The stock WFCO charged at about 14 A max. An owner notes a 50 A breaker on the positive bus in a 2023 limits charging. An owner reports a flammable-refrigerant warning label inside his Norcold.\"}]},{\"id\":\"x-absorption-vs-12-v-compressor-fridge\",\"system\":\"Refrigerator\",\"title\":\"Absorption vs 12 V compressor fridge\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. For 12 V: more space, no leveling, no propane while driving, faster cool-down, no ice on fins (Fischse, an owner, field & stream). one owner’s Norcold N10DCDSSR needs a zero-clearance install, so it isn't drop-in. An owner (2019 Bambi) found a Nova Kool 3100 kept up at 100–110 °F after a poor Dometic. Johncapp (2004 Safari 25, 500 Ah lithium, 600 W solar) uses about 40 Ah/day on a Furrion. An owner says his 2022's 12 V fridge is very quiet; an owner hears some compressor noise. Against: about 60+ Ah/day at a 50% duty cycle, which uses up a 100 Ah lead-acid battery (field & stream, an owner). wulfraat: propane uses under 1 A DC and runs fine while driving. one owner’s 12 V van fridge couldn't keep up at 100 °F.\"},{\"look\":\"More\",\"action\":\"Absorption vs 12 V compressor fridge (cont.) Middle road: Vantair keeps the absorption fridge and adds a portable compressor cooler. Check the cutout; an owner needed a fabricated surround.\"}]},{\"id\":\"x-dometic-2-door-absorption-fridge-recall\",\"system\":\"Refrigerator\",\"title\":\"Dometic 2-door absorption fridge recall (\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Recall: about 926,877 units. If the boiler tube ruptures, hydrogen in the refrigerant can ignite. Models NDR1062, RM2652, RM2662, RM2663, RM2852, RM2862, RM3662, RM3663, RM3862, RM3863, built Apr 1997 – May 2003; the serial ranges were expanded in 2008. Check your model and serial on Dometic's recall site. The fix: extra sheet-metal shielding around the boiler, a thermal fuse and a boiler-tube thermostat, wired into the 12 V feed to the control board so the unit shuts down if it overheats. The kit is meant to contain a fire, not prevent one; an owner says it keeps propane from feeding one. If the fridge won't turn on afterwards, the thermostat's red reset button may have tripped.\"},{\"look\":\"More\",\"action\":\"Dometic 2-door absorption fridge recall (1997–2003 units) (cont.) Check: a flat sheet-metal cover over the boiler tube at the rear access door means the kit is installed. The work is free; installers must not charge for recall work under NHTSA rules. It takes about 15–30 minutes, and any RV shop authorized by Dometic can do it, not just an Airstream dealer (An owner, jimmickle). An owner used an authorized mobile tech. DISAGREEMENT on how much the kit does: an owner calls it inadequate; an owner says it is meant to contain a fire. An owner saw a new 27 ft fridge overheat until plastic melted.\"}]},{\"id\":\"x-water-heater-electric-vs-propane-on-or-off\",\"system\":\"Water heater\",\"title\":\"Water heater: electric vs propane, on or off\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. On shore power where electricity is included, use electric; switch on both electric and propane for fastest recovery. An owner ran 2 months on a 40 lb bottle with both on. DISAGREEMENT on leaving it on: an owner says leave it on if you use hot water every couple of hours, since repeated heat-ups may wear it more; az-streamer, Awchief and CRH turn it on only when needed (CRH: shower-hot in under 10 minutes; still warm 18 hours later). Load: an owner measured the factory electric element at 11.6 A and the A/C at 14.6 A, close to a 30 A limit; BMWTX notes the element doesn't draw continuously.\"}]},{\"id\":\"x-choosing-a-fantastic-vent-roof-fan-features\",\"system\":\"Furnace\",\"title\":\"Choosing a Fantastic Vent roof fan (features)\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Rain sensor is the most-recommended option: it closed the lid in a sudden storm for an owner, and an owner watched it work (also an owner). Reversing: set one fan in and one out for flow-through cooling. an owner warns never to run a fan in \\\"in\\\" mode near the toilet vent stack while flushing. Thermostat: an owner worked 4 years. one owner’s wall thermostat slows the fan as it nears the set point. 87MH never used his. Basic models can be upgraded later with parts. Sealing: an owner found rusted factory screws and resealed with EternaBond tape over a bead of caulk.\"}]},{\"id\":\"x-12-v-compressor-fridges-on-newer-airstreams-powe\",\"system\":\"Refrigerator\",\"title\":\"12 V compressor fridges on newer Airstreams: power and performance\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. How they run: off battery power in transit or boondocking. one owner’s Nova Kool RFU6800 DC is 12 V only, fed by the power center from batteries or shore power; an owner describes them as dual voltage. If you unplug and the fridge stops, check that the batteries are charged and connected. one owner’s Globetrotter needs the 12 V switch at the door on, even when plugged in. one owner’s 2021 Bambi cools within about an hour on the tow vehicle’s 7-way while driving. Susie an owner (Bambi, solar) and an owner (2021 GT 27, factory solar, desert, running full time for a year) report no problems.\"},{\"look\":\"More\",\"action\":\"12 V compressor fridges on newer Airstreams: power and performance (cont.) Boondocking: heymana added 2 lithium batteries and 300 W solar. In sun no generator; under trees 1.5 h every 3 days; in cloud and rain, every other day. Heat and humidity: one owner’s Nova Kool in a 2021 25 ft GT in Florida reached 53°F after sitting all night, and its coils froze up quickly in humidity. The 10 cu ft fridge in his 2021 30 ft GT seems way better, though not yet tested in 90°F+ humidity. Ventilation: an owner estimated his vents at 64 and 80 sq in against the 60 in the manual, and a condenser fan blows across the coils. one owner’s aftermarket GE 12 V fridge in his 2000 Bambi shut down at 100°F until he added a 92 mm exhaust fan.\"},{\"look\":\"More\",\"action\":\"12 V compressor fridges on newer Airstreams: power and performance (cont.) DISAGREEMENT on efficiency off-grid. An owner: compressor cooling is far more efficient than absorption; he measures about 1 A on his absorption fridge. field & stream: on propane his Dometic absorption fridge measured 0.33 A, about 8 Ah/day. panamerican runs about 2 weeks before battery runs low while propane remains; an owner frames it as propane’s greater energy-storage density. one owner’s Nova Kool 5.8 cu ft draws 4.4 A and ran about 50% of the time on a 95°F day.\"}]},{\"id\":\"x-compressor-fridge-warm-in-hot-weather-checks-own\",\"system\":\"Refrigerator\",\"title\":\"Compressor fridge warm in hot weather: checks owners tried\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Symptoms: the fridge section climbs into the mid-40s to 50°F on hot afternoons while the freezer stays cold (An owner, a 2021 25 ft GT in Texas; an owner; an owner). Yet one owner’s 2021 27 FBQ stays very cold at 112–120°F, and an owner (same model) freezes lettuce above setting 4. Checks raised in the thread: a \\\"night mode\\\" switch, if fitted, should be on \\\"day\\\". Is the sun on the fridge side ? Place the thermometer front and back, and remember warm food or many door openings warm it up. Icing: in humid weather the coils ice over and cooling drops; an owner defrosts with a hair dryer; iced, they won’t cool much below about 56°F. one owner’s 2021 GT has a Dometic RFU6800 DC.\"},{\"look\":\"More\",\"action\":\"Compressor fridge warm in hot weather: checks owners tried (cont.) Ventilation: a blocked vent path is possible, and the only sure way to know is to pull the fridge. An owner: check the manual’s intake/exhaust sq in; he doubled airflow on his Vitrifrigo with a second coil fan, within the controller’s listed fan amp limit. One owner's 2020 FC has a fridge-fan switch the tech said to leave on. An owner: check the model on the silver tag by the temperature control; Nova Kool support answered his email by phone within 15 minutes. If you are the original owner with a warranty, contact the fridge maker directly. An owner: food held in the 40s–50s is a food-safety issue.\"}]},{\"id\":\"x-propane-fridge-at-fuel-stops\",\"system\":\"Refrigerator\",\"title\":\"Propane fridge at fuel stops\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. An owner added a dash switch and a normally-closed relay so he can turn his Dometic off before reaching the pumps. If the switch or wiring fails, the fridge still works. DISAGREEMENT on whether it matters. An owner turns his off when the trailer is beside an active pump or he can smell fumes, and won’t fuel beside another RV. An owner shuts the propane off before pulling up. B. Cole won’t tow with propane burning and says RV fridges are the second-leading cause of RV fires. Others consider the risk very small (An owner, panamerican, an owner). an owner and an owner dispute whether New Jersey requires propane off while towing; an owner found only the NYC bridge and tunnel rules.\"},{\"look\":\"More\",\"action\":\"Propane fridge at fuel stops (cont.) Keeping food cold with the fridge off: an owner: Airstream says 6–8 hours; on a 3-hour drive everything stayed cold. dmatzinger fills the freezer with ice packs overnight; kittmaster pre-cools at home. panamerican keeps an automatic halon extinguisher in the fridge vent compartment when parked, not while moving.\"}]},{\"id\":\"x-dometic-furnace-fan-runs-then-stops-no-ignition-\",\"system\":\"Furnace\",\"title\":\"Dometic furnace: fan runs then stops, no ignition (sail switch and other causes)\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. one owner’s fan ran a few seconds and shut off; the board flashed once every ~3 seconds (“limit switch/airflow” in his manual). A new sail switch fixed it, though the old one looked fine. An owner: the sail switch senses fan airflow before the gas valve opens; access is from the outside cover (on his 2019 the exhaust pipe slides over the furnace pipe, so wiggle it off). paporter removed lint from the switch; persistent says contamination or a weak spring can stop it returning to “off”, and his failed at 7 years; one owner’s died within a year. An owner tests the removed switch with an ohmmeter (zero ohms when actuated); an owner: test the switch itself, off the trailer.\"},{\"look\":\"More\",\"action\":\"Dometic furnace: fan runs then stops, no ignition (sail switch and other causes) (cont.) Other causes owners found: the regulator (An owner, per Jackson Center), a bad control board, a loose ground wire, then dielectric grease, and propane regulator pressure checked by a tech. one owner’s new 2024 FC stayed intermittent even with a new sail switch. Spares: carry one spare sail switch (An owner; an owner carries three); an owner also keeps a high-temperature limit switch. An owner sprays a corrosion preventive around the cover screws when refitting. Shorting the sail-switch wires as a test is excluded here (it bypasses a safety device).\"}]},{\"id\":\"x-vacuum-inner-tube-plywood-shop-vac-dent-removal-\",\"system\":\"Furnace\",\"title\":\"Vacuum (inner tube + plywood + shop vac) dent removal on end caps and roof\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. one owner’s method, worked from the outside: inflate an inner tube (his was for a 15\\\" tire) to about 5 lb so it is round and spongy, lay it around the dent, put plywood on top with a fitting for the shop-vac hose (his was a plastic bottle lid cut to fit the hose tightly), press down and turn on the vac. He used a 16-gallon vac with a clean filter. He says outside air pressure pushes the dent out from behind, so there is less push at altitude; it worked for him at 4,200 ft. His dent had no creases. Results: one owner’s uncreased basketball dent left no sign. one owner’s used 2020 Flying Cloud had a roof dent from the previous owner climbing on the rear end; a suction cup had failed, but a pool ring, plywood and shop vac pulled it out.\"},{\"look\":\"More\",\"action\":\"Vacuum (inner tube + plywood + shop vac) dent removal on end caps and roof (cont.) Limits: one owner’s suction-cup pull left a faint crease trace around the edges; one owner’s creases on a compound-curve corner panel and branch gouges stayed; an owner notes stressed dents won’t come out perfectly. An owner suspects his end-cap dent came from someone kneeling on it.\"}]},{\"id\":\"x-furnace-short-cycling-or-not-igniting-sail-switc\",\"system\":\"Furnace\",\"title\":\"Furnace short-cycling or not igniting: sail switch, limit switch, flame sensor, altitude\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. an owner's sequence: board checks sail switch off, fan starts, sail switch must close, purge, then gas valve and spark, then flame sensing. If the burner lights and then goes out, suspect the flame sensor (clean/adjust per the service manual), not the sail switch; a few minutes then off may be the over-temperature switch. A sail switch should read infinite open and under 1 ohm closed. one owner’s blower-runs-~30-seconds-no-ignition was a bad limit switch, on the plenum above the exhaust with two blue wires; it should show continuity when the furnace is off. LED one flash every 3 seconds points to sail or limit switch.\"},{\"look\":\"More\",\"action\":\"Furnace short-cycling or not igniting: sail switch, limit switch, flame sensor, altitude (cont.) Switch quality: damonbeals and an owner warn against cheap switches (an owner got four bad ones, then bought from Mouser and found a shorted igniter probe); an owner treats them as consumables. one owner’s 2015 lacked airflow to move the sail; switching from part 31094MC to 31093MC (different blade) fixed it up to 9,360 ft. one owner’s “10 ohm” reading was 10 megohms — open. Altitude: one owner’s 2023 short-cycled above ~6,000 ft; an owner blames combustion at altitude; a dealer tapped the gas valve and it improved. aftermath’s 2006 original sail switch still tested good. Jumpering the switch, a pressure-switch conversion and running with the access door off are excluded here.\"}]},{\"id\":\"x-plastic-side-fridge-vents-leaking-into-the-floor\",\"system\":\"Refrigerator\",\"title\":\"Plastic side fridge vents leaking into the floor on small trailers\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. one owner’s 2007 Bambi had rotted subfloor around the fridge; with the fridge out and a fine mist sprayed to mimic rain, water ran down the side and through gaps between the plastic vent and its surround. About half the floor had to be replaced. He swapped to Airstream stainless vents, fastened with stainless screws and 1/4\\\" rubber seal; the metal vent’s interior ridge catches water, and three days of tropical-storm rain left no water behind the fridge. trailerpup had the same leak on a 2006 16 CCD; his 2019 FC has aluminum vents with no trouble.\"},{\"look\":\"More\",\"action\":\"Plastic side fridge vents leaking into the floor on small trailers (cont.) Other fixes: an owner added an aluminum-angle dam inside the vent and an “eyebrow” above it; an owner bolted a UHMW strip across the bottom of the Sport 16 vent as a dam, sealed with RTV, plus insect screens; one owner’s dealer sealed the outside fridge compartment and said not to spray directly at the vents. An owner: fridge vents must be code-approved, which is why the factory used the Dometic vent on the 16 and can’t install the stainless one; composite floors became standard for 2021 (An owner says 2020; one owner’s 2020 23FB shows composite). Some owners suggest closing the vents and using a compressor fridge; DISAGREEMENT: an owner says that needs serious solar/lithium for boondocking.\"}]},{\"id\":\"x-furnace-fan-runs-but-no-heat-sail-switch\",\"system\":\"Furnace\",\"title\":\"Furnace fan runs but no heat: sail switch\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Symptom: blower runs a couple of minutes, no ignition, one red blink on the board — an owner: one blink is the air-flow (sail switch) error. one owner’s Atwood AFMD25141 fired right up after replacing sail switch 31094. Often the switch just needs cleaning: pet hair or fuzz (thezoltar, an owner, Bucky G — four screws hold the outside cover; realign them carefully), dog hair. An owner notes bugs nesting.\"},{\"look\":\"More\",\"action\":\"Furnace fan runs but no heat: sail switch (cont.) Parts: sail switches vary by furnace model; look up by furnace model number (David in Lex); 4pucks fixed a furnace the dealer couldn’t in three visits with Dometic 33082 sail switch with bracket; Dometic sent an owner a free switch after a non-Airstream dealer quoted a new furnace. umasslax lists the ignition sequence.\"}]},{\"id\":\"x-absorption-fridge-flashing-lp-after-highway-towi\",\"system\":\"Refrigerator\",\"title\":\"Absorption fridge flashing LP after highway towing\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Causes owners checked: a dirty burner/chimney or weak flame; the Dometic burner-housing recall (an owner; one owner’s RM3762 fell outside it); a loose burner wire connection; circuit-board contacts cleaned with a pencil eraser; a pinched supply hose under the A-frame. An owner notes it happened at higher speeds and runs the fridge on the inverter from lithium/solar while towing. DISAGREEMENT on towing with propane on: an owner says never; owners (citing a Good Sam table) say it is legal in most of the US except specific tunnels, bridges and New Jersey.\"}]},{\"id\":\"x-furnace-batteries\",\"system\":\"Furnace\",\"title\":\"Furnace / batteries\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. A 2007 International owner woke to 11.9 V after running the furnace overnight (An owner, 2015). A Suburban blower draws about 9 A; one owner estimates a 50% duty cycle as a starting point (drboyd, 2015). The 2007 International's Atwood Hydroflame 8525 is listed at 7.6 A; 10 hours at half duty cycle is about 38 Ah (Lance M, 2015). Several members said the furnace alone should not flatten the batteries overnight and suggested measuring the actual draw and looking for other loads or bad batteries (an owner, idroba, daveswenson, 2015). Batteries pulled below 11 V may never take a full charge again; a load test was suggested (An owner, 2015). The owner later found the batteries were shot (An owner, 2015).\"},{\"look\":\"More\",\"action\":\"Furnace / batteries (cont.) Conservation approaches: a lower thermostat setting with blankets (An owner, 2015); moving to 6 V golf-cart batteries (field & stream, 2015). One owner keeps fire and CO detectors and a roof vent partly open when running gas appliances (drboyd, 2015).\"}]},{\"id\":\"x-dealer-reported-oil-and-metal-on-drums\",\"system\":\"Running gear\",\"title\":\"Dealer reported \\\"oil and metal\\\" on drums\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Dealer reported \\\"oil and metal\\\" on drums. Owners say scoring and a little grease are normal: measure lining thickness and magnet wear before replacing anything. TPMS temperature rising on one wheel, drum over 200 °F vs ~70 °F on the others, plus a \\\"check trailer connection\\\" message: likely a locked brake (spring or adjuster out of place, magnet wires cut). Back off the adjuster to pull the hub.\"}]},{\"id\":\"x-brakes-breakaway\",\"system\":\"Running gear\",\"title\":\"Brakes — breakaway\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Test the breakaway annually: wheels off the ground, pull the pin briefly and confirm each wheel brakes (or hear the shoes, or use a compass at the drum). Do not leave the pin out: it drains the battery. One owner's manual: contact cleaner in the switch and a drop of light oil on the pin every 90 days.\"}]},{\"id\":\"x-front-axle-overload-or-wear-an-owner-found-the-t\",\"system\":\"Running gear\",\"title\":\"Front-axle overload or wear: an owner found the trailer was towing nose-down, putting\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Front-axle overload or wear: an owner found the trailer was towing nose-down, putting too much weight on the front axle. Level the hitch (see 3A.1.1).\"}]},{\"id\":\"x-axles-tires\",\"system\":\"Running gear\",\"title\":\"Axles / tires\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. After a 3 in. Dexter lift, diagonal outer-edge wear at 10,000 miles drew three different diagnoses (alignment within tolerance, install, normal wear). Unresolved; listed only as a caution. Another owner says torsion-axle misalignment comes from the frame mount or worn torsion rubber, not a bent tube.\"}]},{\"id\":\"x-wheels-capped-lug-nuts\",\"system\":\"Running gear\",\"title\":\"Wheels — capped lug nuts\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. The original capped lug nuts have a stainless steel cap over a steel nut that \\\"becomes loose or strips altogether\\\", leaving a smaller nut that is harder to remove. One owner replaced all 24 with solid stainless lug nuts, taking an old nut to a tire shop to match the seat and threads. He swapped them one at a time and rechecked torque on the next trip.\"}]},{\"id\":\"x-small-checks-from-the-favorite-owner-mods-thread\",\"system\":\"Running gear\",\"title\":\"Small checks from the favorite-owner-mods thread\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Owners recommend: Check the breakaway switch; a new one is \\\"CHEAP insurance\\\". If you mount a battery disconnect on the tongue, one owner used #4 wire, sealed the connections. Do not drill the battery box. A tongue-mounted disconnect is owner practice. Seal the connections and leave the box as the maker built it. Another fitted a disconnect partly because his tongue jack \\\"was going up by-it's-self\\\". After a pump failed and leaked, one owner carries a spare and keeps a battery moisture alarm on the floor beside the pump. On newer water heaters that run hotter, an accumulator also gives the water room to expand once the heater's air pocket is absorbed. Bathroom door hinge screws can be only 1/2\\\" long into a brad-nailed board; one owner replaced them with 1 1/4\\\" screws. A rattling Penguin A/C quieted after 1/8\\\" duct insulation tape was added inside the plenum.\"}]},{\"id\":\"x-weight-distribution-and-sway-control-hitches-con\",\"system\":\"Running gear\",\"title\":\"Weight-distribution and sway-control hitches (contested topic)\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported, with strong, unresolved disagreement: Owners broadly agree that set-up matters more than brand. Weigh the rig on a CAT scale (solo, hitched without WD, hitched with WD; one owner cites the Ron Gratz three-pass method) and adjust from the tickets. Several owners say many dealers set hitches up poorly.\"},{\"look\":\"More\",\"action\":\"Weight-distribution and sway-control hitches (contested topic) (cont.) Hitch types owners use: Equal-i-zer, Blue Ox SwayPro, Reese Dual Cam, and Eaz-Lift with separate friction bars (owners advise two bars on 25 ft and larger). The Hensley/ProPride “pivot-point projection” type was praised by its users. Disagreement: critics call that class over-hyped, heavy and long, and one owner says it raises jackknife risk (disputed). Heavy-duty trucks: some 2017 Super Duty owners say WD is not needed (Ford rates the receiver the same with or without WD). Others found too much WD tension on a stiff F-250/F-350 made the rear light and squirrelly, and set minimal tension. A 2004 Duramax owner’s scale passes still showed WD restoring steer-axle weight. Another owner notes his Ram 2500 manual recommends WD above 5,000 lb trailer weight.\"},{\"look\":\"More\",\"action\":\"Weight-distribution and sway-control hitches (contested topic) (cont.) Over-adjustment is a hazard; an owner quotes the Equal-i-zer manual warning that it can cause loss of control and jackknifing. Another owner quotes SAE J2807-based advice to keep WD torque to the minimum needed. Electronic sway control: Disagreement over whether truck electronic stability/sway systems or add-on trailer modules (Tuson) make mechanical sway control redundant. Others call them “belt and suspenders” and note that trailer brakes are not wired left/right separately. If sway starts: owners agree on applying the trailer brakes with the controller’s manual lever and not the truck brakes. Disagreement over whether to accelerate at the same time or ease off the throttle. Test trailer brakes before every trip. Friction sway bars can be disengaged on slippery roads; some owners avoid towing in ice and high wind altogether.\"},{\"look\":\"More\",\"action\":\"Weight-distribution and sway-control hitches (contested topic) (cont.) Payload: several owners found half-ton payload used up quickly by a 28–30 ft Airstream plus a heavy hitch; check the door-jamb sticker for your own truck. Shorter tips: keep a long breaker bar for spring-bar tension; one owner removes WD bars on dirt and gravel roads; lithium batteries save weight compared with flooded batteries.\"}]},{\"id\":\"x-blowing-out-water-lines-compressor-size-pressure\",\"system\":\"Running gear\",\"title\":\"Blowing out water lines — compressor size, pressure, water-heater drain\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Manufacturer + owner-reported, with disagreement marked: Pressure: blow-out air max 50 psi (30 psi on Globetrotter) per the 2027 owner's manuals; the factory inlet regulator is 50 psi per the 2027 owner's manuals. Owners disagree on whether the built-in regulator limits air pressure, and one notes regulators fail and should be verified with a gauge. Several owners say an open faucet keeps the pressure from building.\"},{\"look\":\"More\",\"action\":\"Blowing out water lines — compressor size, pressure, water-heater drain (cont.) Method owners report: drain tanks and low-point drains first. Pressurise with the faucets closed, then open them one at a time, highest first and the low points last, until not even vapour appears, and repeat about 3 times. Include the toilet valve and sprayer, kitchen sprayer and outside shower. Afterwards drain the water that the blow-out pushed into the grey and black tanks. A 2012 25FB owner found a drain valve beside the water heater that the manual did not mention.\"},{\"look\":\"More\",\"action\":\"Blowing out water lines — compressor size, pressure, water-heater drain (cont.) Compressor: tire inflators and tiny units are too slow (a 3 gal / 1.5 CFM unit could not hold 20 psi with one faucet open). Small tank compressors work by letting pressure rebuild between bursts. The 2012 25FB owner used a 6 gal unit and took about 2 hours. A blow-out adapter with its own shutoff valve made it easier. Disagreement: some owners in cold climates say air alone is not enough (one had a cracked shower faucet) and add antifreeze. Others say air alone is fine in mild climates. Antifreeze: use RV/marine antifreeze, never automotive. Owners report using 1.5–5 gallons. Water-heater drain plug: owners replaced the hard-to-reach nylon plug with a small drain valve or a 1/2 in NPT boiler cock. One owner found a boiler cock fouled the gas line on his trailer.\"}]},{\"id\":\"x-parts-owners-point-to-the-gabriel-made-shocks-so\",\"system\":\"Running gear\",\"title\":\"Parts: owners point to the Gabriel-made shocks sold for Airstreams, for example by\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported: Parts: owners point to the Gabriel-made shocks sold for Airstreams, for example by Out of Doors Mart. One owner says they are designed to work roughly horizontally and that ordinary vertical automotive shocks will fail early. Owners replace them in sets. One owner ordered a set after seeing tyre wear that he thought might come from worn shocks. Doing it: the shocks don’t carry the trailer’s weight. Pull the wheel, either by jacking properly or by running the other wheel of a tandem up on blocks, then unbolt the shock and fit the new one. A 3/4 in box-end wrench is reported to work. Leave the first nut loose until the other end is started. On a 2014 International it was a straight swap.\"},{\"look\":\"More\",\"action\":\": Parts: owners point to the Gabriel-made shocks sold for Airstreams, for example by (cont.) Disagreement on older trailers: there may be too little room between the upper stud and the frame. One owner bends the upper mount out slightly with a large wrench and taps it back with a 4×4 and a sledgehammer. Another dislikes bending it and waited to change two shocks until he replaced the axles. On a ’69 Tradewind, one owner says the axle had to be unbolted and lowered.\"}]},{\"id\":\"x-where-to-jack-an-airstream-and-taking-load-off-t\",\"system\":\"Running gear\",\"title\":\"Where to jack an Airstream, and taking load off the axles in storage (contested topic)\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported, with disagreement marked: Axle mounting plate camp: A restorer (a well-known restorer) said every Airstream since 1961 should be lifted only at the axle mounting plate, the vertical steel plate welded to the frame that the axles bolt to. He said the belly “JACK” labels are for stabilizing only, and that lifting there can twist the shell so the door jams. On a single axle he said to jack aft of the wheel. His test: the door should open and close while the trailer is raised.\"},{\"look\":\"More\",\"action\":\"Where to jack an Airstream, and taking load off the axles in storage (contested topic) (cont.) Jack-label camp: owners’ manuals (1971, 1979, 2004, 2017) say to jack at the labelled plate on the main frame rail behind the wheels. One owner photographed factory service in 2007 lifting every trailer at those points with a 10-ton floor jack, then putting stands at the axle plates, and the door still worked. Others used those points with a wood block or a floor jack without damage. Some found the points unusable or felt something was about to bend.\"},{\"look\":\"More\",\"action\":\"Where to jack an Airstream, and taking load off the axles in storage (contested topic) (cont.) Common ground: never jack on the axle tube itself, which can misalign it. Never lift with stabilizer jacks, which are only for stabilizing. Spread the load with wood, especially with a bottle jack, so it doesn’t puncture the belly. Chock the wheels, work on level ground and use jack stands. On a tandem, a ramp under one wheel avoids jacking. Watch tyre shops, who have been seen about to jack on the belly pan or bumper. Storage: some owners put stands under the frame or axle plates to take load off the rubber torsion axles for long storage. Dexter’s service literature is cited as recommending this. Others see no need for 30–45-day stops. One owner bent the plate’s flange with stand cradles. A Bridgestone reply quoted by an owner covers tyre storage: clean, off oil and petroleum, on a barrier, covered from UV and fully inflated.\"}]},{\"id\":\"x-electric-over-hydraulic-disc-brakes-vs-electric-\",\"system\":\"Running gear\",\"title\":\"Electric-over-hydraulic disc brakes vs electric drum brakes (contested topic)\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported, with disagreement marked: Which is better: an owner of Inland RV and several owners call E/H discs clearly superior: more consistent, no fade, easy to inspect and needing no adjustment. Others say well-maintained electric drums are more than adequate for an Airstream’s weight and simpler and more reliable. One owner had two actuator failures and a delay in one year. One owner notes Classics went back to electric drums around 2011–12.\"},{\"look\":\"More\",\"action\":\"Electric-over-hydraulic disc brakes vs electric drum brakes (contested topic) (cont.) Drum upkeep: an owner said standard electric brakes need adjusting about every 2,000 miles. With self-adjusting (Nev-R-Adjust) brakes you just back up a few feet every 1,000–2,000 miles. One owner reports chasing wiring and voltage faults with drums. Controller compatibility: owners found some truck and older controllers don’t work properly with E/H actuators, including one case of erratic braking in the mountains. Solutions they report: a controller with an E/H mode, a Tuson DirecLink (OBD-II), a MaxBrake (reads tow-vehicle brake pressure), or adding brake magnets to the circuit so a built-in controller detects the trailer.\"},{\"look\":\"More\",\"action\":\"Electric-over-hydraulic disc brakes vs electric drum brakes (contested topic) (cont.) Delay is usually air: 4-piston Dexter calipers trap air in the inner half, because the crossover line is at the bottom and the only bleeder is on the outer half. Owners report vacuum or pressure bleeding won’t clear it. One owner rebuilt the hose to allow bleeding at the inner fitting. Single-piston calipers (Kodiak, and Dexter’s 3,500 lb kit) bleed easily, with “nearly instant” braking reported. Tips: a remote switch or the breakaway pin to run the pump without a helper; never let the reservoir run dry; raise the tongue while bleeding. One owner’s delay stopped varying after he added a 2 psi residual-pressure valve; others questioned whether that causes drag. Dexter reportedly said the actuator has no residual valve and that one would not hurt.\"},{\"look\":\"More\",\"action\":\"Electric-over-hydraulic disc brakes vs electric drum brakes (contested topic) (cont.) Dragging and hot brakes: watch rotor and hub temperatures (IR gun or TPMS). Owners traced drag to rust under damaged piston dust boots and to corroded pad anchor points. Prevention one owner adopted: at tyre rotation, clean the pad contact points and apply a light film of caliper grease, keeping it off the friction surfaces. Carry an inverted-flare union and plug so a dragging caliper can be isolated to get home. Excluded: a method of bleeding by inverting a caliper with its pistons blocked by a board. Owners in the thread themselves warned it can eject pistons or crush fingers at actuator pressures (about 1,600 psi), so it is not reproduced here.\"}]},{\"id\":\"x-brake-controllers-types-setup-and-wiring-faults\",\"system\":\"Running gear\",\"title\":\"Brake controllers — types, setup and wiring faults\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported: Types: owners describe time-delay controllers (brake-light input only, such as the Hopkins “Hoppy”/POD) as needing constant manual gain changes between town and highway. Several replaced them. Inertia (accelerometer) units such as the Tekonsha Prodigy/P3 were the most commonly recommended. Pedal-position (Jordan) and hydraulic-pressure sensing (BrakeSmart, Ford’s factory system) also have keen owners. One owner argues all good controllers brake well in practice.\"},{\"look\":\"More\",\"action\":\"Brake controllers — types, setup and wiring faults (cont.) Disagreement on long steady descents: some Prodigy owners found it applied too little braking when speed wasn’t changing. Others say it’s fine when properly set up, and the boost setting helps. Setup: mount the Prodigy aligned fore and aft and not tilted side to side, at 0–70° and never at a negative angle, within the driver’s reach. Use the boost guide in the manual; owners use B-1 on 19–25 ft trailers. One owner raised boost to stop a Hensley-hitch “push” under braking. It powers down when idle, so owners leave it connected to an always-live lead, which also keeps its settings.\"},{\"look\":\"More\",\"action\":\"Brake controllers — types, setup and wiring faults (cont.) Wiring faults owners hit: the wrong GM harness year put the brake-sense wire in the wrong slot, so the brakes applied whenever the headlights came on (fixed by moving the red wire). A cable with the centre wires swapped gave “no ground” and killed cruise control. On some GM trucks a missing under-hood fuse meant the trailer battery wasn’t being charged; one owner suggests an auto-reset breaker there instead of a fuse. One installer routed wiring against the exhaust and the insulation melted. Never test-pull the breakaway pin with the 7-pin plugged into the truck: one owner says it will fry a Prodigy. Disc brakes: owners note some controllers don’t suit E/H disc actuators. Airstream fitted a Hayes Genesis on one owner’s disc upgrade.\"},{\"look\":\"More\",\"action\":\"Brake controllers — types, setup and wiring faults (cont.) Excluded: an owner’s question about towing a trailer home without a working controller (replies note many states require trailer brakes over a set weight; California requires them from 1,500 lb gross). An improvised manual switch from the cigarette lighter to the brake circuit is also excluded.\"}]},{\"id\":\"x-raising-ride-height-dexter-torflex-lift-kits-spa\",\"system\":\"Running gear\",\"title\":\"Raising ride height — Dexter Torflex lift kits, spacers and higher-angle axles\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported: Not a cure for worn axles: an owner of Inland RV said a lift kit does not replace axles whose rubber is worn out, and the shell will still take the shocks. His check: if the torsion arm sits near parallel with an empty trailer, the axles are done. He said they last roughly 25 years, and new axles raise the trailer about 3 in. Others say the best test is lifting the trailer and seeing how far the arm drops, because Dexter builds arms at many start angles (one Sport was built at about 10° up).\"},{\"look\":\"More\",\"action\":\"Raising ride height — Dexter Torflex lift kits, spacers and higher-angle axles (cont.) Options: Dexter bolt-on blocks (about 2■–3■ in, in sizes for #10/#11/#12 axles that aren’t interchangeable). One owner was sold the wrong size through a listing. Dexter told one owner their kits don’t fit Henschen axles. Other options are custom steel channel or tube spacers, or new axles with a steeper start angle (owners mention 32°). An owner cautioned against more than about 5 in, against start angles beyond about 32–35°, and against more than 14.4 in between the two shock studs. Larger wheels (14→15 in) gained one owner 1.1 in. A lift raises tanks, tail and hitch but not the axle-tube clearance.\"},{\"look\":\"More\",\"action\":\"Raising ride height — Dexter Torflex lift kits, spacers and higher-angle axles (cont.) Results: several owners report no noticeable towing change with the 3 in kit, including towing about 1,000 miles and on washboard. One 23D owner and another owner noticed no mpg loss. Downsides they note: a higher step and stabilizers, the hitch ball needing to come up, and alignment found off afterwards in two cases. Installation lessons: mark the axle position on the frame first with a square. Bolt access is tight, so owners ground wrenches thin, cut belly-pan or tank-cover corners, fished bolts in with wire, or welded nuts in place. Gas lines routed through the axle bracket had to be disconnected. Bolts near the shocks needed shortening. One owner paint-marks the nuts to spot loosening. On disc-brake trailers, check brake-hose slack; one owner found it was enough.\"},{\"look\":\"More\",\"action\":\"Raising ride height — Dexter Torflex lift kits, spacers and higher-angle axles (cont.) Safety: work one axle at a time with the other wheels on the ground, or use rated stands, and never work under the trailer with both wheels off one side. Caution: welding anti-turn tabs onto grade-8 bolts was pointed out in the thread as weakening them. That owner planned to replace the bolts. An owner said rear-skid casters damage the rear quarter panels.\"}]},{\"id\":\"x-tires-and-wheels-st-lt-16-upgrades-pressure-torq\",\"system\":\"Running gear\",\"title\":\"Tires and wheels — ST/LT, 16\\\" upgrades, pressure, torque, age (contested topic)\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Manufacturer + owner-reported. Default: set cold tire pressure to the trailer placard / tire sidewall value per your owner's manual; the load-table tips below apply only to weighed axle loads. Lug torque: 110 ft-lb aluminum / 100 ft-lb steel spare per the 2027 owner's manuals. Manufacturer + owner-reported, with tire-engineer and dealer posts identified and disagreement marked. Tires and wheels — ST/LT, 16\\\" upgrades, pressure, torque, age (contested topic) (cont.) Marathon failures: belt/tread separation on ST225/75R15 D Marathons, often low-mileage, even with daily pressure checks; thrown treads tore up wheel wells, scorched a subfloor and (2011) ripped out tank valves, wiring and drains; an 8-year-old Marathon threw its tread on the interstate and a 1994 spare disintegrated on a tongue. Early signs: a bulge or raised area, uneven tread height, a lump that won't spin out (\\\"slipped belt\\\"), a convex profile, a tire that reads a few psi low, a slight rhythmic vibration. A tandem tows normally while a tire shreds, so look at every stop and remove a destroyed tire before limping on. TPMS won't warn of a separation; sidewall depressions/indentations on radials are normal ply splices. Tires and wheels — ST/LT, 16\\\" upgrades, pressure, torque,\"}]},{\"id\":\"x-ground-clearance-dexter-torflex-frame-spacer-lif\",\"system\":\"Running gear\",\"title\":\"Ground clearance: spacer kits, larger tires, and axle angle\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported, with dealer posts identified: Options: (1) Dexter frame-spacer kit (e.g. K71-724-02 for Torflex #11 axles, about 2.88\\\" lift for two axles) bolted between frame and axle mounting plate. (2) Larger tires: 14\\\" to 15\\\" Michelin raised a 23D about 1.1\\\"; 15\\\" to 16\\\" about 1/2\\\". (3) New axles with a steeper arm angle (Inland RV: 32° gives about 1\\\"). (4) A drop hitch, or lumber bridging, for a single steep driveway.\"},{\"look\":\"More\",\"action\":\"Ground clearance: Dexter Torflex frame-spacer lift kits, larger tires, axle angle (cont.) Install notes: the axle label is on the tube. Scribe the axle-to-frame position before loosening so it goes back in the same place. One owner modified a #11 kit (9.5\\\" vs 9\\\" hole centres) to fit Henschen axles. Weld tabs on bolt heads where no wrench fits. A bolt may need trimming to clear the shock body. The shocks mount nearly horizontally, so stroke barely changes. Torque everything; plan a full day for one person. Re-set hitch height afterward. Inland RV warns that the axle tube height (lowest point) does not change, and that 16\\\" tires on old axles can rub the wheel-well cover.\"},{\"look\":\"More\",\"action\":\"Ground clearance: Dexter Torflex frame-spacer lift kits, larger tires, axle angle (cont.) Lifting safely: use the proper jacking points; do not hold the body up on stabilizer jacks. Work one axle at a time with the wheels left on the other axle. Use rated jack stands plus cribbing on a hard surface (boards on soft ground; one owner's stands sank over an inch). Never use concrete or cinder blocks. Warranty: Airstream reportedly said only the modified area would not be covered. Stability (disagreement): owners with 3\\\" lifts (single, tandem and 31 ft, up to about 20,000 miles, including 40–50 mph gusts) report no handling difference. Others argue a higher centre of gravity and more air under the trailer reduce crosswind and rollover margin, and one owner advised against it for a marginal tow setup. Also: a higher first step, more roof height and storage height. Excluded: riding in the trailer to judge the ride.\"}]},{\"id\":\"x-brake-controllers-obdii-based-direclink-vs-accel\",\"system\":\"Running gear\",\"title\":\"Brake controllers: OBDII-based DirecLink vs accelerometer and pressure-based units\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported, plus posts from an engineer who develops products for the maker, identified as such. Install: plugs into the tow vehicle OBDII port and the factory brake-controller plug, with a dash-mounted handset; owners found mounting where the screen and manual lever are reachable hard. Vehicle fit varies (one owner used it on a 2005 Tacoma outside the listed years); check the fit list or the maker.\"},{\"look\":\"More\",\"action\":\"Brake controllers: OBDII-based DirecLink vs accelerometer and pressure-based units (cont.) Setup reported: calibrate at about 25 mph, then do 50 mph test stops; one owner compared drum temperatures with an IR gun after stops and raised gain (factory 3, he settled near 15 to 16) and reduced low-speed (under 30 mph) gain to -2 to -5. Gain can be changed on the fly for wet or gravel roads. New shoes may need less gain after bedding in. A max-brake limit can be set just below wheel lock-up. How it brakes (disagreement): owners argue whether it is truly proportional to pedal pressure; the maker-side engineer says pressing harder brakes the trailer harder. Accelerometer units (e.g. P3) may apply little trailer braking on ice or gravel because the truck barely decelerates; pressure-based units do not need deceleration.\"},{\"look\":\"More\",\"action\":\"Brake controllers: OBDII-based DirecLink vs accelerometer and pressure-based units (cont.) Check your brakes: on the controller current screen expect about 3 to 3.5 A per magnet; current flowing does not prove the shoes are adjusted and working. Corroded grounds and thin wire can drop brake voltage. E/H disc brakes: owners report some factory integrated controllers would not run electric-over-hydraulic actuators (GM before 2015 per one owner, a 2012 Dodge with a Titan pump), giving erratic braking; confirm compatibility before towing. Do not connect two controllers to the brake (blue) wire. Reliability: owners report a handset that buzzed and a display that died (replaced under warranty); manual braking still worked. Excluded: step-by-step splicing of the tow vehicle wiring from a GM service bulletin (for technicians).\"}]},{\"id\":\"x-bambi-sport-lift-dexter-torflex-11-spacer-kit-k7\",\"system\":\"Running gear\",\"title\":\"Bambi Sport lift: Dexter Torflex #11 spacer kit (K71-724-02/-04), measured clearances\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Manufacturer + owner-reported. Which kit: read the axle label. Owners report the 22 ft Sport uses a #11 Torflex (label capacity 4500 lb), and the kit is sold only as a two-axle pair, so owners split kits. One owner was sold a #10 kit (holes 8 in on centre) that did not fit; the #11 kit has holes about 9 in on centre (9.5 in side holes, per another owner). Smaller Sports may use #10 axles, for which single kits exist. A split half needs 8 bolts, 8 nuts and 12 washers (two washers on the vertical bolts).\"},{\"look\":\"More\",\"action\":\"Bambi Sport lift: Dexter Torflex #11 spacer kit (K71-724-02/-04), measured clearances (cont.) Result: about 2 7/8 to 3 1/4 in. One loaded 22 Sport went from 15 to 18 in at the underbody, 7.5 to 10.5 in at the sewer drain, and 8 to 11 in at the spare carrier; axle tube height (10 7/8 in) is unchanged. Owners report no handling change; the step and hitch height rise. Factory Sport torsion arms sit near level when new, so a low ride is not by itself a sign of a worn axle.\"},{\"look\":\"More\",\"action\":\"Bambi Sport lift: Dexter Torflex #11 spacer kit (K71-724-02/-04), measured clearances (cont.) Install: 3 to 5 hours (one owner took all day). Lift at the proper points, set jack stands under the main frame rails fore and aft of the axle, and support the axle with a jack while it is unbolted. Lock nuts need an impact wrench or breaker bar and impact-rated sockets. Lug torque: 110 ft-lb aluminum / 100 ft-lb steel spare per the 2027 owner's manuals. Fit the side-plate bolts first. If a nut will not start, flip it. Re-torque after a few trips. Wear safety glasses. Propane line: on many 2012–2018 units the copper LP line runs through the axle bracket, and owners had to disconnect and replace or re-route it; on 2019 units it was a hose. Others found no line in the way. Where a line touches the bracket, owners added split loom or hose against chafing.\"},{\"look\":\"More\",\"action\":\"Bambi Sport lift: Dexter Torflex #11 spacer kit (K71-724-02/-04), measured clearances (cont.) Warranty: one owner got written word from the factory that the lift would not breach the warranty; some dealers install it and others refuse. Alternatives: curb ramps for one driveway (disagreement: others want clearance everywhere); frame-end rollers (one owner warns of frame buckling). Excluded: raising the trailer on its stabilizer jacks and using whatever is at hand under it; DIY cutting, flaring or bending of the propane line.\"}]},{\"id\":\"x-complete-diy-rewire-of-a-small-trailer-12-v-bus-\",\"system\":\"Electrical\",\"title\":\"Complete DIY rewire of a small trailer: 12 V bus bars, shunt, fuses, wire sizing, 30 A\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. A first-time DIYer rewired a small trailer, with several experienced owners advising. 12 V side: use positive and negative bus bars as the central connection points. A battery-monitor shunt must carry the only negative cable from the battery bank, and the chassis bond goes on the load side of the shunt. Put a non-resetting catastrophic fuse within about a foot of the battery positive, sized above the maximum load but no larger than the cable rating; a self-resetting breaker would just cycle into a short. Size wire by total circuit amps and the round-trip length (Blue Sea chart; the 3% column for voltage-sensitive loads such as fan motors).\"},{\"look\":\"More\",\"action\":\"Complete DIY rewire of a small trailer: 12 V bus bars, shunt, fuses, wire sizing, 30 A (cont.) Owners suggested 4 ga or larger battery cables and 6 ga for a 45 A converter. Fuses protect the wire; on a dedicated circuit, choose the next size above the device's draw (about 20% headroom). Check salvaged cable is copper, not copper-clad aluminium. Use grommets where wires pass through metal, and avoid wire nuts because vibration loosens them. Keep the converter and inverter inside, away from battery fumes and the leaky battery box. Never plug the converter into the inverter.\"},{\"look\":\"More\",\"action\":\"Complete DIY rewire of a small trailer: 12 V bus bars, shunt, fuses, wire sizing, 30 A (cont.) 120 V side: a 30 A main breaker is needed, protecting the cord when adapted to a 50 A outlet. In a small two-space panel, owners used a backfed single 30 A plus a 20/20 tandem. Keep neutral and ground separate in the trailer panel and bond grounds to the frame, including the shell and the copper LP line, using a cleaned, greased lug. A GFCI on receptacles; Romex secured against movement inside walls, MC cable where exposed. An inverter must not be hard-wired to the panel without a transfer switch. At the pedestal: an RV 30 A outlet is 120 V; mis-wired 240 V outlets at homes have destroyed trailers. Check voltage (one owner does not plug in under about 110 V), or use a 30 A EMS with low- and high-voltage cutoff rather than a surge-only protector.\"},{\"look\":\"More\",\"action\":\"Complete DIY rewire of a small trailer: 12 V bus bars, shunt, fuses, wire sizing, 30 A (cont.) A DC-DC charger from the 7-pin gives far more charge than the factory 7-pin wire, which gives about 4–5 A (less at idle). EXCLUDED (unsafe): feeding the panel with a cord from the inverter outlet into the shore-power inlet; there is a backfeed risk.\"}]},{\"id\":\"x-dc-to-dc-charging-from-the-tow-vehicle\",\"system\":\"Running gear\",\"title\":\"DC-to-DC charging from the tow vehicle\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. The 7-pin line charges only weakly because of voltage drop; a DC-DC charger gives the right profile, which matters for lithium (An owner, pboomerx). An owner warned a lithium bank can discharge into the tow vehicle without one. An Orion 12/12-18 can use the 7-pin charge wire (in Airstreams, a black wire to the positive bus bar; confirm with a meter and the wiring diagram, an owner, SVTRIDE). Bigger units need a dedicated fused cable and an Anderson connector (An owner 40 A with 4 AWG and a 60 A fuse; pboomerx 40 A Redarc; an owner and SVTRIDE 30 A). Problems: one owner’s Audi Q7 is fused at 15 A; cycling on and off was fixed by the \\\"smart alternator\\\" setting (Jason P M, thedantons); an owner and SVTRIDE switch it from the running-light circuit, an owner with a hitch-side switch.\"},{\"look\":\"More\",\"action\":\"DC-to-DC charging from the tow vehicle (cont.) Mount away from wood for heat (SVTRIDE, an owner). An owner: 18 A for 5 hours adds about 90 Ah; isolated or non-isolated both work.\"}]},{\"id\":\"x-tpms-sensors-tst-and-others-winter-storage-batte\",\"system\":\"Running gear\",\"title\":\"TPMS sensors (TST and others): winter storage, batteries, cold pressure\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Removing for storage: an owner and an owner take trailer sensors off for winter. An owner removes his if stored more than a week and says to check your manual, as his stop transmitting without air pressure. An owner: left on, they beep about low pressure all winter and wear the battery down. An owner left TST 507s on the first winter and the batteries drained; removed the next winter, they were fine in spring. An owner leaves his on all year indoors and says TST sensors turn off without pressure.\"},{\"look\":\"More\",\"action\":\"TPMS sensors (TST and others): winter storage, batteries, cold pressure (cont.) Batteries: owners say the TST 507 uses CR1632 coin cells. owners advise having TST’s O-ring kit on hand, as the O-rings are easily damaged; one owner’s four took about 45 minutes. An owner says TST recommends changing batteries every 1–1.5 years. An owner replaces them yearly, greases the O-rings with silicone grease, needs a Phillips 000 driver for his flow-through sensors, would not buy flow-through again, and has had two of them fail in four years (carries spares). Keeping track of positions: bag or bottle each sensor labeled by wheel (weirdstuff, an owner), use a divided pill box, record each sensor’s ID number, or use TST’s stickers or a white paint marker.\"},{\"look\":\"More\",\"action\":\"TPMS sensors (TST and others): winter storage, batteries, cold pressure (cont.) Cold vs. hot pressure: an owner saw 75 psi rise to 80 psi within an hour and let air out. An owner: set the proper pressure cold and leave it; don’t adjust a hot tire. An owner (ex-Goodyear) says the sidewall maximum is a cold figure, to set trailer tires to it before starting out, and that running over it when hot is not an issue.\"}]},{\"id\":\"x-squeak-from-the-running-gear-when-walking-inside\",\"system\":\"Running gear\",\"title\":\"Squeak from the running gear when walking inside (Dexter torsion axles, electric drum\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. The noise: a creak or moan when people move inside, often starting around 20,000 miles; an owner lists about ten owners whose trailers match his recording.\"},{\"look\":\"More\",\"action\":\"Squeak from the running gear when walking inside (Dexter torsion axles, electric drum (cont.) Brake backing plates: an owner found surface rust where the shoes rest on the backing plate and no lubrication; a tiny amount of grease at the six contact points stopped it; keep grease off the linings. He located it by feeling the backing plate vibrate while someone rocked the trailer. one owner’s dealer lubed all moving parts of the brakes; after about 6,000 miles over two seasons, no squeak, with the brakes lubed each fall. one owner’s squeak finally stopped after a service that lubricated behind the brakes. An owner cleaned the assemblies and used a silicone brake-assembly lubricant. Jackson Center techs told an owner it is the backing plate and that they have fixed it by lubricating the shoe and plate. one owner’s dealer also found a broken brake magnet.\"},{\"look\":\"More\",\"action\":\"Squeak from the running gear when walking inside (Dexter torsion axles, electric drum (cont.) Axle: Dexter told an owner the axle cannot be disassembled and suggested Zep 45 PTFE spray at the arm, which helped only briefly; replacing axles was the only other option offered. An owner checked spindle-to-housing clearance with a feeler gauge. Other causes owners found: loose or lowered stabilizers (An owner; an owner), a lost shock nut, a heavy fresh tank, the floor trim screws (one owner’s JC tech). Living with it: wheel chocks set before unhitching (An owner; one owner’s X-Chocks), stabilizers down. Tongue height changes the volume. DISAGREEMENT: one owner’s squeak stopped after torquing a lug nut but returned in a day; an owner saw the same.\"}]},{\"id\":\"x-descending-mountain-grades-with-an-airstream\",\"system\":\"Running gear\",\"title\":\"Descending mountain grades with an Airstream\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Slow down before the descent and downshift early (tow/haul or manual mode), letting the engine hold speed. An owner: if you are braking more than 5 seconds in 30, go slower and shift lower. Braking style DISAGREEMENT: several brake firmly in short bursts, then release (wulfraat, an owner ); an owner says heat depends on the speed shed, and prefers one long application. Brake controller DISAGREEMENT: an owner uses brief manual trailer-brake squeezes on grades; owners would not, saying the trailer drums overheat first. An owner raises the controller gain for mountains and lowers it afterwards.\"},{\"look\":\"More\",\"action\":\"Descending mountain grades with an Airstream (cont.) Gain setting: increase until trailer brakes engage just before the vehicle’s; an owner describes setting it just below wheel lock-up at about 30 mph. Check before descending: apply the trailer brakes manually for a moment (An owner; an owner does it each day); one owner’s umbilical came loose on a downhill, leaving no trailer brakes, so check it at every stop. Hazard flashers when slow. Mountain Directory guides for grade information (Blevi, an owner). An owner: on wet or icy roads don’t rely on engine or exhaust braking alone; the trailer can push the truck toward a jackknife. If you smell burning brakes, pull over and let them cool.\"}]},{\"id\":\"x-brakes-tow-wiring-model-agnostic-electric-brakes\",\"system\":\"Running gear\",\"title\":\"Brakes / tow wiring Model-agnostic electric brakes\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Brake-controller installation instructions quoted in the thread specify an automatic-reset circuit breaker (20 A for 1–2 axles, 30 A for 3–4 axles) on the controller's power feed and no fuse on the blue brake-output wire (Ga Pockets, 2005; also an owner, Anon, 2005). Prewired tow vehicles include a fused or breakered brake-controller feed (An owner, 2005). DISAGREEMENT: whether a fuse belongs on the trailer breakaway circuit (Anon vs. An owner, 2005). Electric brake magnets draw about 3–3.4 A each, so circuit sizing grows with axle count (Inland RV Center In, 2005).\"}]},{\"id\":\"x-to-find-leaking-rivets-try-to-stick-your-fingern\",\"system\":\"Leaks\",\"title\":\"To find leaking rivets, try to \\\"stick your fingernail under the rivet heads\\\" around\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. To find leaking rivets, try to \\\"stick your fingernail under the rivet heads\\\" around both sides of the door frame and along the bottom; a black streak is a sign of a leak. If you cannot get a nail under the head, \\\"most likely it is good\\\".\"}]},{\"id\":\"x-fabric-covers-in-contact-with-the-skin-contested\",\"system\":\"Leaks\",\"title\":\"Fabric covers in contact with the skin (contested topic)\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported, with disagreement marked: Majority view: do not put a fabric cover in contact with the skin. Wind moves the cover, and grit under it abrades the clearcoat and aluminum, leaving black swirl/rub marks, worst on corners and end caps. One owner reports cover damage on the front curved panel, plus a hole worn through the aluminum where a grommet rubbed, in under 30 days. Others cite trapped moisture. One owner quotes Airstream Customer Relations (2007): “Airstream does not recommend a cover. The cover can hold moisture and cause the skin to oxidize and will also scratch the finish.”\"},{\"look\":\"More\",\"action\":\"Fabric covers in contact with the skin (contested topic) (cont.) Dissent: a 2007 Classic owner who contacted aluminum and fabric makers says the ban is outdated and bought a custom Sunbrella cover. Another owner who used a soft breathable cover on a 1972 for 2 years saw no new marks. A third owner reports no harm under trees, and says seals and gaskets looked better. Both dissenters stress washing or dusting first, and note that sandy, windy climates differ. A car owner reports dust passing through a breathable cover and damaging clearcoat within a month. One owner says Argosy units have multi-stage automotive paint, unlike Airstream clearcoat. Consensus alternative: a free-standing frame or carport so nothing touches the shell. One owner uses a pole-frame shelter, anchors it, and brushes snow off from inside. Several owners cover tires on the sunny side against UV when parked for long periods.\"}]},{\"id\":\"x-storage-options-compared-indoor-covered-outdoor\",\"system\":\"Leaks\",\"title\":\"Storage options compared — indoor, covered, outdoor\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported: Effects of outdoor storage that owners report: sun and UV wear on seals, caulk, plastic parts, belt-line trim and the sunny-side doors (one owner replaced a UV-degraded A/C shroud and had cracked, leaking skylights in 2 years outdoors). Freeze–thaw in sealant cracks makes leaks more likely. Hail damage was reported by one owner, and pine sap, needles and droppings by others. One 1967 owner reports clearcoat nearly gone and a rotted floor patch after a lifetime outdoors.\"},{\"look\":\"More\",\"action\":\"Storage options compared — indoor, covered, outdoor (cont.) Mitigations reported for outdoor storage: fix roof/window leaks first, keep the trailer waxed and clean, vent it, avoid parking under trees, keep shore power on for batteries and dehumidifiers (Dampp-Chaser rods or DampRid), cover tires, and visit often. In hot desert storage, owners keep buckets of water inside to stop glue joints drying out and clamp adhesive-mounted mirrors. A storage-facility owner (a business perspective) ranks the options: uncovered < canopy ≈ non-climate indoor (watch for mould and mice) < climate-controlled. He advises against fabric covers (finish damage, and wind makes them act like sails) and says poorly built canopies can cause wind damage. Security tips from the same owner: a coupler-insert lock with a hardened bar, and remove valuables.\"},{\"look\":\"More\",\"action\":\"Storage options compared — indoor, covered, outdoor (cont.) Cheap trickle chargers: one owner links a 2016 storage-lot fire to a cheap charger (owner-reported, unverified). Disagreement on covers: two owners use fitted covers (one custom-made, used on dry-climate outdoor storage) while others say covers chafe clearcoat.\"}]},{\"id\":\"x-front-end-shell-separation-fes-and-weight-distri\",\"system\":\"Leaks\",\"title\":\"Front-end shell separation (FES) and weight-distribution set-up (contested topic)\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported, with strong disagreement marked: Symptoms owners report: small buckles or dimples at the lower corners of the front storage-hatch opening, a hatch that becomes hard to open, caulk gaps at the hatch frame, water in the front compartment, a slight crease in the lower rub rail, or the rub rail standing off the front panel.\"},{\"look\":\"More\",\"action\":\"Front-end shell separation (FES) and weight-distribution set-up (contested topic) (cont.) Disagreement on the dimples: a 2014 27 FB owner relays an Airstream service contact’s view that hatch-corner dimples alone are common flex, and that a loosening rub rail is the real sign. A 2021 Classic 33 owner and a 2018 Globetrotter owner say the factory service centre diagnosed FES from the dimples alone and found separation when the panel came off. They advise having it checked under the 3-year warranty. Owners quote about 20 h labour for out-of-warranty repairs.\"},{\"look\":\"More\",\"action\":\"Front-end shell separation (FES) and weight-distribution set-up (contested topic) (cont.) Cause, disputed: many owners blame the design, specifically fewer rib-to-floor attachment points around the front hatch on FB/front-locker models. One owner says ribs on a 28 RB run continuously to the frame. Others blame set-up: overly stiff or heavy bars (1200–1400 lb on a 27–28 ft), excessive WD tension, a stiff ¾/1-ton truck, high tire pressures, or sharp dips such as ferry ramps. Several owners with long mileage on correctly set Equal-i-zers report no damage.\"},{\"look\":\"More\",\"action\":\"Front-end shell separation (FES) and weight-distribution set-up (contested topic) (cont.) Mitigations owners report: lighter bars (several suggest 750–1000 lb), or tapered round bars on chains with separate friction sway control. One owner reports 20,000 trouble-free miles after that change. Others use cushioned shanks (Gen-Y, AirSafe or Shocker air hitch), better truck shocks, lower truck and trailer tire pressures, or removing WD for steep ramps. Disagreement: one owner warns that a Gen-Y shank adds overhang and may reduce WD effectiveness. WD setting: owners disagree on the “within ½ in of the unhitched fender height” rule. Several cite Ford/GM manuals that restore about 50% of the front-fender rise instead (front-axle load restoration of about 30–50%). Read your tow vehicle’s manual and weigh the rig.\"},{\"look\":\"More\",\"action\":\"Front-end shell separation (FES) and weight-distribution set-up (contested topic) (cont.) One owner reports a 2021 Basecamp 16X A-frame bent over a few thousand miles with a 600 lb Equal-i-zer on a Tacoma, set by the manual but not weighed. Other owners question whether WD suits that light frame. One owner quotes a hitch manual warning against towing with WD engaged through ditches, dips and swales.\"}]},{\"id\":\"x-water-heater-drain-plug-leaks-t-p-valve-drips-an\",\"system\":\"Leaks\",\"title\":\"Water-heater drain-plug leaks, T&P valve drips and pressure\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. A cracked aftermarket plastic drain plug sprayed hot water; two plugs from the same two-pack cracked within weeks. Several owners say the plug, not system pressure, was at fault. Suspected causes: the wrong plastic for hot water, under- or over-tightening, or fatigue from repeated removal. Owners advise using the OEM nylon plug or one rated for high temperatures, Teflon tape, and a spare. DISAGREEMENT over brass plugs: some have used brass in aluminium tanks for 14–16 years without corrosion; others keep plastic to avoid dissimilar-metal corrosion and cross-threading. An overheating thermostat or heating element (water near boiling) has been found and replaced; measure the temperature at the faucet, which owners put at about 130 °F.\"},{\"look\":\"More\",\"action\":\"Water-heater drain-plug leaks, T&P valve drips and pressure (cont.) Thermal expansion: the owner quoted the Airstream manual as saying a full cold system builds pressure until the relief valve opens, and that running a cup of water as it heats relieves this. Owners describe the air pocket at the top of the tank as an intended expansion cushion. A T&P valve that drips can be clogged by hard water. Hookups: use an inlet filter and a pressure regulator at the spigot; owners turn city water off when away and overnight. Water reaching the fresh tank while on city water usually means the pump's check valve is leaking. Owners say a trickling sound in the grey tank after using the sink is normal.\"}]},{\"id\":\"x-sagging-or-slipped-glass-shower-door\",\"system\":\"Leaks\",\"title\":\"Sagging or slipped glass shower door\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. This is a common problem: the heavy glass door drops until it catches on the threshold. Factory fix: Airstream supplies nylon spacer blocks (part # 204280, also sold by Woodland Airstream). One goes under the hinge side and one under the latch side, so the door rests on them when closed and while towing. Owners made their own from plastic cutting board, cut with a groove to fit the frame ridge and set in silicone. One owner's block was later trimmed at Jackson Center so the door no longer needed lifting to close.\"},{\"look\":\"More\",\"action\":\"Sagging or slipped glass shower door (cont.) Check the top hinge screw. It can shear, letting the door drop; one owner had the door end up on the floor. Fixes owners used: a longer stainless screw. Do not drill the extrusion. A longer stainless screw is an owner attempt. If the door is slipping, a shop should reset it. One owner replaced the nylon hinge pin with a stainless one (Gordon Glass HPSS2). Another loosened the top Phillips screw, lifted the door and slid the spacer down. Owners also wedge the door's free side while travelling (a cut clothes-peg at the bottom or a small wedge at the top). A 2019 27FBQ owner instead slid a thin piece of aluminium sheet under the bottom hinge while someone held the door up, which gave enough clearance and was still holding years later.\"},{\"look\":\"More\",\"action\":\"Sagging or slipped glass shower door (cont.) DISAGREEMENT about how lasting the fix is. Several owners report blocks working for years. Others found blocks failed, or the glass frame separated. Some owners fitted a Nautilus retractable door from Stoett (about 8 lb) themselves. Owner-reported. The cause is usually a missing or slipped spacer at the top of the hinge. On 2012 doors, an owner found the whole door hangs from one weak top screw, and his had sheared off. Dealer fix (an owner, 2010): a split piece of plastic tubing on the hinge pin in a gap of about 3/16\\\"–1/4\\\". He said rough roads tend to knock it loose.\"},{\"look\":\"More\",\"action\":\"Sagging or slipped glass shower door (cont.) Owner fixes: a plastic spacer or nut under the hinge end of the door. An owner (2014 International) used a shortened nylon chair-leg glide pressed into the broken hinge section, plus a small metal bracket bent at 90° and screwed to the frame to stop the door bouncing upward. an owner (2016 FC) siliconed magnets in place, and Castaway siliconed a 1/2\\\" plastic spacer. Replacements: a Sterling (Kohler) pivot door from Lowe's (about two hours to install), and an Arizona Shower Door full-hinge door (special order) for a 2005 Safari. Tip: lay a flashlight on the floor to spot small dropped parts by their shadows.\"}]},{\"id\":\"x-dometic-310-leaking-at-the-bowl-to-base-seam\",\"system\":\"Leaks\",\"title\":\"Dometic 310 leaking at the bowl-to-base seam\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Symptom: water on the floor only after travelling, coming from the seam between the ceramic bowl and plastic base. Diagnose it with paper taped over the seam; if the area below the seam is dry, suspect the flush valve instead. One owner's explanation is that water left in the cavity in the bowl rim leaks through the inner seal when the toilet moves on the road. Until you can replace it, turn off the toilet's supply valve. DISAGREEMENT about repair: two owners fixed it by removing the toilet and tightening the bowl-to-base bolts or replacing the seal. Others found the centre seal couldn't be replaced, or no part was available, and fitted a new toilet; the original poster did so, with no leaks months later.\"},{\"look\":\"More\",\"action\":\"Dometic 310 leaking at the bowl-to-base seam (cont.) New toilets ordered online arrived damaged or missing screws, so inspect yours before you remove the old one. The rubber floor seal comes with the toilet (it isn't a wax ring). The flush valve is a replaceable part; a mirror against the wall helps you see its screws.\"}]},{\"id\":\"x-modern-glass-shower-door-breakage-causes-and-rep\",\"system\":\"Leaks\",\"title\":\"Modern glass shower door: breakage, causes and replacements\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Temporary fix: a spring curtain rod across the door slots plus a 36-inch curtain. Leave the side frame in place, because a factory replacement comes as a complete assembly. Causes suggested (DISAGREEMENT, no single cause established): door shimmy on rough roads (a top clip that stops all movement helped an owner on an Alaska trip); items stored in the shower; a broken top hinge screw (screws too short — an owner fitted longer stainless ones, and nylon blocks under the door); and high cold tyre pressure. An owner reports no more interior damage since lowering to 60–65 psi cold. The 2023 30RB shattered twice despite careful latching.\"},{\"look\":\"More\",\"action\":\"Modern glass shower door: breakage, causes and replacements (cont.) Replacements: the Stoett Nautilus retractable door (lighter, unbreakable; leave a 3–4 inch gap at the top for steam; caulking is the hardest part), Lexan or plexiglass, or Shower Enclosures of America for frame parts. Removing a 2014 FC frame meant Do not cut the frame with a grinder. If the screws are buried, glass-door replacement is a shop job. An owner says Sikaflex held at the lower guide where silicone failed. Try a warranty claim; glass keeps turning up for weeks.\"}]},{\"id\":\"x-bathroom-stainless-sink-stains-swapping-to-a-whi\",\"system\":\"Leaks\",\"title\":\"Bathroom stainless sink stains; swapping to a white sink\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Garfish swapped the 2020 25GT stainless lavatory for a 13¼-inch Kohler round drop-in. It needed a slightly bigger hole, an adapter from the 1¼-inch tailpiece to the 1½-inch OEM drain, and a new pop-up drain, and it added about 10 lb. An owner did a similar Kohler swap. Keeping stainless clean: Bar Keepers Friend, polishing compound, or an SOS pad to restore it. Then a light coat of mineral oil, Pledge, Sprayway stainless polish, or a sealer to resist spots, or dry it after use. Owners say the galley sink stains far less than the bath one.\"}]},{\"id\":\"x-rear-bumper-hatch-leak-and-floor-rot\",\"system\":\"Leaks\",\"title\":\"Rear bumper-hatch leak and floor rot\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. An owner found the leak where the bumper storage cover, skin and wall U-channel meet. He removed the vinyl insert, screws and rivets of the rub rail, cleaned and caulked the joint, refitted with stainless screws and aluminum rivets, and used Acryl-R on thin seams; updates in 2017–2018 said it was still dry. Keep the tongue raised in storage so water runs off. An owner: use polyurethane or Acryl-R, not both. wahoonc prefers a fabricated L-flashing to sealant. Factory change: from 2012 a tubular rubber seal was fitted between bumper plate and shell. An owner saw a seal plus sealant at the factory and called it an improvement, not a fix; an owner was not impressed. DISAGREEMENT: one owner’s 2012 had no leak, while one owner’s 2014 27FB leaked again after a dealer fix.\"},{\"look\":\"More\",\"action\":\"Rear bumper-hatch leak and floor rot (cont.) Detection: an owner uses a Sonin moisture meter (any needle movement means moisture); an owner (2001 Safari 25) compare against a dry control piece. An owner (2004 28 Safari) found hers with a hose test. Other sources: a pinhole in the license-plate pocket, failed caulk around the compartment frame. Do not drill the bumper tray or the shell. If the floor is soft, a shop should look at the seal and the drain path. an owner ('05 Bambi) replaced the floor and used flexible sealant, not silicone. Fiberglass bumpers have a lip under the belt; a drawer-type bumper (34 ft Excella) avoids this leak but can hide rust under its FRP liner.\"}]},{\"id\":\"x-sealing-the-rear-bumper-rub-rail-joint\",\"system\":\"Leaks\",\"title\":\"Sealing the rear bumper / rub-rail joint\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. An owner (2002 22 ft) traced rot under the rear sink to the bumper joint; Airstream told him the seal behind the rub rail \\\"frequently\\\" works loose. He caulked the bumper/rub-rail intersection with Vulkem 116 and it stayed dry, but the floor needed Jackson Center repair. Water also seeped into the holding-tank cover, which dripped for a day after rain. DISAGREEMENT over sealing the bottom of the trim: Bowmans and 2airishuman warn it can trap water; an owner says if you caulk the gap, caulk the full upper rub-strip seam; an owner notes Airstream leaves the bottoms of tail lights and rub rails open to drain; one owner’s factory tech filled the seam.\"},{\"look\":\"More\",\"action\":\"Sealing the rear bumper / rub-rail joint (cont.) idmtman (2006 Safari LS) unscrewed the rear rub rail, caulked behind it with TremPro 636, sealed its top with Parbond and left the bottom open; a remaining leak was a gap at the right tail light. Parbond tips: it is messy, so use painter's tape and several light passes. An owner (2004 28 International) and Robbie R. (2000 Excella) found wet floor at the bumper; Robbie dried his with a fan for days. An owner: a rotted floor can let the body shift and rip new caulk.\"}]},{\"id\":\"x-where-airstreams-leak-and-which-sealants-to-use\",\"system\":\"Leaks\",\"title\":\"Where Airstreams leak and which sealants to use\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Common sources: roof vents and sealant that hardens and cracks, skylights blown off or cracked, a pano window, a front window gasket, a loose screw behind the lower trim, an antenna mount draining a foot away, the AC bolts (An owner: manual torque 40–50 in-lb), awning-rail supports and missing rivets (Gene, an owner). Fantastic fans: an owner says use only the supplied foam gasket under the flange, no other sealant; an owner (2005 22) found cracked, overtightened flanges with no gasket and replaced the fan.\"},{\"look\":\"More\",\"action\":\"Where Airstreams leak and which sealants to use (cont.) Silicone DISAGREEMENT: Mainstream, an owner and barts say never on Airstreams (failure, residue, possible corrosion); an owner, citing GE Silicones chemists, says cured silicone does not corrode aluminum but prefers polyurethane or EPDM sealants for most jobs. Recommended: Parbond, Vulkem, Dicor lap sealant, Alcoa gutter seal. Walk only on the roof ribs or spread weight with blankets and board. Grandparippr paid for a pressure test with soapy water; Inland RV suggested asking Jackson Center to test a warranty unit in the water-test booth. Temporary fix for a broken-out window: foam board cut to fit the opening, taped in and hidden behind the front gravel guard.\"}]},{\"id\":\"x-tracing-a-rear-window-leak-in-a-classic-25fb\",\"system\":\"Leaks\",\"title\":\"Tracing a rear-window leak in a Classic 25FB\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Water running down the window screen means the leak is above the window frame, not in it. Water travels sideways along hidden structure, so it can appear far from the entry point. An owner, nearly two years of tests: resealed clearance lights, the window and awning-rail rivets, and a A&P replaced the window gasket, then found the street-side and centre clearance lights leaking. A SealTech pressure-and-soap test found two lower leaks but not this one; one owner’s dealer found the same leak with it on the third try. He then taped off roof seams, ran a hose spray for 20–25 minutes at a time and uncovered short sections (An owner suggested removing tape 1–2 in at a time). That traced the drip to rivets on the street-side panel seam, but the leak came back in the next heavy rain.\"},{\"look\":\"More\",\"action\":\"Tracing a rear-window leak in a Classic 25FB (cont.) one owner’s method: work from the bottom up, one seam or light at a time, allow plenty of time for each, tilt the trailer to isolate quadrants; don't drill weep holes. Floor: probe the subfloor with a moisture meter; an owner found moisture where the shell meets the subfloor. On Classics with a fiberglass centre bumper, the top of the rub rail is always suspect. An owner found a curb-side tail-light housing full of water; an owner asked about the licence-plate pocket. Products used: an owner used Captain Tolley’s on rivets and Parbond or Tempro on the window frame. An owner: Acryl-R for thin seams, grey Adseal for the wider rub-rail gap; remove old caulk with plastic tools. An owner also says awning-window anti-chafe tape is normal. Wayne&Sam's '07 leak came from the solar-guard hinge.\"}]},{\"id\":\"x-pressurized-shell-leak-tests\",\"system\":\"Leaks\",\"title\":\"Pressurized shell leak tests\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. kc’s dealer ran a pressurized leak test on his 2020 FC and found many leaks. An owner describes the SealTech system: a fan pressurizes the trailer through the roof-fan opening while soapy water on the outside shows bubbles. one owner’s 2-year-old FC leaked far from the real entry points: a failed sunglass-hinge seal and a vista-view window seal. The test found them faster than hunting by hand. one owner’s 2019 FC leaked only at highway speed in rain. The dealer test found several entry points, and Jackson Center’s own test later found a window leak. one owner’s test found no leaks. DISAGREEMENT on value: an owner and an owner say air escapes at lower pressure than water, so some bubbles may never leak water. Rfriebele and an owner (service staff told him to skip it) question it. kc plans to test annually.\"},{\"look\":\"More\",\"action\":\"Pressurized shell leak tests (cont.) an owner says the factory water-sprays rather than pressure-tests, and the leak warranty is 1 year. An owner notes the awning was installed after the factory water test. Nenabeena (2008 Safari SE) had to replace the rear floor and recommends protecting the rear rail.\"}]},{\"id\":\"x-roof-fan-flanges-cracking-and-leaking\",\"system\":\"Leaks\",\"title\":\"Roof fan flanges cracking and leaking\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Plastic Fantastic Fan flanges crack, often from the screw holes, and then leak. an owner blames the aluminum roof expanding more than the plastic. An owner suggests less screw torque. Install notes: owners ditched the countersunk screws; an owner uses stainless pan-head screws with washers in a bead of Vulkem and has had no cracks in 4 years. one owner’s shop added an aluminum strip under the unsupported side. Tape: an owner likes EternaBond around roof openings. An owner found water trapped under EternaBond where it bridged screws and the flange step, which corroded the roof. An owner went back to butyl tape and Sikaflex 221, which an owner says Fantastic recommended.\"},{\"look\":\"More\",\"action\":\"Roof fan flanges cracking and leaking (cont.) one owner’s 2005 Classic 30 had damp carpet at both front corners. Under thick caulk on the fan he found cracks and trapped water, plus rotted clearance-light sockets. Support: an owner got redesigned, thicker-flange housings free past warranty; by 2018 an owner was told the part was discontinued. Wayne&Sam’s MaxxAir was a near drop-in replacement and never cracked.\"}]},{\"id\":\"x-classic-safari-slide-out-leaks\",\"system\":\"Leaks\",\"title\":\"Classic/Safari slide-out leaks\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Water left on the slide roof: wind-driven rain can blow under the slide awning. The top gasket doesn’t wipe the roof while the slide moves, so water can drop inside as it retracts. An owner squeegees the slide roof first. Drain tubes: each front and rear corner of the slide frame has a small tube that spiders and dirt can block. An owner clears them with about 3 ft of flexible wire, holding the tube; a WD-40 straw was too short. An owner found the factory caulk line where the slide roof tucks under the side wall stopped 1–2 inches short; it is visible only with the slide in. He finished it and added a riveted, caulked aluminum drip edge on the slide awning cover.\"},{\"look\":\"More\",\"action\":\"Classic/Safari slide-out leaks (cont.) Other sources: a skylight or a detached top weather seal. an owner suspect a window or seam and suggest Captain Tolley’s on rivets and seams. An owner suggests parking off-level front to back to see which end gets wet. one owner’s 2004 Safari leaked only with the slide out. one owner’s 2004 Classic leaked while towing in rain.\"}]},{\"id\":\"x-pulling-dents-in-the-end-cap-or-roof-decal-ghost\",\"system\":\"Leaks\",\"title\":\"Pulling dents in the end cap or roof; decal “ghosts”\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Suction pullers: an owner pulled end-cap dents with an automotive suction-cup puller and would work in from the edges; an owner used a compressor-powered suction puller from Harbor Freight “okay”; Bunsen and 3wd67rg pulled dents with a plunger. Glue-on pulling: an owner uses a glue gun and plastic tabs (sold as “Super PDR”), attaching them just inside the dent and working around and in toward the crease, pulling gradually; an owner suggests body-shop adhesive pulling tabs. Both say a crease is stretched metal; for perfect results replace the panel (also an owner).\"},{\"look\":\"More\",\"action\":\"Pulling dents in the end cap or roof; decal “ghosts” (cont.) From inside: on his 2007 27FB, Rhinno cut out the back of an overhead cabinet with an oscillating tool (no inner skin there) and pushed the skin out by fist — no hard tools, which ding the skin. An owner points to his inner-tube, plywood and shop-vac method (An owner also used the shop-vac trick). Decal ghosts: an owner says polishes and fine abrasives didn’t remove shadowed numbers because the decals changed the metal’s color; an owner attributes ghosting to the clear coat’s UV inhibitors and calls it permanent; an owner suggests a larger sticker over it. An owner suggests WD-40 for adhesive residue. DISAGREEMENT: a solvent suggested for ghosts is excluded here; owners warn it risks stripping the clear coat.\"}]},{\"id\":\"x-stabilizer-jacks-up-or-down-in-storage\",\"system\":\"Leaks\",\"title\":\"Stabilizer jacks up or down in storage\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Leave them up: if tires lose pressure the stabilizers end up carrying load, which an owner says can warp the frame and misalign the door (an owner agree); Scott an owner has seen stabilizers bent in storms; an owner sees them as routes for critters. Down: One owner lowers them while working on the trailer in storage; an owner in case tires lose pressure; an owner as a theft deterrent (a drill can raise them in two minutes, so they are not a lock). Howard L.: they stabilize, not lift; a friend bent his by cranking too hard. an owner: level at the wheels and tongue, not with stabilizers. Chock the wheels against wind (tbrowne, urnmor). one owner’s dealer advised leveling to avoid frame twist affecting the door.\"}]},{\"id\":\"x-window-and-seam-leaks-on-newer-trailers-finding-\",\"system\":\"Leaks\",\"title\":\"Window and seam leaks on newer trailers: finding them and warranty routes\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. an owner found leaks in all four panoramic windows and a front seam by pouring water from a bucket. An owner says Airstream water-tests every trailer and calls this unusual; one owner’s panoramics first leaked at about 3 years and needed a second reseal at 11–12. Routes: start with the dealer (what JC told an owner; akarakos agrees), document with Jackson Center early, or go to JC; kc would hose-test and fix a missed caulk spot himself. Hidden damage: one owner’s 2023 Caravel soaked a mattress via the front window, resealed by the dealer; one owner’s 2018 Bambi had wall leaks that rotted the floor (windows replaced, pressure test, seams resealed); an owner notes newer floors are composite.\"},{\"look\":\"More\",\"action\":\"Window and seam leaks on newer trailers: finding them and warranty routes (cont.) an owner: water-leak test every 2–3 years, check interior fasteners every other year and exterior yearly.\"}]},{\"id\":\"x-dust-getting-in-on-gravel-roads-rear-window-and-\",\"system\":\"Leaks\",\"title\":\"Dust getting in on gravel roads: rear window and other entry points\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. An owner found dust entering at the ends of the curved rear window where the gasket doesn’t seal; he tested fit with a four-foot level and a sheet of paper, cleaned, applied Scotch 2242 rubber tape (sticky side to glass, no stretch) on the bottom and sides, and re-adjusted the latches gently, warning the tempered glass can break. Silicone spray alone didn’t help. An owner suggests silicone grease on the rubber and checking for cracks elsewhere, since dust collects where pressure is low. Other entry points he lists: fender wells (Jackson Center recut and sealed his 2006’s), the fridge compartment, floor edges, the door’s non-hinge side, and the rear storage, battery and propane compartments.\"},{\"look\":\"More\",\"action\":\"Dust getting in on gravel roads: rear window and other entry points (cont.) Pressurizing: slofoks and an owner describe facing a roof vent forward to pressurize the interior; an owner asks about Outback-style positive pressure. DISAGREEMENT: an owner and an owner report no rear-window dust; gandttimes and an owner do.\"}]},{\"id\":\"x-replacing-a-leaking-city-water-inlet-regulator-5\",\"system\":\"Propane\",\"title\":\"Replacing a leaking city-water inlet regulator: 50 vs 65 psi\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Manufacturer + owner-reported. A 2018 GT27FB inlet/regulator leaked into the wall; the parts book lists the 50 psi part (601392-06) per the 2027 owner's manuals. The swap took about 3 minutes, but the Shurflo replacement had no gasket; greghoro notes the gasket comes only in an Airstream gasket kit (his was part 365336) and recommends checking your trailer’s parts manual. The pump also pressurizes back to the inlet, so switching to the pump didn’t stop the leak. one owner’s wet insulation dried in a few days with the area left open. Replacement: use the VIN-matched 50 psi part. Alde systems: max 3 bar (about 44 psi).\"},{\"look\":\"More\",\"action\":\"Replacing a leaking city-water inlet regulator: 50 vs 65 psi (cont.) External regulator: most add one at the hose (an owner 45 psi, an owner 40 psi, an owner); an owner and aftermath report campground or home pressure of 100–150 psi. suncoasteng and an owner use the tank and pump instead; an owner turns off city water when away.\"}]},{\"id\":\"x-windows-sticking-to-their-gaskets\",\"system\":\"Leaks\",\"title\":\"Windows sticking to their gaskets\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. The Flying Cloud manual specifies 303 Aerospace Protectant (Airstream part 44845WR-01) on a rag applied generously to the gasket. bcheever, an owner and DCPAS (sheets) report it helps; per an owner, an Airstream service manager at Alumapalooza said to let it dry before closing. An owner treats seals annually to keep them pliable. Others use silicone spray or slide-out silicone lube. DISAGREEMENT: one owner’s Corning 111 grease lasted about a week; DAQ and an owner say windows still stick after everything. Releasing: a plastic scraper, old credit/ATM card, trim tool or bone folder near a bottom corner (An owner, DAQ, an owner, DCPAS, an owner). Opening windows often helps (bcheever, an owner).\"},{\"look\":\"More\",\"action\":\"Windows sticking to their gaskets (cont.) an owner reduces latch tension until a dollar bill pulls out with slight resistance. aftermath’s window poppers worked well but may no longer be sold; an owner links a homemade version. A 2023 owner’s gasket tore on first opening and needed warranty work.\"}]},{\"id\":\"x-rock-guard-spline-popping-out\",\"system\":\"Leaks\",\"title\":\"Rock-guard spline popping out\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. The front window rock guard’s spline kept working out at the top while towing. An owner: spline shrinks with sun/heat or was stretched when installed; use new spline (rock guards use a thicker spline than window screens; an owner had assumed screen size), compress it slightly on reinstall, and don’t bow the frame away from the plexiglass — have someone hold the frame. Fixes: one cut to relieve tension and push it back in (Wayne&Sam; an owner says it works); push it fully home with a wooden shim rather than the roller and avoid crossing frame sections; use a proper spline tool. An owner: the roller alone isn’t permanent. An owner: if the screen/material doesn’t fill the groove the spline won’t stay. featherbedder screws blocks around a frame on plywood so it doesn’t distort.\"}]},{\"id\":\"x-roof-fan-dripping-in-rain\",\"system\":\"Leaks\",\"title\":\"Roof fan dripping in rain\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Causes: gaps in the factory sealing; leaking exterior seals with water held in the housing (An owner Squared); water traveling from elsewhere along wires or edges (tbrowne, Backfortyjoe); screws (an owner sealed each from inside and outside); a hardened foam gasket where the flat flange meets the curved roof (an owner added an aluminum angle inside and sealant under the flange). An owner: leave the inside bezel off and watch during rain. Fan maker replaced one owner’s dome under warranty without returning the old one. An owner: check the whole roof (his skylight, antenna mounts and tank vent also leaked); step only on rivet seams; he uses 3M 4200 on screws. Add-on vent covers let the fan stay open in rain.\"}]},{\"id\":\"x-roof-vent-foam-gaskets-falling-into-the-fan\",\"system\":\"Leaks\",\"title\":\"Roof-vent foam gaskets falling into the fan\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. one owner’s fan jammed when the lid’s foam gasket came loose; the other vent’s had too. Common (an owner kc after 3 months). Replacements: M-D EPDM cellular rubber weatherstrip, M-D high-density PVC foam tape (An owner: remove old foam, clean residue), better foam with 3M weatherstrip adhesive, window weatherstripping, EPDM, U-shaped vinyl edging on the lower ring; Colonial Airstream fitted an aftermarket gasket under warranty. DISAGREEMENT: owners left it off with no issues (An owner notes cold drafts below about 20°F); one owner’s missing gasket let rain in when parked with the street side higher, via the rim drain cutout.\"}]},{\"id\":\"x-the-toilet-water-valve-and-the-kitchen-sink-spra\",\"system\":\"Plumbing\",\"title\":\"The toilet water valve and the kitchen sink sprayer \\\"can easily freeze if not blown out\\\"\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. The toilet water valve and the kitchen sink sprayer \\\"can easily freeze if not blown out\\\". On foot-pedal toilets the valve is open only while the pedal is held down, so one person holds the pedal while the other blows air.\"}]},{\"id\":\"x-one-owner-had-the-black-and-gray-dump-valves-fre\",\"system\":\"Plumbing\",\"title\":\"One owner had the black and gray dump valves freeze in the 20s °F\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. One owner had the black and gray dump valves freeze in the 20s °F. After dumping, add RV antifreeze to the tanks, which also keeps the valve seals moist.\"}]},{\"id\":\"x-winter-camping-occupied-trailer\",\"system\":\"Plumbing\",\"title\":\"Winter camping — occupied trailer\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Owner views differ. Some owners camp through winter without winterizing by keeping the furnace running. One owner who has done this for 7 years in Colorado had \\\"one valve by the toilet freeze and crack\\\" in his first winter. Another owner says that if you stay in the trailer with the heat on, you only need to disconnect and drain the fresh-water hose. Other owners avoid winter towing because road de-icers corrode aluminum, and one had his 28 ft trailer rustproofed.\"}]},{\"id\":\"x-antifreeze-leave-it-in-or-drain-it\",\"system\":\"Plumbing\",\"title\":\"Antifreeze — leave it in or drain it\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Owner views differ. Some owners leave antifreeze in all winter, as \\\"assurance that any water left doesn't freeze\\\" (NE Wisconsin; one had to replace the pump after an air-only winter at −30 °F). Others drain and blow it back out, because \\\"if it gets cold enough it turns to slush\\\". A 1967 Safari owner says antifreeze in the copper pipes \\\"froze and pulled apart\\\". One owner suggests testing your antifreeze in a home freezer first. Owners also disagree on whether modern PEX lines survive a freeze: one says PEX \\\"will withstand a freeze\\\", but faucets, the toilet valve and the water heater will not; another doubts the joints and elbows do.\"}]},{\"id\":\"x-one-owner-says-that-leaving-pink-antifreeze-in-t\",\"system\":\"Plumbing\",\"title\":\"One owner says that leaving pink antifreeze in the bowl let \\\"the gasket warp a little\\\"\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. One owner says that leaving pink antifreeze in the bowl let \\\"the gasket warp a little\\\". He now leaves the bowl empty and coats the seal with Oatey silicone grease, with \\\"no problems\\\" since.\"}]},{\"id\":\"x-calibration-needs-water-in-the-tank-at-the-empty\",\"system\":\"Plumbing\",\"title\":\"Calibration needs water in the tank at the “empty” step\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported: Calibration needs water in the tank at the “empty” step. One owner says most red-LED calibration failures are caused by too little water at empty, and suggests draining a few gallons from full. A 2004 owner reported the opposite: his calibration succeeded only when he started with NO water (disagreement). One owner found calibration much more effective on battery power only, unplugged from shore power: “the Micropulse does not like 13+ volts during cal.” To escape a stuck calibration mode, use the Catcon “reboot” sequence (posted in full; confirmed working by another owner). Inspect the phone-style (RJ) cables at both ends for dirt or corrosion; one owner had to re-terminate a connector.\"},{\"look\":\"More\",\"action\":\": Calibration needs water in the tank at the “empty” step (cont.) The sensor is the grey screw-in plug near the dump valve. Airstream customer relations, as quoted by an owner, said it measures liquid pressure. The bag-of-ice trick is for older probe sensors, not these. A flashing red LED means close to full; solid red means full. Owner-reported: Temperature: one owner found readings “totally off” at 40 °F or below and accurate again in the 50s–60s. Another’s test unit worked fine at 34 °F (disagreement). Burned-out or dim LEDs: Catcon told one owner a 2004 production run had a high LED failure rate and sent a replacement. Swapping the panel: label every connector (masking tape works). You need compression butt connectors, and some Airstream-supplied wires share a color. After a swap, one owner’s battery display reached Full instead of stopping at 7/8.\"},{\"look\":\"More\",\"action\":\": Calibration needs water in the tank at the “empty” step (cont.) Sanity-check the fresh-tank reading by filling from measured jugs. One owner’s 61 gal tank showed 1/8 but took only about 38 gal. By 2019, one long-time owner had given up after “3 control boards in 15 years and at least 10 calibrations”.\"}]},{\"id\":\"x-black-tank-flush-valve-open-vs-fill-and-dump-ove\",\"system\":\"Plumbing\",\"title\":\"Black-tank flush: valve open vs fill-and-dump, overflow risk via toilet and roof vent\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. The sticker under the flush inlet says to use it only with the dump (termination) valve open; one owner notes his 2019 owner manual says to close the valve and fill to about half. Disagreement: many owners close the valve, fill partway with the flush (about 25% to 80% reported) and dump, repeating until the clear elbow runs clear; others keep the valve open and let the rotating spray run, arguing a perfectly clean black tank is unnecessary and the overflow risk is not worth it. Most agree: never walk away.\"},{\"look\":\"More\",\"action\":\"Black-tank flush: valve open vs fill-and-dump, overflow risk via toilet and roof vent (cont.) Use a timer, watch the level monitor (one owner double-presses the tank button so the level stays on for about 5 minutes) or have a second person watch, and remember gauges are often wrong. What overflow does: owners report the toilet overflowing (twice for one owner) and water rising up the vent pipe to the roof, leaking into the walls and between the skins and dripping from many places underneath; one case came from connecting the fresh hose to the flush inlet by mistake. Use a pressure regulator on the flush hose: high park pressure broke one owner's plastic check valve inside the flush inlet. Closing both dump valves while backflushing through a macerator blew a Y-pipe hose off one tank (repair needed the belly pan dropped).\"},{\"look\":\"More\",\"action\":\"Black-tank flush: valve open vs fill-and-dump, overflow risk via toilet and roof vent (cont.) Other habits: dump black first, then grey to rinse the hose; leave a few gallons of water in the black tank after dumping; a bucket of water down the toilet helps clear the last debris; wear disposable gloves and wash hands. Leaving a partly full tank in storage led to flying insects in one owner's toilet. Excluded: removing the warning sticker; filling to 94–100% on the monitor before dumping.\"}]},{\"id\":\"x-separate-hose-for-the-black-tank-flush-cross-con\",\"system\":\"Plumbing\",\"title\":\"Separate hose for the black-tank flush, cross-contamination, inlet layout, bleach\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Disagreement: some owners run the built-in black-tank flush from their fresh-water hose for years with no problem, relying on the inlet's anti-backflow valve; most advise a separate, different-coloured hose (a short or expanding hose saves space) and never attaching either end of the drinking hose to anything non-potable. A vacuum breaker or backflow preventer at the spigot adds protection. Dump-station rinse hoses are usually threadless on purpose and are non-potable.\"},{\"look\":\"More\",\"action\":\"Separate hose for the black-tank flush, cross-contamination, inlet layout, bleach (cont.) Layout: on some Flying Clouds the flush inlet sits directly above the city-water inlet, so drips run onto it. The flusher instructions say to disconnect the hose at the spigot end first and let the line drain before unhooking at the trailer; owners also spray the city-water inlet with bleach solution before hooking up. Bleach solution: owners cite 1 oz to 3–4 oz of household bleach per gallon; a nurse notes mixed solution degrades in about a day, so remix it, wet surfaces thoroughly, and remove visible debris first. Gloves are not a substitute for washing hands. One owner argues municipal chlorine makes this overcautious (disagreement).\"},{\"look\":\"More\",\"action\":\"Separate hose for the black-tank flush, cross-contamination, inlet layout, bleach (cont.) Order: dump black first, then grey to rinse the hose. Grey does not pass through the black tank (with both valves open grey can back into it). One owner's first-ever flush brought out a lot of sludge despite lots of water in the tank. Annual routine from one owner: bleach in the fresh tank, run into grey and black, sit, drain, rinse.\"}]},{\"id\":\"x-black-tank-rv-vs-household-septic-safe-toilet-pa\",\"system\":\"Plumbing\",\"title\":\"Black tank: RV vs household septic-safe toilet paper, the jar/shake test, dumping\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Paper: many long-term owners use household septic-safe paper (Angel Soft, Charmin Ultra Soft, Scott, Costco Kirkland, Cottonelle) without clogs. Others prefer single-ply or RV paper (disagreement; some call RV paper a marketing scheme). Test any brand: shake it in a jar of water and check that it breaks down; Charmin Ultra Soft and Kirkland passed for owners, and a paper towel was still intact after a day.\"},{\"look\":\"More\",\"action\":\"Black tank: RV vs household septic-safe toilet paper, the jar/shake test, dumping (cont.) Habits that owners credit: put water and treatment in before use; use plenty of water; dump at 75% or fuller (one owner fills to about 90%), ideally after road travel; use the tank flush or a rotary rinser, closing the valve, rinsing and dumping again; never leave the tank dry (for storage, about 20–25% water plus treatment). Some keep paper out of the tank entirely in a lidded bin. Additives owners use: dishwasher detergent pods before travel, Dawn, or a borax plus water-softener mix; formaldehyde treatments are reported to be generally illegal now.\"},{\"look\":\"More\",\"action\":\"Black tank: RV vs household septic-safe toilet paper, the jar/shake test, dumping (cont.) Macerators (macerating toilets): what you flush matters far more; facial tissue, paper towels and wipes do not break down and can jam the pump, and undissolved solids can clog campground sewer lines downstream. Excluded: flushing wet wipes and paper towels into the black tank (reported by two owners as working; contradicted by others and a wastewater worker).\"}]},{\"id\":\"x-freeze-damage-the-toilet-flush-valve-dometic-sea\",\"system\":\"Leaks\",\"title\":\"Freeze damage: toilet flush valve and other low points\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. An owner who only opened the drains (no blow-out, no antifreeze) cracked the toilet water valve and the outside-shower fixture. The toilet valve is a low point and holds water unless the pedal is held down while blowing out or pumping antifreeze. Other owners found split copper behind the tub (shower wand not drained) and damage after leaving the water-heater plug in. One owner reports a new trailer that was factory/dealer-winterized also had a frozen flush valve. An RV shop told one owner it sells many of these valves because of freeze damage. Repair (about 15 minutes): the replacement valve comes with a hose clamp; release the old crimp ring by twisting it with pliers, or cut it with a Dremel. Owners say gluing the cracked body will not hold, since the valve is under full pressure.\"},{\"look\":\"More\",\"action\":\"Freeze damage: the toilet flush valve (Dometic/SeaLand 310) and other weak points (cont.) Lubricating the plunger: use silicone (plumber's silicone grease) or glycerine; petroleum products degrade rubber seals. Ideas: pressure-test the system with about 30 psi of air through the city inlet after blowing out; many owners simply pump antifreeze through every line and low point.\"}]},{\"id\":\"x-grey-tank-filling-by-itself-on-city-water-a-meth\",\"system\":\"Leaks\",\"title\":\"Grey tank filling by itself on city water: a methodical leak hunt\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. On a 2016 25 ft Flying Cloud, the grey tank filled to 100% overnight on city water and backed up into the shower; it stopped when city water was disconnected. Owners pointed out that fresh (PEX) and waste (PVC/ABS) plumbing are not connected, so the water had to be entering through a drain. The cause: the shower lever had been left on with only the handheld head's pause button closed, and the seepage was hidden under a translucent shower mat. Turning the lever off fixed it.\"},{\"look\":\"More\",\"action\":\"Grey tank filling by itself on city water: a methodical leak hunt (cont.) Troubleshooting steps from the thread: turn off city water, pressurize with the pump and time the cycling; put stoppers in every drain to see which one collects water; wipe fixtures dry and use paper as a wet/dry witness; check the outdoor shower (on one owner's Classic, its compartment spigot also drains the water heater); on some trailers, the city/fresh-fill plumbing can be reached through the back of the wardrobe. A 2004 Safari owner notes a cracked toilet valve can leak unseen into the shower drain. Turn city water off at night or when away; one owner's fresh tank overfilled through a failed valve and buckled the floor.\"}]},{\"id\":\"x-water-spraying-from-a-belly-pipe-when-the-toilet\",\"system\":\"Plumbing\",\"title\":\"Water spraying from a belly pipe when the toilet flushes: an unlisted low-point drain\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. On a 2014 Flying Cloud bunkhouse, fresh water poured from a small PVC pipe beside the sewer outlet every time the macerator toilet was flushed. A dye test showed it was clean water. The two brass low-point drains and the fresh-tank drain were all closed. The cause was an extra low-point drain valve for the toilet supply, left wide open at the factory, hidden behind the drawers next to the water pump. The manual doesn't show it. A 2008 27FB owner found a similar undocumented low-point drain (for the cold line into the water heater) below the bypass valves, which Jackson Center confirmed. Check for extra drains when winterizing and de-winterizing.\"},{\"look\":\"More\",\"action\":\"Water spraying from a belly pipe when the toilet flushes: an unlisted low-point drain (cont.) The pump still came on briefly every few minutes; an owner pointed out that this means a leak. The cause was a dripping water-heater drain plug: it stopped after the nylon plug was replaced with enough Teflon tape. To avoid cross-threading, turn the plug backwards until it drops into the thread, then tighten. Keep spares; Atwood advises against brass plugs (dissimilar metals). Re-tighten the hand-tightened sink traps, which work loose on the road. Drawers coming open in transit (2014 full-extension slides held by two small screws): add screws in the spare slide holes, fit stronger or adjustable catches, use bungees between cup hooks, or take the drawers out and set them on the floor for travel.\"}]},{\"id\":\"x-getting-solids-to-clear-a-dometic-gravity-toilet\",\"system\":\"Plumbing\",\"title\":\"Getting solids to clear a Dometic gravity toilet\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Problem: waste sticks to the bowl and needs a lot of fresh water (or a brush) to flush. Tips owners used: half-fill the bowl first by partly pressing the pedal; Airstream's toilet label says to fill it half full. Lay a cross of toilet paper over the valve opening; use Happy Bowl liners; add a squirt of soapy water or a few drops of dish soap before going; fit a bidet hand sprayer (one owner's replacement flush valve came with a sprayer connection) or use the shower wand if it reaches. Use enough water each flush so paper and solids don't build up into a mass in the black tank. DISAGREEMENT: some hold the valve open while going, but others say that wastes water and lets tank odour in, especially when an exhaust fan is running. Lubricant: silicone spray; the guide does not recommend oils.\"}]},{\"id\":\"x-object-dropped-into-the-black-tank\",\"system\":\"Plumbing\",\"title\":\"Object dropped into the black tank\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. DISAGREEMENT over whether to remove it: several owners say a toothbrush is unlikely to block anything and can be left in the tank, while others say it will restrict dumping, catch paper and jam the dump valve, so it must come out. Methods owners suggested: partly fill the tank so the object floats, then fish it out with a grabber tool; flush with a backflush wand (Flush King-type) and watch the clear section of hose; spray a garden hose down the toilet towards the dump valve; use a light and a mirror. What worked: a plumber's flexible inspection camera (Ridgid \\\"SeeSnake\\\") found the toothbrush wedged in a crease in the tank. A coat hanger freed it, and it then caught in the dump valve until it was pulled out with the hanger.\"},{\"look\":\"More\",\"action\":\"Object dropped into the black tank (cont.) One owner found that pulling the toilet off the floor gave the easiest access. Owner-reported. Try a flexible claw retriever, a bent coat hanger, or two wires (one lifts, one hooks the handle hole); wear gloves and bag the item. The owner couldn't see the brush, so he filled the black tank, dumped it (the outlet's right angle wouldn't pass it), and planned a garden-hose current to bring it into view. Others recommend pulling the toilet for access; an owner replaced both the flapper and floor seals while it was off. Another option is having a dealer do it. Prevention: tie a cord to the brush handle, or use a long-handled brush.\"}]},{\"id\":\"x-dumping-tanks-with-a-macerator-pump-or-a-water-p\",\"system\":\"Plumbing\",\"title\":\"Dumping tanks with a macerator pump or a water-powered Sewer Solution\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Water-powered Sewer Solution: several owners like it because it is clean, easy to store and can pump uphill to a raised sewer inlet. It is slower, though, needs a supply of water (so it won't work at dry dump stations), and uses a lot of water. Owners avoid using it when there is a queue at the dump station and carry an ordinary sewer hose as a backup. DISAGREEMENT: one owner dislikes it and finds the standard hose fastest.\"},{\"look\":\"More\",\"action\":\"Dumping tanks with a macerator pump or a water-powered Sewer Solution (cont.) Electric macerators (FloJet, Jabsco, Thetford Sani-Con): dump black first, then grey to rinse the hose. A permanent FloJet means you can never drain by gravity, whereas the Sani-Con has a grey-water bypass. One owner's test with clean water: about 6 gpm through 50 ft of 5/8-inch hose at 0 and 10 ft of lift, and still flowing at 18 ft. Another owner says solids should be lifted only about 4–5 ft. Long runs need 1-inch hose to limit back pressure. Owners say macerators can't handle baby wipes or paper towels; one needed new seals after a wipe was flushed. Secure the discharge end so it can't blow off the sewer inlet, and fit a 45° clear elbow so the pump body drains and you can see the flow.\"},{\"look\":\"More\",\"action\":\"Dumping tanks with a macerator pump or a water-powered Sewer Solution (cont.) If you use the flush fitting for anything else, never connect a fresh-water hose to it without a backflow preventer. Fittings: Airstream outlets are 3 inches; Thetford and Valterra bayonet fittings differ, so carry an adapter.\"}]},{\"id\":\"x-tankless-versus-a-6-gallon-tank-heater-owners-tr\",\"system\":\"Water heater\",\"title\":\"Tankless versus a 6-gallon tank heater: owners' trade-offs\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. DISAGREEMENT on whether tankless is worth it. For: endless showers on hookups; less propane (one owner used a single bottle of propane over three weeks); no anode, tank or mixing valve to maintain; easier winterizing. A Truma AquaGo weighs less and removed about 48–50 lb of stored water; it has a single drain lever and a freeze-protection mode; and because it is narrower than a 6-gallon Dometic, the installer added studs to close up the opening. The PrecisionTemp RV-550 fits the 6-gallon Atwood opening, which on two trailers was a little short and needed slight enlarging.\"},{\"look\":\"More\",\"action\":\"Tankless versus a 6-gallon tank heater: owners' trade-offs (cont.) Its two-second ignition delay gives a cold burst whenever flow is restarted, and it needs at least 0.4 gpm. Against: a plumber says tankless units are less reliable than tank heaters. Girard and Suburban units shut down at a trickle or need full flow. Tankless wastes water and grey-tank space while it comes up to temperature, which matters when boondocking; Truma owners say they get no cold slug. Several full-timers are content with the 6-gallon tank and its cheap, widely available parts. The \\\"extra 6 gallons\\\" in a tank heater is only reachable by draining it, so it is not usable reserve.\"},{\"look\":\"More\",\"action\":\"Tankless versus a 6-gallon tank heater: owners' trade-offs (cont.) Recirculating loop: Suburban's instructions forbid recirculating already-hot water through the heater.\"}]},{\"id\":\"x-swapping-a-plastic-toilet-for-a-china-dometic-31\",\"system\":\"Plumbing\",\"title\":\"Swapping a plastic toilet for a china / Dometic 310/320 27' International FB (\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Why china: harder to scratch, easier to clean, won't yellow, and closer to a household size. Owners report it adds little weight; one linked Dometic's spec sheet when asked. Swapping a plastic toilet for a china / Dometic 310/320 (cont.) Models named: Dometic/SeaLand 310 (taller; the favourite of one owner after an 11-year search, and reported as factory-fitted in some models); SeaLand Traveler and Traveler Lite (the Lite's seat is flimsy; its bowl separates from the base and can be angled a few degrees); Thetford Aurora and Style II (Style Plus reportedly won't fit). A rinse sprayer helps clean the bowl but is one more possible leak. Order with heavy packaging, because one bowl arrived broken. Swapping a plastic toilet for a china / Dometic 310/320 (cont.) Fit in a 27' FB is tight: a dealer said a SeaLand wouldn't fit without moving the wall. One owner gained about 1/8\\\" by re-bolting a factory flange that was off-centre, and trimmed the plastic vacuum-breaker cover. A later replacement 310 had a bigger china back, and he cut its corner with a Dremel Saw-Max and a ceramic blade. Measure the clearance behind the toilet before buying, because returns are often refused. Bolt pattern: a 2-bolt toilet can use two slots of a 4-bolt flange. If the slots aren't at 3 and 9 o'clock, one owner screwed brass studs into the 3 and 9 h\"}]},{\"id\":\"x-preventing-a-pyramid-in-the-black-tank\",\"system\":\"Plumbing\",\"title\":\"Preventing a \\\"pyramid\\\" in the black tank\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Cause: not enough water. Owners agree you should put a gallon or two of water in the black tank after dumping and before use, fill the bowl before #2, flush generously, and hold the pedal down for a rinse. Keep the black valve closed on hookups and open it only to dump, with the tank as full as possible; add water first if it isn't. Dump the black tank first, then the grey to rinse the hose. Travel agitation: driving with water in the tank (some add a bag of ice) helps knock loose solids that have built up. Toilet paper: test it in a jar of water. It should break up within minutes. Avoid quilted multi-ply. Treatments: DISAGREEMENT between enzyme and chemical treatments. Some owners avoid formaldehyde-based chemicals and say enzymes work better; others use whatever brand they like.\"},{\"look\":\"More\",\"action\":\"Preventing a \\\"pyramid\\\" in the black tank (cont.) A Dometic/Thetford spray wand saves water while cleaning the bowl. Grey reuse when boondocking: one owner showers with the plug in and bails the water into the toilet. A composting-toilet conversion means removing the black tank. Vintage units with only 10–15 gallons of black capacity limit how much water you can add.\"}]},{\"id\":\"x-cracked-toilet-water-valve-thetford-aqua-magic\",\"system\":\"Plumbing\",\"title\":\"Cracked toilet water valve (Thetford Aqua-Magic)\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Cause: owners agree it is usually freezing. The valve is a low point and cracks if it isn't blown out or filled with antifreeze. Remember the sink sprayer and the outside shower too. Part: Thetford 09868 (Aqua-Magic valve replacement package), from Inland RV and other suppliers. Access: the toilet comes off with two closet bolts (7/16\\\" nuts); the valve is held by two screws and a nut. When reinstalling, it is easier to secure the rear bolt first. Supply line: several owners swapped the rigid copper feed for a flexible braided line, which they think reduces stress on the plastic valve and makes it easier to remove; one owner thought it could be done without removing the toilet.\"},{\"look\":\"More\",\"action\":\"Cracked toilet water valve (Thetford Aqua-Magic) (cont.) Fittings into the plastic valve: hand-tight with Teflon tape. One owner cracked a new valve by over-tightening it, and JB Weld did not save it. The closet gasket goes on the right way up; check the manufacturer's instructions.\"}]},{\"id\":\"x-dometic-300-310-320-bowl-won-t-hold-water\",\"system\":\"Plumbing\",\"title\":\"Dometic 300/310/320 bowl won't hold water\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Check the seal is the right way up (it is marked); Airstream found one fitted upside down. Clean the seal and the slide valve, and keep the seal wet when stored. Hot-water method: press the seal into place, pour hot (owners said boiling) water over it and leave it to cool; an owner said this is in the toilet manual. Results varied from fixed to about 12 hours. One owner questioned pouring boiling water into a porcelain toilet; check your manual first. Lubricant: use silicone grease or Thetford seal conditioner; petroleum products (Vaseline, plumber's putty) attack rubber. Seal part numbers 385311658 and 600346163 appear to be the same kit.\"},{\"look\":\"More\",\"action\":\"Dometic 300/310/320 bowl won't hold water (cont.) If new seals keep failing, check the ball's mating surface for scratches, and consider the seal between the upper and lower bowl (brown stains around the screws underneath suggest it is leaking; it can't be replaced). Several 2024–25 owners got replacement toilets from Dometic under warranty after reporting a defect. Contact Dometic or your dealer. Splashing while towing: leave only a little water in the bowl.\"}]},{\"id\":\"x-composting-toilet-conversion-nature-s-head-air-h\",\"system\":\"Plumbing\",\"title\":\"Composting toilet conversion (Nature's Head / Air Head)\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Odour: users say there is no sewage smell while the fan runs, only a faint peaty smell. One owner had bad smells. Common causes are urine getting into the solids tank, coir that is too wet, a fan that isn't working, or waiting too long to empty. Keep the coir just moist, and two full-timers emptied the solids about every two weeks. Routine: the liquids bottle needed emptying about every other day for two people. Owners differ on toilet paper (bin or solids tank). Installation: Airstream at Jackson Center fitted a Nature's Head in a 2019 Globetrotter and sealed the cleaned black tank. A Canadian installer piped urine into the former black tank and joined it to the grey tank. Owners debated whether urine belongs in the grey tank.\"},{\"look\":\"More\",\"action\":\"Composting toilet conversion (Nature's Head / Air Head) (cont.) DISAGREEMENT on whether it is worth it. Boondockers favour it; owners with hookups prefer a standard toilet, and one owner thought it hurts resale value. Alternatives mentioned: Laveo dry-flush toilet, and bowl liners or Wag Bags.\"}]},{\"id\":\"x-leaking-toilet-supply-fitting\",\"system\":\"Leaks\",\"title\":\"Leaking toilet supply fitting\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. The plastic winged nut on the 90° supply elbow came off in a 2017 owner's hand and the line sprayed. Shut the water off; the toilet can be flushed with a bucket meanwhile. Owners recommended cutting out the failed fitting rather than reusing it. Options: a crimp PEX fitting (ring and tool) or a push-on SharkBite. Cut an ear clamp through the ear to remove it. Newer Airstreams use PEX (one 2013 owner); one owner thought older lines were polybutylene, which needs matching fittings. Crimp exactly square to the pipe. A dealer's SharkBite repair still wept at the back. Leak-finding tips: put a mirror under the elbow, use food colouring or tissue, and test under pressure, because a hairline crack can open as the pressure rises. Keep shore pressure at about 40 psi with a regulator.\"},{\"look\":\"More\",\"action\":\"Leaking toilet supply fitting (cont.) Also suspect the toilet's water valve, which can crack if winterizing missed the toilet or the sprayer. Warm water from the cold tap: one owner thinks the water heater's air pocket pushes hot water into the cold line. Fitting shut-off valves at each fixture makes later repairs easier. Warranty: Airstream agreed to cover the fitting; contact Airstream or Dometic/Thetford support.\"}]},{\"id\":\"x-adding-a-non-electric-bidet-attachment\",\"system\":\"Plumbing\",\"title\":\"Adding a non-electric bidet attachment\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Parts (2017 27FB): a 1/2\\\" SharkBite tee in the toilet supply line (cut out about 3 cm of pipe to keep the original geometry), a 1/2\\\" × 3/8\\\" compression adapter for the bidet hose, and a short piece of PEX. Several owners added a shut-off valve, either a separate valve or a SharkBite service-stop tee with a 3/8\\\" outlet. Option without cutting pipe: one owner noted that RV toilet inlets are 1/2\\\", unlike household toilets, and used a matching 1/2\\\" adapter. Push-fit fittings need a square, deburred cut but no crimp tool; a cheap plastic tool removes them. Cold water only. Owners reported up to 90% less toilet paper and less risk of clogging the black tank. Winterizing: one owner held a cut-down antifreeze jug over the bidet so the spray went into the bowl. Owners in mild climates only blow the lines out with air.\"},{\"look\":\"More\",\"action\":\"Adding a non-electric bidet attachment (cont.) Check the seat bolt spacing before buying a new seat; RV toilets vary.\"}]},{\"id\":\"x-sewer-solution-water-jet-macerator-vs-standard-s\",\"system\":\"Plumbing\",\"title\":\"Sewer Solution (water-jet macerator) vs standard sewer hose\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. How it works: a water jet from a garden hose breaks up waste and pushes it through a 1\\\" hose, so it can pump uphill or a long way (owners used 50' of conduit to a home cleanout). Valterra makes it. DISAGREEMENT. Long-term users (1,400–1,700 nights) prefer it at full-hookup sites. Others went back to a standard hose because it is 4–5 times slower, needs a water supply at the dump, won't fit the bumper storage tube, and one owner watched solids still coming out with the tank flush afterwards. Many carry both. Hygiene: use a separate hose for it, never your drinking-water hose. One owner added a brass check valve to back up the plastic one.\"},{\"look\":\"More\",\"action\":\"Sewer Solution (water-jet macerator) vs standard sewer hose (cont.) Faults: if it fills the tank instead of emptying it, check the nozzle is aimed straight at the outlet and not cross-threaded. Valterra replaced one owner's crooked head. A short clear extension helps if the valve handles get in the way.\"}]},{\"id\":\"x-macerating-toilet-flying-cloud-26u-bunkhouse\",\"system\":\"Plumbing\",\"title\":\"Macerating toilet (Flying Cloud 26U / Bunkhouse)\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. The 26U has a factory SeaLand/Dometic 8100-series macerating toilet that pumps to the black tank through a small line. Several 26U owners reported no problems after a learning curve. One owner holds the main flush for about 5 seconds and the refill for about 3. Risks: a former RV technician repaired many failed motors, pumps and circuits. Boat owners warn that \\\"flushable\\\" wipes and string wrap around the shaft, and that blockages usually collect at the rubber duckbill \\\"joker\\\" valve. Carry spares or a rebuild kit. A 2014 Bunkhouse owner had one jam that blew the fuse, and found it used a lot of water. Lubrication and toilet paper: follow the Dometic manual. Have a backup plan if your only toilet fails, such as bowl liners.\"}]},{\"id\":\"x-toilet-bowl-won-t-hold-water-slide-valve-seal\",\"system\":\"Leaks\",\"title\":\"Toilet bowl won't hold water (slide valve seal)\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Yes, the bowl should hold water; the water keeps tank odours out. First steps: clean debris or calcium out of the seal groove (wear gloves; tie a string to any tool you use so you can't drop it), lubricate the seal with a toilet seal lubricant, and let your foot off the pedal quickly or lift the pedal slightly so the valve closes fully. One owner replaced the seal ring on a Dometic 300 in minutes without taking the toilet apart. Another got a seal that wasn't centred working by nudging the top half of the toilet until it centred. New trailers: one owner's pedal mechanism failed and another's seal cracked; both were replaced with a new toilet under warranty. Use a product made for RV toilet seals; vegetable oil goes gummy over time.\"},{\"look\":\"More\",\"action\":\"Toilet bowl won't hold water (slide valve seal) (cont.) To keep the seal from drying out, leave water in the bowl in storage. One owner moved to Prestone RV antifreeze after a no-name antifreeze turned a rubber part to mush. Until it's fixed, ventilate with a roof vent or window open, and don't run exhaust fans, which pull gas from the tank.\"}]},{\"id\":\"x-bidet-seats-and-attachments-25-27fb-flying-cloud\",\"system\":\"Plumbing\",\"title\":\"Bidet seats and attachments 25; 27FB Flying Cloud; owners' trailers as stated\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Owners fitted non-electric bidet seats or attachments (Lux/Luxebidet, Brondell Thinline, GenieBidet, Biffy), or used portable bidets or a hand sprayer instead. Plumbing: a 1/2\\\" tee is needed; one owner said the Brondell's supplied 3/4\\\" tee does not fit, and used a 1/2\\\" male × 1/2\\\" female × 3/8\\\" tee. A Luxebidet owner added a 1/2\\\" tee and a longer hose. A 27FB owner used a SharkBite tee, a short piece of PEX and a 1/2\\\" NPT adapter. One owner rebuilt the PEX run with short fittings and enlarged the floor hole to fit it. Space is tight; check there is room for the controls. On one 25 the seat sat slightly off-centre. Add a valve on the supply line, because the knob can give a sudden high-pressure jet.\"},{\"look\":\"More\",\"action\":\"Bidet seats and attachments (cont.) The water is cold, which one owner did not mind. It adds a little water to the black tank but saves paper. Owners who boondock for long periods noted it suits trailers with hookups.\"}]},{\"id\":\"x-toilet-overflowing-on-city-water\",\"system\":\"Plumbing\",\"title\":\"Toilet overflowing on city water\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Manufacturer + owner-reported. One owner woke to clean water overflowing the bowl and the black tank full while on city water. Likely causes: debris in, or failure of, the flush water valve (one owner found trash in his old valve); a faulty O-ring made worse by high pressure (factory techs repaired one under warranty and replaced the inlet regulator). 2airishuman noted that the black-tank flush needs its own hose connection, so a normal water connection can't fill the tank through it. Prevention: close the toilet's supply shut-off (it is hard to see, behind the toilet) at night and when away, or turn off the city water and use the pump. Use an external pressure regulator. The factory inlet regulator is 50 psi per the 2027 owner's manuals. In some trailers the bathroom sink drains into the black tank.\"},{\"look\":\"More\",\"action\":\"Toilet overflowing on city water (cont.) Related: a fresh tank slowly filling on city water usually means a faulty check valve at the pump. A pump that \\\"burps\\\" with all taps closed means either the pump is defective or there is a leak; one owner suggested a variable-speed Shurflo or Flojet pump, which is quieter.\"}]},{\"id\":\"x-factory-composting-toilet-trade-wind-basecamp-an\",\"system\":\"Plumbing\",\"title\":\"Factory composting toilet (Trade Wind/Basecamp) and storage\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Airstream's support page, as quoted in the thread, says the solids can stay in between trips if the 12 V fan runs continuously; otherwise empty them before storage. A 2024 Trade Wind owner said solar should keep up with the fan in uncovered storage. A 2015 30RBQ full-timer said the batteries can run the fan for months if the fridge and Multiplus are off. Agitate the medium once or twice a month in storage. One owner whose crank stiffened in 110° heat added a little water. A fan installed backwards (blowing into the trailer) caused bad smells; reversing it fixed this.\"},{\"look\":\"More\",\"action\":\"Factory composting toilet (Trade Wind/Basecamp) and storage (cont.) In the factory Trade Wind setup, urine goes to the black tank, and the bathroom sink drains there too. There is no crossover, so cascading grey into black means opening both valves to let the tanks equalise through the drain pipes. One owner fitted a cap with a garden-hose fitting for this. Emptying intervals reported: 10–14 days for two people, every 3 weeks, and every 4–6 weeks (geewhiz, Trade Wind). Urine jugs on separate-container units: every couple of days to 3–4 days. Some campgrounds ban putting black bags in dumpsters. Grey water is regulated like black water in most areas, so assume it must go to a proper system. Airstream doesn't do the initial setup, and one dealer's techs were unfamiliar with it.\"}]},{\"id\":\"x-toilet-and-water-system-before-towing\",\"system\":\"Plumbing\",\"title\":\"Toilet and water system before towing\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Most owners leave a little water in the bowl to keep the seal wet and close the lid; it rarely sloshes. If the bowl won't hold water, the seal may be bad. One 2019 owner's bowl never held water. To empty it, shut off the pump or city water and hold the pedal until it stops flowing. DISAGREEMENT on storage: some leave the bowl dry for winter with the seal lubricated (Oatey silicone, or a silicone toilet conditioner); others leave a cup of antifreeze to keep the seal wet. Turn off the pump for travel and relieve the pressure. Owners described single-lever kitchen faucets vibrating open on the road and flooding the floor when the sink drain was plugged. Water in front of the toilet after rain turned out to be a leaking bathroom vent seal; renew the gasket under the vent lid.\"},{\"look\":\"More\",\"action\":\"Toilet and water system before towing (cont.) The 2014 FC has a quarter-turn supply shut-off beside the toilet.\"}]},{\"id\":\"x-fitting-a-sealand-dometic-traveler-to-an-old-fla\",\"system\":\"Leaks\",\"title\":\"Fitting a SeaLand (Dometic) Traveler to an old flange\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. The Traveler uses a 4-bolt base. Old Thetford flanges and vintage threaded flanges don't line up, and the toilet would sit crooked. Options owners used: (1) the SeaLand Universal Mounting Ring Kit (part #310139 in 2006), which screws over the old flange with a bead of silicone and adds about 3/8 inch of height, helpful over a new floor; (2) rotating a threaded flange, which worked for Janet H, but a shop refused to force a seized one on a 1960 for fear of breaking the tank neck; (3) modifying the flange, which was judged risky. Replace a warped plastic flange first. Seal: use the bowl seal supplied with the toilet, not a household wax ring. one owner’s manual specifies a bead of glazing compound around the flange in wet baths and showers.\"},{\"look\":\"More\",\"action\":\"Fitting a SeaLand (Dometic) Traveler to an old flange (cont.) Caution (an RV shop): heavier china toilets tend to work loose and leak in travel. An owner had no leaks after about 500 miles. A wooden shower deck gained a short user about an inch; finish it with water-based polyurethane.\"}]},{\"id\":\"x-replacing-a-rusted-toilet-flange-sealing-an-rv-t\",\"system\":\"Leaks\",\"title\":\"Replacing a rusted toilet flange; sealing an RV toilet\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. A rusted, wobbly flange: an owner fitted a new plastic floor flange from a hardware store (True Value) on a 1967 and rebuilt the original toilet with parts from the same store. RV supply shops also stock flanges. A seized threaded flange may need a home-made black-tank wrench (Rick O.). one owner’s rusted flange screwed out easily, and he replaced the toilet with a Dometic Traveler Lite 210. Sealing: use the foam floor gasket, not a household wax ring. Wax won't cope with trailer movement and eventually leaks. The Traveler manual calls for extra sealant only in a shower or wet bath. Bidet seats (Toto Washlet, Smart Bidet) were suggested; the Washlet needs 120 V.\"}]},{\"id\":\"x-city-water-hose-on-the-black-tank-flush-inlet-fl\",\"system\":\"Plumbing\",\"title\":\"City-water hose on the black-tank flush inlet; flood clean-up Safari; FC 25RB; unnamed\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. What happened: a city-water hose connected to the black-tank flush inlet flooded the trailer, with water coming up through the shower and onto the floor. The likely path (one owner’s Safari; an owner): the black tank overfilled up its vent, which on trailers with one roof vent is joined to the grey vent, then the grey tank filled and backed up through the shower drain. an owner alternative cause: a shower head left on 'almost off'. Prevention: colour-tape the flush inlet and matching hose ends; turn the campground spigot off when leaving; after hooking up, check every faucet is off.\"},{\"look\":\"More\",\"action\":\"City-water hose on the black-tank flush inlet; flood clean-up (cont.) Clean-up: treat it as diluted black water. Disinfect wet surfaces with a mild bleach solution, discard rugs and towels, and replace the fresh-water hose. Promptly drop at least a corner of the belly pan to check the insulation; remove wet fiberglass to avoid mould. an owner uses large flat washers under the belly-pan fasteners on refit. Check the vent stack for leaks. Getting underneath: use ramps or levelling blocks, or the tongue jack with heavy-duty chocks. Don't hold the brakes on with the breakaway cable. Floor jacks in the wrong place can bend the light frame.\"}]},{\"id\":\"x-fitting-a-taller-or-elongated-ceramic-toilet-dom\",\"system\":\"Plumbing\",\"title\":\"Fitting a taller or elongated ceramic toilet (Dometic 320)\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Check the flange-to-wall distance: 9 inches on one owner’s 25 FB and 12 inches on one owner’s 30'. An owner found the 320 needed about 10 inches. A dealer couldn't fit one in a 27FB, and one owner’s 27 EB lacked the clearance without moving the plumbing base. Offset flanges were suggested but nobody reported using one in an Airstream; check the tank-to-floor depth first. Alternatives: a seat riser on the stock toilet (about 15.5–16 inches high), a raised open-front seat, or a male-compatible seat for the round 310. Bluto trimmed a corner off a 310 to fit his 27'. A low-profile model used about an extra inch front and back in a 23D.\"}]},{\"id\":\"x-bidet-or-washlet-seats-in-an-airstream\",\"system\":\"Plumbing\",\"title\":\"Bidet or washlet seats in an Airstream\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. one owner’s dealer fitted a Toto Washlet to his 2010 25' International. This meant swapping to an RV toilet with a larger bowl, adding an outlet, and teeing into the toilet's water line. He estimates under 400 W with the seat and water heating, and says it adds less than a quart of water per use; his grey tanks still fill first. Check clearance behind the toilet and bowl size first. Electric seats can be a steady battery draw on an inverter (An owner, a plumber, estimates 400–900 W). Non-electric attachment bidets were suggested for a 2016 23D. Consider extra fresh-water use if boondocking.\"}]},{\"id\":\"x-rv-toilet-paper-vs-ordinary-single-ply\",\"system\":\"Plumbing\",\"title\":\"RV toilet paper vs ordinary single-ply\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Many owners use ordinary single-ply septic-safe paper (Scott original, not 'extra soft'; Charmin Basic, which Charmin told one owner had been tested for RV tanks) with no problems. Smokin Camel, a state septage coordinator, says most single-ply paper breaks down within hours. One owner found thick paper had plugged the outlet, making the tank look full. Tank care: travel with a few gallons of water (with detergent, per an owner) in the black tank to slosh it clean, then dump on arrival. Paper or debris can foul tank sensors.\"}]},{\"id\":\"x-odour-control-for-separatin-g-composting-toilet-\",\"system\":\"Plumbing\",\"title\":\"Odour control for composting-toilet urine jugs\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Suggestions for the urine jug: empty it daily so it doesn't age (rvlife, Nature's Head, who notices no odour otherwise); add a little sugar (short term) or an enzyme digester such as Nilodor (medium term); float a tablespoon of vegetable oil on top; or use Happy Camper. One owner found vinegar in the jug made it smell worse. Between uses, clean a spare jug by soaking it with Lemi Shine. Spray vinegar and water on the bowl after urine-only use. Unique cleaner or Nature's Miracle can be used on the bowl and surrounding surfaces. Do not plumb the urine diverter to the grey tank; that makes it a black tank (odour, treatment needed).\"}]},{\"id\":\"x-the-toilet-side-sprayer-use-it-upgrade-it-or-rem\",\"system\":\"Plumbing\",\"title\":\"The toilet-side sprayer: use it, upgrade it, or remove it\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Several owners rely on the sprayer to clear stuck paper and marks, because RV toilets flush weakly, especially on the pump. It also uses less water than flushing when boondocking. Others rarely use it or removed it; one said rinsing didn't make the tank sensors read correctly. Alternatives: an adjustable spray bottle or squeeze bottle kept behind the toilet. A missing sprayer head is the common kitchen-sink type from a hardware store. Jlawrence fitted a separate shut-off valve for his sprayer. One owner's sprayer line leaked behind the toilet after a hard winter.\"}]},{\"id\":\"x-choosing-a-replacement-rv-toilet\",\"system\":\"Plumbing\",\"title\":\"Choosing a replacement RV toilet\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Fit is the main limit: the Dometic 310 bowl was too big for the 86 Limited. The Thetford Aqua Magic V or Style Plus fit tight bathrooms (An owner, mikextr, an owner). A Thetford Style II was the largest porcelain bowl that fit a Bambi's rough-in. DISAGREEMENT on Dometic: one owner’s 2012 310 leaked at the bowl-to-base seam and could not be repaired. Martee traced a 2018 leak to a cracked flush valve after rough roads and now carries a spare. An owner said his 2017 one works great. one owner’s 2019 Masterflush leaked, and black water came back up. Simple gravity designs are preferred by some. A porcelain seat raised 1 in helped an owner. Lower option: a Dometic 321 fitted a 23FB directly in about 30 minutes; Thetford makes low-profile versions that should bolt on directly.\"}]},{\"id\":\"x-sewer-smell-when-a-roof-or-exhaust-fan-runs\",\"system\":\"Plumbing\",\"title\":\"Sewer smell when a roof or exhaust fan runs\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Causes owners suggested: a powerful roof fan with no window open can pull tank gases through drain traps or a bad seal, so open an air source first. Other causes were a dried-out toilet seal from never leaving water in the bowl, a dry shower P-trap, a failed sink vent valve, and an open black valve at a hookup. Air flowing at the base is not normal; check the floor gasket and the two mounting bolts, and have a new gasket on hand before removing the toilet (Ken K-THOR, 2airishuman). The owner suspected storm-repair work. Tank cleaning: a spray wand, a Flush King (Gene), or ice plus water before a drive (Mikethefixit, an owner). Keep valves closed at hookups and dump on a schedule.\"},{\"look\":\"More\",\"action\":\"Sewer smell when a roof or exhaust fan runs (cont.) The owner's \\\"green\\\" product made no deodorizing claim, and he switched back. Owner-reported. Running a range-hood or roof fan with everything closed pulls replacement air from somewhere (Dexterpix, an owner); an owner: grey and black share a roof vent, so air comes down it. Fix reported by owners: open a window or another vent (ideally upwind and away from tank vents) before running an exhaust fan. An owner traced his 27FB smell to the black-tank-flush vacuum breaker behind the wardrobe knee wall: debris from the hose had held it open; cleaning it let it seal. He now uses a screen washer at the flush inlet. Also check: shower re-vent below the wardrobe, that roof vent pipes actually protrude and are sealed, and the tank/valve adaptor.\"}]},{\"id\":\"x-new-toilet-not-holding-water-seal-lube-and-blade\",\"system\":\"Leaks\",\"title\":\"New toilet not holding water: seal, lube and blade\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Clean under the seal lip and in the blade groove. An owner used a bent screwdriver (Thetford sells one) tied to his wrist with string, and an owner used a toothpick and noted calcium deposits under the gasket. An owner advised holding the valve fully open when flushing, so solids are not trapped in the seal. Lubricants: an owner, Jacob D, owners use silicone plumber's grease (one owner’s link actually went to plumber's putty, which is a different product), and an owner used silicone dielectric grease. An owner uses Thetford drain-valve lubricant. An owner suggested stopping enzyme tabs in the bowl and said cheap RV antifreeze ruined his seal.\"},{\"look\":\"More\",\"action\":\"New toilet not holding water: seal, lube and blade (cont.) Warranty: one owner’s 2016 FC20 gasket was repaired under warranty, and an owner got about 7–8 years from a seal. On one owner’s 2016 FC 27FB, the white pivot part kept popping out; the dealer had seen the same fault in another toilet. An owner found the white part was not returning to the sealed position. Avoid kitchen oils: they can over-soften seals and go rancid.\"}]},{\"id\":\"x-composting-toilet-nature-s-head-odour-in-wind\",\"system\":\"Plumbing\",\"title\":\"Composting toilet (Nature's Head) odour in wind\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. one owner’s fan vents into the roof plumbing stack. The smell came and went on windy days, even though the seals and fan were OK. Nature's Head suspected wind blowing back through the roof rain cap. With the fan hose blocked there was no smell, so he fitted a 4 in PVC end cap over the roof vent; the outcome was not reported. Nature's Head sells an anti-wind vent cover, and an owner said a Camco directional vent cured a sewer smell. an owner cleans the fan screen every time he changes the coir, because dust reduces airflow. blkmagikca pipes urine into a combined black/grey tank. An owner (not a Nature's Head user) suggested a trap in that line to keep tank fumes out.\"},{\"look\":\"More\",\"action\":\"Composting toilet (Nature's Head) odour in wind (cont.) DISAGREEMENT: an owner thinks composting toilets are expensive and hurt resale, and prefers bag liners. An owner said fresh water, not black-tank capacity, is the limiting factor. Posts suggesting disposal on the ground were excluded (see the exclusions log).\"}]},{\"id\":\"x-electric-dometic-push-button-toilet-not-respondi\",\"system\":\"Plumbing\",\"title\":\"Electric (Dometic push-button) toilet not responding\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. A Dometic push-button toilet stopped responding to all three buttons while on full hookups. Suggestions: check that the toilet water shut-off valve on the floor behind it is open. An owner suggested killing all power, including the batteries, to reset the control, and looking for a blown fuse in a panel or behind the toilet. An owner said Dometic manuals are online but need the exact model number. The outcome was not reported. DISAGREEMENT: owners see an electric toilet as needless complexity with no manual backup, while wkerfoot needs his electric marine (macerating) toilet because it pumps uphill and over 20 ft to a tank that can't sit under it.\"}]},{\"id\":\"x-swapping-an-old-thetford-for-a-bravura\",\"system\":\"Plumbing\",\"title\":\"Swapping an old Thetford for a Bravura\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. 3Ms75Argosy: the front flange nut is under the pedal (loose nuts there were a likely odour source). The rear nut is blind; he reached it from the curb side by feel with a short spanner, using a camera to locate it. An owner described an access cover at the back left under the seat. Lessons from his swap: connect the water line before bolting down. Have someone ready to kill the pump if it sprays; holding the pedal half down fills the bowl without spilling. A previous owner had fitted a 3/8 in line where the toilet needed 1/2 in pipe thread; a 30 in braided 1/2 in pipe-to-pipe hose from the dishwasher aisle fixed it. The new seat opened only about 85–88 degrees against the backrest. An owner on the 1973 Argosy: check the hinge offset against the backrest before buying.\"},{\"look\":\"More\",\"action\":\"Swapping an old Thetford for a Bravura (cont.) an owner (2001 Excella): Thetford replaced two leaking-blade toilets free, and the swap was as easy as at home. An owner said the Bravura's pop-out front gives access to both flange nuts. an owner found the water line the hardest part.\"}]},{\"id\":\"x-toilet-paper-and-black-tank-habits-various\",\"system\":\"Plumbing\",\"title\":\"Toilet paper and black-tank habits various (\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. one owner’s jar test: RV paper broke down almost at once, while Costco \\\"septic safe\\\" paper took much longer. An owner did a similar test and stays with RV paper. DISAGREEMENT: an owner (4 years, no chemicals), owners use ordinary household paper with no problems. Mikethefixit avoids expensive \\\"wet strength\\\" paper. An owner says Scott with an enzyme treatment dissolves, while Charmin with chemicals did not. Steve & Susan see paper dissolve only after a day's towing.\"},{\"look\":\"More\",\"action\":\"Toilet paper and black-tank habits (cont.) Habits reported: a clear connector at the dump valve to judge rinsing (Steve & Susan, an owner). An owner blamed most black-tank problems on too little water after dumping. Mikethefixit and an owner never let the tank go dry. An owner adds 2–3 gallons before a trip and once ran ice in the tank while driving to clean it. An owner uses an enzyme treatment and deliberately doesn't rinse fully at dumps. An owner found repeated sprayer cycles needed.\"}]},{\"id\":\"x-leak-over-toilet-360-siphon-tank-vent-cone-not-g\",\"system\":\"Leaks\",\"title\":\"Leak over toilet: 360 Siphon tank-vent cone not glued\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Symptom: in heavy or sideways rain, water drips from the ceiling seam above the toilet. Root cause found by owners: the funnel cone in the Lippert 360 Siphon roof tank vent was loose rather than glued to the cap as the manual requires. Water gets past it and runs down the outside of the pipe where the pipe isn't sealed to the gasket. Fix: remove the caulk and screws, glue the cone to the cap, reinstall and reseal (about 15 minutes). An owner has had no leaks since; djz reported it to Airstream, who passed it to production.\"},{\"look\":\"More\",\"action\":\"Leak over toilet: 360 Siphon tank-vent cone not glued (cont.) Alternatives: an owner, The an owner, wave man and laferic fit a 4 in PVC cap over the vents (an owner notes it is permanent and mud daubers may nest). an owner screws an upside-down bowl over the vent; a frisbee once the bowls degraded. one owner’s stack pipe was too short for the roof fitting. Also check the bath fan: an owner found water entering through the 6 screws under the cap and sealed them; Farmer an owner replaced loose cover foam.\"}]},{\"id\":\"x-toilet-waste-hanging-up-above-the-black-tank\",\"system\":\"Plumbing\",\"title\":\"Toilet waste hanging up above the black tank\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. one owner’s 2007 had waste and paper sticking in a narrowing below the toilet valve. one owner’s 2014 Eddie Bauer has a straight drop of the same size and suggested a previous owner’s reducer; an owner says the toilet should sit on a foam ring on the tank flange with no reducer; an owner wonders about a household wax ring with a conical insert. an owner found a reduction in her own pipe. one owner’s floor had been redone under the toilet. Water: fill the bowl about half to three-quarters before solids, and flush twice if needed (an owner Awchief). an owner: a weak flush may mean a restricted vent. An owner later concluded too much paper and too little water, and flushed the tank repeatedly.\"},{\"look\":\"More\",\"action\":\"Toilet waste hanging up above the black tank (cont.) Paper and wipes: no tissues; RV-approved white paper, not colored or patterned; an owner finds RV paper brittle and uses single-ply Scott. An owner bags other items for the trash. Tank: an owner and an owner — keep the black valve closed until the tank is at least a third full, and check that it isn’t leaking past. An owner: nearly fill the tank with water and septic enzymes, let it sit a couple of weeks, drive around corners, dump, then refill and dump until a clear bayonet adapter shows clear liquid. An owner says a curb-side toilet can leave mounds because of the tank’s slope. Rinse: owners use the sprayer hose beside the toilet.\"}]},{\"id\":\"x-water-on-the-floor-by-the-toilet-dometic-toilets\",\"system\":\"Plumbing\",\"title\":\"Water on the floor by the toilet (Dometic toilets)\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Supply connections: one owner’s 2015 FC leak behind the toilet stopped after hand-tightening a connection; an owner found the nylon inlet fitting at the back base loose, and the dealer later found the floor wet under the vinyl. An owner also suspects the supply line or its connection to the toilet. Splash-over while towing: TSOMMY flushes, turns the pump off and flushes again before travel; an owner keeps about 1/2 inch in the bowl, saying 2 inches can splash out. one owner’s Dometic toilet in a 2016 FC wouldn’t hold water at the ball valve; after two failed dealer fixes, a Camping World (Dometic dealer) contacted Dometic, which shipped a replacement toilet free.\"},{\"look\":\"More\",\"action\":\"Water on the floor by the toilet (Dometic toilets) (cont.) Other sources: the under-sink filter (kesslerb; an owner says the bypass hose or filter needs a washer on each end), the water-heater relief valve draining toward the bath on some layouts. Shakedown: test every system — fill the tanks, run all faucets from pump and city water, the black-tank flush, heat and A/C — before leaving the dealer (Lily&Me, an owner). Pressure regulator: an owner and 12 wheeler say there is one built into the inlet; Awchief and an owner also use an external one.\"}]},{\"id\":\"x-black-tank-gauge-reading-high-on-a-newer-trailer\",\"system\":\"Plumbing\",\"title\":\"Black-tank gauge reading high on a newer trailer\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. one owner’s 39-gal tank read 67% after 1.5 days. After a professional clean (back-flushing and a three-nozzle wand), a fill test read 71% at 20 gal and 98% at 23 gal. An owner: SeeLevel strips are adhered outside the tank, so with a clean tank he suspects a slipped or mis-mounted strip; readings fit a straight line ending about 1/3 below the top; strips are hard to see. Cleaning methods reported: ice and water drive; Kleen Tank-style pressure wash and repeated reverse flushing (OCRV, Kleen Tank of Austin: back-flush to about 80% of tank size with a flow meter, leave a few gallons in); Tank Blaster. An owner: fill to see water at the toilet, check 100%, drain, check 0%; recalibration instructions may be on the maker’s site (he writes “Garetts”).\"},{\"look\":\"More\",\"action\":\"Black-tank gauge reading high on a newer trailer (cont.) DISAGREEMENT: an owner thinks 67% may be real if a lav sink drains to black; an owner says the Trade Wind bathroom sink goes to black, an owner says his goes to grey. an owner and Keys Dave check with a flashlight; one owner’s 2024 sensors settle after a day or two.\"}]},{\"id\":\"x-black-tank-valve-won-t-fully-close-debris-in-the\",\"system\":\"Plumbing\",\"title\":\"Black-tank valve won’t fully close: debris in the outlet\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. one owner’s valve stopped 3/4\\\" short; a pipe inspection scope showed a wad of what looked like caulk, which he pulled out with a hanger. Others found caulk-tube tips or the plastic disc cut out when the toilet hole is drilled (An owner; one owner’s disc eventually blocked the valve). An owner thinks it may be molding “drool” and harmless. An owner had scraps come out early; a backwash device kept valves clear. an owner: a big water-only flush for construction debris. an owner: open and close the valve a few times as contents flow to keep the seat clear, but go easy if something solid could jam it. Ultraclassic disassembled, cleaned, wet-sanded and lubed a valve jammed by organic debris.\"}]},{\"id\":\"x-one-owner-s-manual-p\",\"system\":\"Body & gear\",\"title\":\"one owner’s manual (p\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported: one owner’s manual (p. 92) said to use kerosene and NOT antifreeze. Another owner replied that the manual probably predates pink RV antifreeze, which is what owners now use. A 1988 Excella owner’s lay-up checklist is also posted.\"}]},{\"id\":\"x-undermount-galley-sink-dropping-away-from-the-so\",\"system\":\"Body & gear\",\"title\":\"Undermount galley sink dropping away from the solid-surface counter\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Failure: the undermount sink drops away from the solid-surface counter, sometimes completely. Most owners had been carrying items in it, but others had not. Causes owners found: wood strips glued to the counter's underside with a thin bead over cutting dust (white residue); a cutout built from separate plywood pieces, so one piece coming loose overloads the others; only a few clips; front clips that can't be reached (one 2022 owner found them unscrewed); and clip screws that worked out or stripped their inserts.\"},{\"look\":\"More\",\"action\":\"Undermount galley sink dropping away from the solid-surface counter (cont.) Repairs owners did: (1) Remove the counter and re-bond it upside down so gravity helps. Jackson Center did this for one Classic and it held, and one owner used VHB tape plus re-glued blocks and had no trouble over 3,000+ miles. (2) Drop the sink, re-glue the substrate with construction adhesive, and add hardwood cleats screwed to the cabinet sides; one owner drilled access holes to reach the front clip. (3) Before any failure, add L-brackets screwed into the cabinet sides beneath the strips that tend to fall. (4) Glue the sink and refit the clips with threadlocker, adding new clips on corner braces at the front. For a temporary hold on the road: a tension curtain rod, gaffer tape, or a jack and 2x4. Disconnect the P-trap first, and re-tighten trap fittings (one came apart in transit and soaked the drawers).\"},{\"look\":\"More\",\"action\":\"Undermount galley sink dropping away from the solid-surface counter (cont.) DISAGREEMENT on adhesive: Airstream support named Bostik 1100 or Adseal, one dealer used Lord adhesive, and owners used Sikaflex 221, VHB, or high-adhesion silicone; one owner cautions that a silicone sealant is not the same as an adhesive. Many simply stopped carrying anything in the sink.\"}]},{\"id\":\"x-stainless-lavatory-sink-tarnishing-or-rusting\",\"system\":\"Body & gear\",\"title\":\"Stainless lavatory sink tarnishing or rusting\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. DISAGREEMENT on the cause: a low-grade stainless supplier (An owner, heslinhotel); bleach or chlorides causing pitting (An owner, Jim an owner); or products used nearby. Silvertwinkie and an owner saw no problem. Roaminhomies had the sink replaced, and the marks came back. Cleaning owners used: Bar Keepers Friend, Bon Ami, Soft Scrub or Scrubbing Bubbles (greenflag, an owner). Clean with the grain, and avoid green Scotch-Brite pads. Prevention: wipe the sink dry after use. Avoid bleach and Clorox wipes, rinse off salt or acids, and do not leave steel wool or other steel in the bowl (Jim an owner). DISAGREEMENT: an owner used a polish barrier, but an owner advised against wax. An owner replaced the sink with a Kohler porcelain one.\"}]},{\"id\":\"x-light-scratches-in-the-clear-coat-e-g-from-bushe\",\"system\":\"Body & gear\",\"title\":\"Light scratches in the clear coat (e.g., from bushes)\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Wax won’t remove scratches; a compound is needed, then wax to protect. An owner: if you can feel it with a fingernail it may not come out completely. Mild products: 3M Finesse with a buffer, or an auto detail shop (an owner, who warns old-fashioned rubbing compound is too abrasive for clear coat); Meguiar’s Ultimate Compound with a DA polisher; Griot’s Paint Glaze; Scratch Out / an owner; Simichrome by hand with a cotton cloth, a little at a time, about 4 hours. An owner: Airstream clear coat is much softer than a car’s; go with a fine compound and go light or you can blow through it (an owner agrees). an owner: getting most of the scratch out is usually enough.\"}]},{\"id\":\"x-waxing-a-clear-coated-airstream-by-hand-or-with-\",\"system\":\"Body & gear\",\"title\":\"Waxing a clear-coated Airstream: by hand or with a buffer\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Newer Airstreams have a clear coat, so the goal is protection, not a mirror shine; wax like a car. Soyboy confirms a 2005 has a factory clear coat. Machines: an owner has waxed his 2001 every year since new with a Craftsman orbital and thin wax-application pads (Meguiar’s Gold), removing residue by hand, and has seen cautions that lamb’s-wool pads can burn the clear coat; an owner removes wax with a low-speed buffer and many clean terry bonnets so as not to burn the clear; an owner uses a D/A polisher and warns that “cleaner”/one-step waxes contain abrasives that can burn through with a standard polisher. an owner: low speed (600 rpm), don’t let the surface get hot, work in shade. an owner: always test first.\"},{\"look\":\"More\",\"action\":\"Waxing a clear-coated Airstream: by hand or with a buffer (cont.) Products: dealer recommendations of Aerospace 303 and Walbernize (an owner; also gandttimes, an owner). DISAGREEMENT: an owner reports the Walbernize website says not to use it on clear coat.\"}]},{\"id\":\"x-where-to-keep-the-weight-distribution-hitch-and-\",\"system\":\"Body & gear\",\"title\":\"Where to keep the weight-distribution hitch and bars when unhitched\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"Owner-reported. Bolt-on holders on the A-frame: an RV bumper-hitch mount (An owner; an owner uses a bolt-on Camco; an owner notes one weighs 11 lb, added to hitch weight); Hitchport stainless holders (An owner, slofoks, who adds a jack cover over it); an owner made one from a Curt 2½\\\" receiver, threaded rod and flat stock, locked with his receiver pin lock. Other habits: set it under the trailer (uraljohn, vwii, an owner); bars in PVC tubes or a front compartment; an owner locks the hitch to the A-frame with a U-lock and short chain. Leave it on the truck? DISAGREEMENT: an owner (Colonial Airstream suggested removing it), owners cite shin injuries, backup sensors and parking-lot damage; mikeinca and an owner keep it in.\"},{\"look\":\"More\",\"action\":\"Where to keep the weight-distribution hitch and bars when unhitched (cont.) uraljohn: Equalizer “Bracket Jackets” cut most of the turning noise; check bar resistance and grease ball and pivots before towing. nwclassic: an open tailgate while coupled can crease the propane cover.\"}]},{\"id\":\"x-seelevel-ii-display-codes-opn-sht-open-short-and\",\"system\":\"Body & gear\",\"title\":\"SeeLevel II display codes (OPN/SHT/Open/Short and related) are also tabulated under 3A.3.3\",\"blurb\":\"Owner-reported. Not a confirmed factory fix. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"What owners and the manuals report\",\"action\":\"SeeLevel II display codes (OPN/SHT/Open/Short and related) are also tabulated under 3A.3.3. Door/screen-door adjustments and Zip Dee spring tension: see 3A.2.5–3A.2.6 and 4.11. Model-specific fault-code tables (Suburban ST, Alde, Coleman, Secop, PD1600) remain in 4.12–4.14. Nev-R-Lube end play: Dexter max axial 0.006 in. for the 42 mm cartridge Airstream uses; Airstream manuals 0.001–0.010 in.. DISAGREEMENT — use the tighter Dexter figure. Full procedure in §3.3 / §3A.1.5.\"}]},{\"id\":\"x-shower-care-heads-and-leaks\",\"system\":\"Plumbing\",\"title\":\"Shower care, shower-head swaps, and finding shower leaks\",\"blurb\":\"Owner-reported. Not a factory specification. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"More\",\"action\":\"Shower care, shower-head swaps, and finding shower leaks (cont.) Leaks: on a 2009 27FB, water reached the floor right after showers. Owners advise filling the pan without splashing the door track or seams to separate pan/drain leaks from door leaks. Common causes reported: the door's bottom gasket or track, a cracked caulk seam in a two-piece shower, or a hidden crack. Dealers and Jackson Center fixed some by re-hanging and re-caulking the door. A leaky shower valve on an older trailer was fixed with new valve washers. Some owners replaced the door with a Velcro-attached curtain; one swapped the stiff wet-bath curtain for a thinner cloth one. A missing shower pan can be replaced with a custom heavy-gauge galvanised-steel pan sprayed with Rhino bedliner; letting shower grey water run onto the ground (e.g. from an outdoor shower) isn't allowed in many places.\"}]},{\"id\":\"x-inverter-generator-loads\",\"system\":\"Electrical\",\"title\":\"What one or two 2,000 W inverter generators will run\",\"blurb\":\"Owner-reported. Not a factory specification. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"More\",\"action\":\"What one or two 2,000 W inverter generators will run (cont.) Battery charging: depends on depth of discharge and loads. The generator's DC outlet is slow; an owner switched to a 3-stage converter (PD4645). one owner’s rule of thumb: charge at no more than about 10% of amp-hour capacity. Buy the \\\"Companion\\\" model as the second unit: it has the 30 A outlet (Goin camping, an owner, an owner).\"}]},{\"id\":\"x-a-frame-flex-and-weight-distribution\",\"system\":\"Running gear\",\"title\":\"A-frame flex, tongue-jack level, and weight-distribution bars\",\"blurb\":\"Owner-reported. Not a factory specification. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"More\",\"action\":\"A-frame (tongue) flex vs bend; checking it; tongue-jack level; WD bar rating debate (cont.) Flex: on longer, heavier units the A-frame flexes under load, and more so the further forward the support point (jack, then coupler, then the WD hitch head). Signs of excessive front flex: the lower front skin bulging above the tongue, and ovalized holes, broken rivets or loose screws along the front arc under the rub rail. Over-tensioning the WD chains can bubble the front skin. Re-zeroing the tongue-jack bubble level: on level ground, level the trailer by the floor, then adjust the level's screws until it reads level.\"},{\"look\":\"More\",\"action\":\"A-frame (tongue) flex vs bend; checking it; tongue-jack level; WD bar rating debate (cont.) Disagreement on WD bar rating: an owner (a dealer) says bars that are too stiff on a stiff truck give the trailer a rough ride and can bend the A-frame, so use lighter bars with a heavier truck. One owner reported a smoother ride and no more sheared interior rivets after loosening one chain link. Hitch makers' posters and others say to size the bars to restore front-axle load (checked on a scale) and follow the hitch maker's instructions. an owner (of hitch maker ProPride) says to use the lightest bar that adequately restores front-axle load. An owner on a 14,745-mile Alaska trip (ProPride, 1000 lb bars, 3/4 ton) saw no damage. The consensus was that this OP's A-frame was not bent, only showing deflection. Excluded: towing with no weight distribution or sway control.\"}]},{\"id\":\"x-pre-2012-rear-bumper-plate-leak\",\"system\":\"Leaks\",\"title\":\"Pre-2012 rear bumper-plate leak\",\"blurb\":\"Owner-reported. Not a factory specification. Your model-year manual still governs.\",\"level\":\"soon\",\"checks\":[{\"look\":\"More\",\"action\":\"Pre-2012 rear bumper-plate leak: fix behind the rub rail (cont.) Do not drill the shell or the insulation to dry a leak. One owner drilled small holes; that is not a fix to copy; dry after heavy rain. an owner raised the tongue, which helped. Burnside Bob posted a sealant list: Sikaflex 221, Parbond, TremPro 635 for trim and rub rail; Acryl-R or Gutterseal for small seams.\"}]},{\"id\":\"x-porcelain-vs-plastic-toilet\",\"system\":\"Plumbing\",\"title\":\"Porcelain versus plastic toilets\",\"blurb\":\"Owner-reported. Not a factory specification. Your model-year manual still governs.\",\"level\":\"watch\",\"checks\":[{\"look\":\"More\",\"action\":\"Porcelain vs plastic toilets: weight, fit and flush (cont.) Plastic bowl care: no abrasive cleaners. Owners use Rain-X or floor wax to help it shed; note that Rain-X's safety data sheet lists it as flammable. A 2018 Classic 33's SeaLand macerating toilet has been praised after two years of full-timing. Composting conversions (Nature's Head, AirHead) are praised for no smell; one owner diverted urine into the black tank, which was joined to the grey. Old Thetford Galaxy: a slow-leaking flush-valve seal means the bowl won't hold water; use the rebuild kit. Flood risk: a failed toilet valve on city water can flood the floor. When leaving the trailer, turn off city water and use the tank and pump.\"}]}]");
